_FILES['config.py'] = '"""\nConfiguration — Indiana Accident Forecaster v2 (county-based).\n\nSpatial unit: county. The baseline layer is EMS-derived motor-vehicle\ninjury opportunity (data/county_opportunity.csv, built from Indiana Data\nHub EMS incidents with severity weighting). The top DYNAMIC_N counties by\nopportunity get live weather + incident monitoring; the long tail stays at\nits static baseline.\n"""\n\nCOUNTY_CSV = "data/county_opportunity.csv"\nPHASE2_PRIORITY_CSV = "data/phase2_metro_priority.csv"\nPHASE2_EFFICIENCY_CSV = "data/phase2_cluster_metro_efficiency.csv"\n\nDYNAMIC_N = 92  # all counties get live weather (Open-Meteo requests are\n#   batched: one call covers every county, so statewide costs the same as\n#   25 did). Incidents are county-assigned statewide via boundary polygons.\n\n# FALLBACK county centroids (lat, lon), used for weather sampling and\n# nearest-county incident assignment only when the county-boundary\n# download fails; normally all 92 centroids are derived from the\n# boundary polygons at runtime.\nCOUNTY_CENTROIDS = {\n    "Marion": (39.78, -86.14), "Allen": (41.09, -85.07),\n    "Lake": (41.42, -87.37), "Hamilton": (40.07, -86.05),\n    "Elkhart": (41.60, -85.87), "St. Joseph": (41.62, -86.29),\n    "Tippecanoe": (40.39, -86.89), "Hendricks": (39.77, -86.51),\n    "Vanderburgh": (38.02, -87.59), "Bartholomew": (39.20, -85.90),\n    "Johnson": (39.49, -86.10), "Delaware": (40.23, -85.40),\n    "Porter": (41.46, -87.07), "Madison": (40.16, -85.72),\n    "Kosciusko": (41.24, -85.86), "Monroe": (39.16, -86.52),\n    "Hancock": (39.82, -85.77), "Noble": (41.40, -85.42),\n    "Vigo": (39.43, -87.39), "Cass": (40.76, -86.35),\n    "Boone": (40.05, -86.47), "Lagrange": (41.64, -85.43),\n    "Marshall": (41.32, -86.26), "Jackson": (38.91, -86.04),\n    "Laporte": (41.55, -86.74),\n}\n\n# County -> Phase 2 metro mapping (for blending with the static search-\n# economics shares). Counties not listed roll into "other_in".\nCOUNTY_TO_METRO = {\n    "Marion": "indianapolis", "Hamilton": "indianapolis",\n    "Hendricks": "indianapolis", "Johnson": "indianapolis",\n    "Boone": "indianapolis", "Hancock": "indianapolis",\n    "Madison": "indianapolis", "Morgan": "indianapolis",\n    "Shelby": "indianapolis",\n    "Allen": "fortwayne", "Whitley": "fortwayne", "Wells": "fortwayne",\n    "Noble": "fortwayne", "Dekalb": "fortwayne", "Huntington": "fortwayne",\n    "Lake": "nwindiana", "Porter": "nwindiana", "Laporte": "nwindiana",\n    "Jasper": "nwindiana", "Newton": "nwindiana",\n    "St. Joseph": "southbend", "Elkhart": "southbend",\n    "Marshall": "southbend", "Kosciusko": "southbend",\n    "Lagrange": "southbend",\n    "Tippecanoe": "lafayette", "Clinton": "lafayette",\n    "White": "lafayette", "Carroll": "lafayette",\n    "Vanderburgh": "evansville", "Warrick": "evansville",\n    "Posey": "evansville", "Gibson": "evansville",\n}\n\nOPEN_METEO_URL = "https://api.open-meteo.com/v1/forecast"\n\n# --- 511in.org live incidents ---------------------------------------------\n# Primary: the same GraphQL endpoint the public 511in.org map uses (verified\n# via browser DevTools, July 2026). Anonymous requests are attempted first;\n# the site\'s own map issues short-lived visitor tokens, so nothing is\n# hardcoded here. Statewide bbox; server-side clusters are drilled into by\n# re-querying each cluster\'s bbox at its maxZoom+1 (bounded by\n# GRAPHQL_MAX_REQUESTS per run).\nGRAPHQL_URL = "https://511in.org/api/graphql"\nGRAPHQL_LAYERS = ["incidents"]\nSTATE_BBOX = {"north": 41.95, "south": 37.65, "east": -84.55, "west": -88.25}\nGRAPHQL_MAX_REQUESTS = 25\n\n# Legacy fallbacks (kept for graceful degradation; the api/v2 endpoint is\n# the IBI-platform standard used by other states and is NOT expected to\n# work for Indiana — see [warn] lines in logs).\nTRAFFICWISE_EVENTS_URLS = [\n    "https://511in.org/api/v2/get/event?format=json",\n    "https://content.trafficwise.org/json/cars.json",\n]\nTRAFFICWISE_API_KEY = None  # legacy; unused unless api/v2 ever works\n\n# --- TomTom Traffic Incidents (local-road coverage) ------------------------\n# Blended with 511. 511\'s real gap is geography (INDOT-managed roads only);\n# TomTom\'s probe data adds local-road incidents statewide. Requires a free\n# TomTom developer key stored as the TOMTOM_API_KEY GitHub Actions secret\n# (the workflow exports it as an env var). If the env var is absent the\n# feed is skipped and everything runs exactly as before.\nTOMTOM_URL = "https://api.tomtom.com/traffic/services/5/incidentDetails"\nTOMTOM_TILE_MAX_KM2 = 9750  # API bbox cap is 10,000 km^2; safety margin.\n#   The fetcher solves for the fewest tiles that stay under this\n#   (16 for Indiana\'s bbox vs 20 with the old fixed 1-degree grid) and\n#   skips tiles that don\'t overlap any Indiana county.\nTOMTOM_MAX_REQUESTS = 24   # hard per-run cap, belt-and-suspenders\n# TomTom snapshot cache: incidents there are long-lived (jams, closures,\n# roadwork persist for hours), so between refreshes the last statewide\n# snapshot is reused — the layer never goes blank, requests drop ~60%.\n# Fast-moving crash reports are covered by the 5-minute 511 polls.\nTOMTOM_REFRESH_DAY_MIN = 35     # refetch when snapshot older (6am-10pm)\nTOMTOM_REFRESH_NIGHT_MIN = 65   # overnight traffic changes slowly\nTOMTOM_DEDUP_KM = 1.5      # drop TomTom events this close to a 511 event\n\n# --poll-loop: sub-cron sampling inside one Actions job. Crashes live a\n# median ~15 min on 511 (many <10), so 5-minute cron alone misses the\n# short tail — and GitHub\'s scheduler is best-effort besides. One 511\n# sweep per ~65 s matches the refresh rate of a single browser tab left\n# open on 511in.org\'s own map — but pending the firm\'s 511 ToS review,\n# we deliberately run WELL below that: two sweeps per 5-min job\n# (interval 210 s -> sweeps at t=0 and t=3.5 min), i.e. effective\n# ~3.5-min sampling. Vs single-shot polling this closes most of the\n# short-listing tail AND halves the damage of any cron slot GitHub\n# drops. Raise cadence only after the ToS review clears it.\nPOLL_LOOP_SECONDS = 240    # loop budget; leaves ~1 min of the 5-min\n#   slot for job setup + the commit step, so jobs don\'t pile up\nPOLL_LOOP_INTERVAL = 210   # seconds between 511 sweeps inside the loop\n\n# Stale-crash cap. 511 occasionally never clears a crash entry (seen: a\n# Shelby County semi crash listed \'live\' for 6 straight days, Aug 2026).\n# Real crashes clear within hours, so past this age a live \'crash\' is\n# treated as a stale listing: live weight cut to CRASH_STALE_WEIGHT of\n# itself, popup labeled, and trailing decay computed as if the event\n# ended at first_seen + cap (so a ghost can\'t also haunt the trailing\n# model for days after the feed finally clears it). Crash-only: real\n# closures/roadwork legitimately persist for weeks and are untouched.\nCRASH_LIVE_MAX_H = 12\nCRASH_STALE_WEIGHT = 0.1\n\n# Trailing (fading) events leave the map/model entirely past this age —\n# the importance floor alone let high-magnitude crashes linger ~12 days,\n# contradicting the ~2-day-fade story the map tells. 96 h = two full\n# half-lives (weight <= 25%) and matches what the display promises.\nTRAIL_MAX_AGE_H = 96\n\n# If the GitHub Actions poller is set up, its raw incident-history URL,\n# e.g. "https://raw.githubusercontent.com/USER/REPO/main/incident_history.json"\n# Colab runs will merge this machine-built archive into local memory.\nINCIDENT_LOG_URL = None\n\n# Weather multipliers (FHWA road-weather program; Qiu & Nixon 2008;\n# Theofilatos & Yannis 2014 — conservative midpoints).\nWEATHER_MULTIPLIERS = {\n    "rain_light": 1.25, "rain_moderate": 1.5, "rain_heavy": 1.8,\n    "snow_light": 1.5, "snow_moderate": 1.8, "snow_heavy": 2.2,\n    "freezing_precip": 2.5, "fog": 1.4, "darkness": 1.25, "high_wind": 1.15,\n}\nMAX_MULTIPLIER = 3.5\nINCIDENT_BOOST_PER_EVENT = 0.10   # +10% county risk per unit of\n#   severity-weighted live activity: crash=1.0, closure/hazard=0.6,\n#   stalled=0.4, congestion=0.3, roadwork=0.15, \'reopened\'=ignored.\n#   See EVENT_WEIGHTS in sources.py.\n# Collisions vs contributing factors: only events with weight >= this get\n# a map marker. 1.0 = crashes only (incl. "road closed due to crash",\n# which classifies as crash). Lower to 0.6 to also mark hazards (ice,\n# flooding, spills). Everything below the bar still shades its county\'s\n# color and is itemized in the county click-panel.\nMAP_MIN_MARKER_WEIGHT = 1.0\n# Events below this weight never enter trailing memory (roadwork and\n# congestion have near-zero trailing signal but would bloat\n# incident_history.json now that TomTom reports them statewide).\nMEMORY_MIN_WEIGHT = 0.4\n\n# --- long-term crash ledger (learned county baselines) ----------------------\n# Every crash the feeds ever record is tallied by county+month inside\n# incident_history.json (key "_ledger"). Once the statewide sample passes\n# LEDGER_MIN_TOTAL, observed county shares gently adjust the EMS baseline\n# via an empirical-Bayes factor; PRIOR_K shrinks small samples toward 1.0\n# and CAP bounds the effect (the feeds over-represent highways and metro\n# roads, so the EMS baseline must remain the anchor).\n# --- vehicle-type county badges ---------------------------------------------\n# Truck involvement IS visible in feed text ("semi", "jackknifed", ...) so\n# 🚛 badges are learned from the crash archive once a county has enough\n# data. (Rideshare badges were removed in v9.7: rideshare involvement is\n# never visible in any traffic feed, so the map cannot honestly claim it.)\nTRUCK_KEYWORDS = ("semi", "tractor trailer", "tractor-trailer", "jackknif",\n                  "big rig", "18 wheeler", "18-wheeler", "commercial vehicle",\n                  " cmv", "box truck", "dump truck", "truck")\nTRUCK_BADGE_MIN_N = 5         # crashes (baseline + archive) before judging\n# Truck badges are RELATIVE: a county is truck-prone if its truck share is\n# at least TRUCK_BADGE_REL x the STATEWIDE share computed from the same\n# blended (baseline + archive) data, with a small absolute floor. A fixed\n# share threshold flickered — one ordinary crash could drag a small county\n# across the line and back day to day; comparing every county to the same\n# statewide yardstick keeps the designation stable and meaningful.\nTRUCK_BADGE_REL = 1.5         # x statewide truck share to earn the badge\nTRUCK_BADGE_FLOOR = 0.08      # absolute floor if statewide share is tiny\n# Official background data: drop a baseline_crashes.csv in the repo root\n# (columns: county,total_crashes,truck_crashes — from the ICJI/IU-PPI\n# ARIES county profiles) and badges blend it with the live archive.\nBASELINE_CRASH_CSV = "baseline_crashes.csv"\nTRUCK_COUNTIES_MANUAL: list[str] = []      # e.g. ["Jasper", "Newton"]\n\nLEDGER_MIN_TOTAL = 300\nLEDGER_PRIOR_K = 25.0\nLEDGER_CAP = (0.75, 1.30)\n\nTRAILING_BOOST_PER_POINT = 0.05   # +5% per point of decayed trailing weight\nINCIDENT_BOOST_CAP = 1.75         # cap on combined live + trailing boost\nTRAILING_HALF_LIFE_H = 48         # trailing importance halves every 48 h\n\n# Hour-of-week exposure fallback (INDOT diurnal shape). Upgrade path: learn\n# this empirically from EMS run timestamps if a filtered extract with a\n# datetime column is provided.\nWEEKDAY_HOURLY = [0.25,0.15,0.12,0.12,0.25,0.6,1.3,1.9,1.6,1.2,1.15,1.25,\n                  1.35,1.35,1.5,1.8,2.0,2.1,1.6,1.1,0.85,0.7,0.55,0.4]\nWEEKEND_HOURLY = [0.45,0.3,0.25,0.15,0.15,0.25,0.45,0.7,1.0,1.3,1.5,1.6,\n                  1.65,1.6,1.55,1.5,1.45,1.4,1.3,1.1,0.95,0.8,0.7,0.55]\n\n# Budget blending: forecast may move up to this fraction of allocation away\n# from the static Phase 2 shares.\nDYNAMIC_WEIGHT = 0.35\nSTATIC_SHARES = {\n    "indianapolis": 0.50, "fortwayne": 0.15, "nwindiana": 0.13,\n    "southbend": 0.10, "lafayette": 0.06, "evansville": 0.06,\n}\n\n\n# --- v7: location grit, commuter spillover, feed-coverage grades ---------\nSPILLOVER_FRAC = 0.25    # share of a county\'s crash evidence credited to\nSPILLOVER_TOP_K = 8      # commuter home counties (Census LODES), top-K homes\nLEDGER_POINTS_MAX = 4000  # archived crash locations kept (oldest dropped)\nHOTSPOT_CELL_DEG = 0.004  # ~400 m grid cell for hotspot clustering\nHOTSPOT_MIN_N = 3         # archived crashes in a cell before a pin appears\n# Hotspots are judged inside a trailing window, not over the archive\'s\n# lifetime: with years of data, virtually every busy interchange would\n# eventually cross a fixed lifetime bar, and \'hotspot\' would stop\n# meaning anything. A pin (and public-page qualification) requires the\n# threshold to be met by crashes within the last HOTSPOT_WINDOW_D days;\n# older points stay in the ledger and monthly tallies but age out of\n# hotspot arithmetic. 120 d ~ a season: long enough for the recurrence\n# gates to fill at current capture rates, short enough to mean \'now\'.\nHOTSPOT_WINDOW_D = 120\n\n# Risky SEGMENTS (corridors): hotspots catch one bad ~400 m cell, but long\n# highways often have a several-km stretch that\'s contentious without any\n# single cell crossing the hotspot bar. Windowed crash points on the same\n# road are chained when consecutive points are within SEGMENT_LINK_KM;\n# a chain with >= SEGMENT_MIN_N crashes spanning >= SEGMENT_MIN_KM is a\n# risky segment (shorter dense chains are the hotspot feature\'s job).\nSEGMENT_MIN_N = 5      # crashes required along one corridor (window)\nSEGMENT_LINK_KM = 3.0  # max gap between chained crashes on the same road\nSEGMENT_MIN_KM = 2.0   # min corridor span; below this it\'s a hotspot\nSEGMENT_MAX = 12       # cap drawn/reported segments per build\nCOVERAGE_MIN_EXPECTED = 5.0  # expected crashes needed to grade a county\n\n# --- v8: source health, degraded mode, fair coverage tiers ---------------\nHEALTH_MAX = 600          # per-run source-health entries kept (~2 days)\nDEGRADED_AFTER = 4        # consecutive 511-silent runs => degraded mode\nCOVERAGE_TIERS = 4        # county size tiers for peer-fair coverage grades\nTREND_MIN_N = 5           # min expected crashes before a trend is called\n\n# --- v9: public Road Safety Watch + policymaker Action Brief -------------\n# Lean protocol gates for the PUBLIC drafts (output/safety_watch_draft.html\n# and output/action_brief_draft.html). A location publishes only with\n# recurrence across distinct days, a real road name, and non-F coverage.\nPUB_MIN_N = 3            # archived crashes at a location (>= hotspot bar)\nPUB_MIN_DAYS = 3         # crashes on this many DISTINCT days (recurrence)\nPUB_MAX_LOCATIONS = 10   # cap per report (protocol: 5-10 locations)\n\n# --- v10: tiered publication gates ---------------------------------------\n# The ~400 m cell above is a very small target. Measured on a 550-crash\n# archive the points landed in ~520 distinct cells with only 4 reaching\n# n>=3, so the reports were empty despite a substantial archive: the gate\n# was asking for recurrence at a scale the sample cannot supply yet, and\n# the empty-state note then told the reader we lacked data. We do not —\n# we lacked the right unit of analysis.\n#\n# CORRIDOR and ROAD tiers add the two larger scales at which recurrence\n# is genuinely observable at this sample size. Both still demand\n# repetition across DISTINCT DAYS, which is the gate that actually\n# separates a pattern from one bad afternoon; neither relaxes it.\n# Corridor geometry itself is defined by the SEGMENT_* constants above.\nPUB_CORRIDOR_MIN_N = 6     # crashes chained along one road (>= SEGMENT_MIN_N)\nPUB_CORRIDOR_MIN_DAYS = 5  # on this many distinct days\nPUB_ROAD_MIN_N = 8         # crashes on one named road within one county\nPUB_ROAD_MIN_DAYS = 6      # on this many distinct days (weakest tier, so\n#                            the recurrence bar is the highest of the three)\n# Archive size below which the reports say "still filling" rather than\n# "nothing is recurring". Above it, an empty report is a FINDING about\n# the road network, not a complaint about the sample, and the pages now\n# say so. Set at the ledger\'s own learning threshold so the whole system\n# agrees on when the archive has become usable.\nPUB_MIN_ARCHIVE = LEDGER_MIN_TOTAL\n# Report slots held for spot-tier findings when more candidates qualify\n# than fit. Pinpointed spots are the most actionable output we produce\n# and are always outnumbered by corridors.\nPUB_RESERVE_SPOTS = 4\n\n# --- v9.1: everything in Indiana local time -----------------------------\n# GitHub Actions runners are UTC, so naive datetime.now() stamped every\n# archive entry 4-5 h ahead of Indiana. All modules now stamp and\n# display naive LOCAL time via local_now(). Pre-v9.1 archived\n# timestamps were UTC and are left as-is (a one-time skew that fades\n# out of trailing memory within ~2 days; ledger month tallies are\n# unaffected except within hours of midnight).\nimport datetime as _dt\ntry:\n    from zoneinfo import ZoneInfo as _ZoneInfo\n    TZ = _ZoneInfo("America/Indiana/Indianapolis")\nexcept Exception:  # noqa: BLE001\n    TZ = None\n\n\ndef local_now():\n    """Naive Indiana-local datetime (falls back to system time if\n    tz data is unavailable)."""\n    return (_dt.datetime.now(TZ).replace(tzinfo=None) if TZ\n            else _dt.datetime.now())\n'
_FILES['sources.py'] = '"""\nData connectors (v2): county opportunity table, batched Open-Meteo\nforecasts for the dynamic counties, 511/CARS live incidents.\n\nAll network connectors degrade gracefully to neutral values so a\nscheduled run always completes.\n"""\nfrom __future__ import annotations\n\nimport datetime as dt\nimport math\nimport os\nimport sys\n\nimport pandas as pd\nimport requests\n\nimport config\n\n\n_ROAD_RE = None\n\n\ndef extract_road(text: str) -> str:\n    """Best-effort road / street name(s) from an incident title+tooltip,\n    e.g. \'I-65\', \'US 31\', \'SR 37\', \'38th St\', \'Keystone Ave\'. Up to two\n    distinct names joined with \' / \' (crash at an intersection)."""\n    global _ROAD_RE\n    import re as _re\n    if _ROAD_RE is None:\n        _ROAD_RE = _re.compile(\n            r"\\b(?:I|US|SR|IN|CR)[- ]?\\d{1,3}[A-Z]?\\b"\n            r"|\\b\\d{1,3}(?:st|nd|rd|th)\\s"\n            r"(?:Rd|Road|St|Street|Ave|Avenue|Blvd|Boulevard)\\b"\n            r"|\\b[A-Z][A-Za-z.\'\\u2019]{2,}(?:\\s[A-Z][A-Za-z.\'\\u2019]+)?\\s"\n            r"(?:Rd|Road|St|Street|Ave|Avenue|Blvd|Boulevard|Pkwy|Parkway|"\n            r"Hwy|Highway|Dr|Drive|Ln|Lane|Pike|Trace|Trl|Trail)\\b")\n    seen, out = set(), []\n    for m in _ROAD_RE.finditer(str(text or "")):\n        r = " ".join(m.group(0).split())\n        k = r.lower().replace("-", " ")\n        if k not in seen:\n            seen.add(k)\n            out.append(r)\n        if len(out) == 2:\n            break\n    return " / ".join(out)\n\n\ndef load_counties() -> pd.DataFrame:\n    df = pd.read_csv(config.COUNTY_CSV)\n    df["county"] = df["county"].astype(str).str.strip()\n    if "weighted_score" in df.columns and "opportunity_score" in df.columns:\n        # Retire the synthetic viability multiplier (opportunity_score was\n        # weighted_score * (0.5 + viability); viability itself derived from\n        # a synthetic pct_non_english column built in early prototyping).\n        # Anchor purely on the EMS-derived weighted_score and re-rank.\n        df["opportunity_score"] = df["weighted_score"].astype(float)\n        df = df.sort_values("opportunity_score",\n                            ascending=False).reset_index(drop=True)\n        if "rank" in df.columns:\n            df["rank"] = range(1, len(df) + 1)\n        df = df.drop(columns=[c for c in ("viability", "pct_non_english")\n                              if c in df.columns])\n        print("[info] synthetic viability/pct_non_english columns retired: "\n              "opportunity_score = EMS weighted_score "\n              f"({len(df)} counties re-ranked)")\n    df["dynamic"] = False\n    dyn = df.nlargest(config.DYNAMIC_N, "opportunity_score")["county"]\n    df.loc[df["county"].isin(dyn), "dynamic"] = True\n    df["metro"] = df["county"].map(config.COUNTY_TO_METRO).fillna("other_in")\n    return df\n\n\n# ---------------------------------------------------------------------------\n# Weather — one batched request for all dynamic counties\n# ---------------------------------------------------------------------------\nHOURLY_VARS = ["precipitation", "snowfall", "temperature_2m", "visibility",\n               "wind_gusts_10m", "is_day", "weather_code"]\n\n\ndef county_centroids(geodata, county_names) -> dict:\n    """{canonical county name: (lat, lon)} for all counties, derived from\n    the boundary polygons; falls back to the hand-entered top-25 table\n    when boundaries are unavailable."""\n    if not geodata:\n        return dict(config.COUNTY_CENTROIDS)\n    canon = {_norm_name(n): n for n in (county_names or [])}\n    out = {}\n    for fips, cen in (geodata.get("centroids") or {}).items():\n        name = geodata["fips_to_name"].get(fips, fips)\n        out[canon.get(_norm_name(name), name)] = cen\n    return out or dict(config.COUNTY_CENTROIDS)\n\n\ndef fetch_weather(hours: int = 48,\n                  centroids: dict | None = None) -> dict[str, pd.DataFrame]:\n    cents = centroids or config.COUNTY_CENTROIDS\n    names = list(cents)\n    lats = ",".join(str(cents[n][0]) for n in names)\n    lons = ",".join(str(cents[n][1]) for n in names)\n    params = {\n        "latitude": lats, "longitude": lons,\n        "hourly": ",".join(HOURLY_VARS),\n        "forecast_days": min(7, max(1, math.ceil(hours / 24))),\n        "timezone": "America/Indiana/Indianapolis",\n    }\n    out = {}\n    try:\n        r = requests.get(config.OPEN_METEO_URL, params=params, timeout=30)\n        r.raise_for_status()\n        payload = r.json()\n        if isinstance(payload, dict):  # single-location fallback\n            payload = [payload]\n        for name, loc in zip(names, payload):\n            df = pd.DataFrame(loc["hourly"])\n            df["time"] = pd.to_datetime(df["time"])\n            df = df.set_index("time").iloc[:hours]\n            df["freezing_precip_flag"] = df["weather_code"].isin(\n                [56, 57, 66, 67])\n            out[name] = df\n    except Exception as e:  # noqa: BLE001\n        print(f"[warn] weather fetch failed ({e}); using neutral weather.",\n              file=sys.stderr)\n    for name in names:  # fill any gaps\n        out.setdefault(name, neutral_weather(hours))\n    return out\n\n\ndef neutral_weather(hours: int) -> pd.DataFrame:\n    idx = pd.date_range(dt.datetime.now().replace(minute=0, second=0,\n                                                  microsecond=0),\n                        periods=hours, freq="h")\n    return pd.DataFrame({\n        "precipitation": 0.0, "snowfall": 0.0, "temperature_2m": 15.0,\n        "visibility": 20000.0, "wind_gusts_10m": 10.0, "is_day": 1,\n        "weather_code": 0, "freezing_precip_flag": False,\n    }, index=idx)\n\n\ndef weather_multiplier(row: pd.Series) -> float:\n    m = config.WEATHER_MULTIPLIERS\n    mult = 1.0\n    snow = row.get("snowfall", 0.0)        # cm/h\n    rain = row.get("precipitation", 0.0)   # mm/h\n    if row.get("freezing_precip_flag", False) or (\n            rain > 0.1 and row.get("temperature_2m", 15) <= 0):\n        mult *= m["freezing_precip"]\n    elif snow > 2.5:\n        mult *= m["snow_heavy"]\n    elif snow > 1.0:\n        mult *= m["snow_moderate"]\n    elif snow > 0.1:\n        mult *= m["snow_light"]\n    elif rain > 7.6:\n        mult *= m["rain_heavy"]\n    elif rain > 2.5:\n        mult *= m["rain_moderate"]\n    elif rain > 0.1:\n        mult *= m["rain_light"]\n    if row.get("visibility", 20000) < 1000:\n        mult *= m["fog"]\n    if not row.get("is_day", 1):\n        mult *= m["darkness"]\n    if row.get("wind_gusts_10m", 0) > 40:\n        mult *= m["high_wind"]\n    return min(mult, config.MAX_MULTIPLIER)\n\n\n# ---------------------------------------------------------------------------\n# Live incidents -> per-county active event counts\n# ---------------------------------------------------------------------------\n# Substance-based event classification. Order matters: first match wins.\n# weight 0.0 = not a risk signal at all (dropped entirely: no boost, no\n# marker, no memory).\nEVENT_WEIGHTS = [\n    ("reopened/cleared", 0.0, (\n        "back open", "reopened", "re-opened", "all lanes open",\n        "has been cleared", "now open", "open to traffic", "has ended")),\n    ("crash", 1.0, (\n        "crash", "accident", "collision", "overturned", "jackknif",\n        "pileup", "multi vehicle", "multi-vehicle", "rollover")),\n    ("stalled/disabled", 0.4, (\n        "stalled", "disabled vehicle", "vehicle fire", "abandoned vehicle")),\n    ("closure/hazard", 0.6, (\n        "road closed", "ramp closed", "bridge closed", "closed in both",\n        "closure", "hazmat", "spill", "debris", "flood", "high water",\n        "fire", "downed", "ice", "snow covered")),\n    ("congestion", 0.3, (\n        "slow traffic", "congestion", "delay", "stopped traffic",\n        "heavy traffic", "backup")),\n    ("roadwork", 0.15, (\n        "construction", "roadwork", "road work", "maintenance",\n        "restriction", "lane closed", "lane closure", "paving",\n        "bridge work", "mowing", "utility work", "shoulder work")),\n]\nDEFAULT_EVENT_CATEGORY = ("other", 0.3)\n\n\ndef classify_event(text: str) -> tuple[str, float]:\n    """(category, risk weight) from an event\'s title + description."""\n    t = str(text).lower()\n    for cat, w, kws in EVENT_WEIGHTS:\n        if any(k in t for k in kws):\n            return cat, w\n    return DEFAULT_EVENT_CATEGORY\n\n\ndef _norm_bbox(cb):\n    """Cluster bbox -> (north, south, east, west); tolerates dict or\n    GeoJSON-style [west, south, east, north] list."""\n    if isinstance(cb, dict):\n        return (float(cb["north"]), float(cb["south"]),\n                float(cb["east"]), float(cb["west"]))\n    w, s, e, n = (float(x) for x in cb)\n    return (n, s, e, w)\n\n\ndef _feature_point(mf):\n    """First usable (lat, lon) from a mapFeature\'s GeoJSON geometries."""\n    for feat in (mf.get("features") or []):\n        g = feat.get("geometry") or {}\n        t, c = g.get("type"), g.get("coordinates")\n        if not c:\n            continue\n        if t == "Point":\n            return (float(c[1]), float(c[0]))\n        if t in ("MultiPoint", "LineString"):\n            return (float(c[0][1]), float(c[0][0]))\n        if t in ("MultiLineString", "Polygon"):\n            return (float(c[0][0][1]), float(c[0][0][0]))\n    return None\n\n\ndef _graphql_map_features(session, bbox, zoom):\n    """One MapFeatures query against the 511in.org GraphQL endpoint."""\n    payload = {\n        "query": (\n            "query MapFeatures($input: MapFeaturesArgs!) {"\n            " mapFeaturesQuery(input: $input) { mapFeatures {"\n            " bbox title tooltip uri"\n            " features { id geometry properties }"\n            " ... on Cluster { maxZoom } ... on Event { priority }"\n            " __typename } error { message type } } }"),\n        "variables": {"input": {\n            "north": bbox[0], "south": bbox[1],\n            "east": bbox[2], "west": bbox[3],\n            "zoom": zoom, "layerSlugs": config.GRAPHQL_LAYERS,\n            "nonClusterableUris": ["dashboard"],\n        }},\n    }\n    r = session.post(config.GRAPHQL_URL, json=payload, timeout=20)\n    r.raise_for_status()\n    data = r.json()\n    if data.get("errors"):\n        raise RuntimeError(str(data["errors"])[:200])\n    q = (data.get("data") or {}).get("mapFeaturesQuery") or {}\n    if q.get("error"):\n        raise RuntimeError(str(q["error"])[:200])\n    return q.get("mapFeatures") or []\n\n\ndef _fetch_incidents_graphql():\n    """Statewide incident list from the 511in.org public-map GraphQL API.\n    Anonymous request (the same data the public map shows). Clusters are\n    drilled into recursively via their bbox/maxZoom."""\n    session = requests.Session()\n    session.headers.update({\n        "User-Agent": "Mozilla/5.0",\n        "Origin": "https://511in.org",\n        "Referer": "https://511in.org/",\n        "language": "en",\n    })\n    events, seen = [], set()\n    budget = [config.GRAPHQL_MAX_REQUESTS]\n\n    def visit(bbox, zoom):\n        if budget[0] <= 0:\n            return\n        budget[0] -= 1\n        for mf in _graphql_map_features(session, bbox, zoom):\n            if mf.get("__typename") == "Cluster":\n                cb = mf.get("bbox")\n                try:\n                    nz = min(int(mf.get("maxZoom") or zoom + 2) + 1, 15)\n                except (TypeError, ValueError):\n                    nz = min(zoom + 2, 15)\n                if cb and nz > zoom:\n                    visit(_norm_bbox(cb), nz)\n                continue\n            uri = mf.get("uri") or ""\n            if uri and uri in seen:\n                continue\n            seen.add(uri)\n            pt = _feature_point(mf)\n            if pt is None:\n                continue\n            tooltip = str(mf.get("tooltip") or "")\n            title = str(mf.get("title") or "event")\n            cat, w = classify_event(title + " " + tooltip)\n            if w <= 0:\n                continue  # e.g. "road back open" — not a risk signal\n            events.append({\n                "id": uri or None,\n                "lat": pt[0], "lon": pt[1],\n                "type": title[:80],\n                "desc": tooltip[:160],\n                "category": cat, "weight": w,\n                "severity": None,\n                "full_closure": "closed" in tooltip.lower(),\n            })\n\n    visit((config.STATE_BBOX["north"], config.STATE_BBOX["south"],\n           config.STATE_BBOX["east"], config.STATE_BBOX["west"]), 11)\n    return events\n\n\ndef _fetch_incidents_legacy():\n    """Old IBI-style JSON endpoints, kept as a fallback."""\n    for url in config.TRAFFICWISE_EVENTS_URLS:\n        if config.TRAFFICWISE_API_KEY and "api/v2" in url:\n            url += "&key=" + config.TRAFFICWISE_API_KEY\n        try:\n            r = requests.get(url, timeout=20,\n                             headers={"User-Agent": "Mozilla/5.0"})\n            r.raise_for_status()\n            raw = r.json()\n            items = raw if isinstance(raw, list) else raw.get("events", [])\n        except Exception as e:  # noqa: BLE001\n            print(f"[warn] legacy event feed failed: {url.split(\'?\')[0]} "\n                  f"({e})", file=sys.stderr)\n            continue\n        events = []\n        for ev in items:\n            lat = ev.get("latitude") or ev.get("lat") or ev.get("Latitude")\n            lon = ev.get("longitude") or ev.get("lon") or ev.get("Longitude")\n            if lat is None or lon is None:\n                continue\n            etype = str(ev.get("type") or ev.get("EventType") or "event")\n            sub = ev.get("Subtype") or ev.get("EventSubType") or ""\n            desc = str(ev.get("Description") or "")[:160]\n            cat, w = classify_event(f"{etype} {sub} {desc}")\n            if w <= 0:\n                continue\n            events.append({\n                "id": ev.get("id") or ev.get("ID"),\n                "lat": float(lat), "lon": float(lon),\n                "type": f"{etype} {sub}".strip(),\n                "desc": desc, "category": cat, "weight": w,\n                "severity": ev.get("Severity"),\n                "full_closure": bool(ev.get("IsFullClosure")),\n            })\n        return events\n    return None\n\n\n# TomTom iconCategory -> (category, weight). Weather-condition warnings\n# (fog / rain / wind) are weighted 0.0 because the weather multiplier\n# already models conditions — counting them again would double-dip.\nTOMTOM_ICON_CATEGORIES = {\n    1: ("crash", 1.0),\n    3: ("closure/hazard", 0.6), 5: ("closure/hazard", 0.6),\n    8: ("closure/hazard", 0.6), 11: ("closure/hazard", 0.6),\n    14: ("stalled/disabled", 0.4),\n    6: ("congestion", 0.3),\n    7: ("roadwork", 0.15), 9: ("roadwork", 0.15),\n    2: ("weather-warning", 0.0), 4: ("weather-warning", 0.0),\n    10: ("weather-warning", 0.0),\n}\n\n_TOMTOM_FIELDS = ("{incidents{type,geometry{type,coordinates},properties{"\n                  "id,iconCategory,magnitudeOfDelay,roadNumbers,"\n                  "events{description,iconCategory}}}}")\n\n\ndef _tomtom_point(geom):\n    """First (lat, lon) from a TomTom incident geometry (Point or\n    LineString; coordinates are [lon, lat])."""\n    c = (geom or {}).get("coordinates")\n    if not c:\n        return None\n    t = (geom or {}).get("type")\n    if t == "Point":\n        return (float(c[1]), float(c[0]))\n    if t in ("LineString", "MultiPoint"):\n        return (float(c[0][1]), float(c[0][0]))\n    if t == "MultiLineString":\n        return (float(c[0][0][1]), float(c[0][0][0]))\n    return None\n\n\ndef _fetch_incidents_tomtom(poly_index=None) -> list[dict]:\n    """Statewide incidents from the TomTom Traffic Incident Details API\n    (v5). The API caps each request\'s bbox at ~10,000 km^2, so the state\n    bbox is tiled with the FEWEST tiles that fit under the cap (16 for\n    Indiana vs 20 with a naive 1-degree grid), and tiles that don\'t\n    overlap any Indiana county are skipped. Returns [] when\n    TOMTOM_API_KEY is not set."""\n    key = os.environ.get("TOMTOM_API_KEY", "").strip()\n    if not key:\n        print("[info] TOMTOM_API_KEY not set; skipping TomTom feed")\n        return []\n    b = config.STATE_BBOX\n    span_lat = b["north"] - b["south"]\n    span_lon = b["east"] - b["west"]\n    lat_km = 111.0\n    # worst case: longitude degrees are widest at the SOUTHERN edge, so\n    # size tiles for that row and every row stays under the area cap\n    lon_km = 111.0 * math.cos(math.radians(b["south"]))\n    rows, cols = 5, 4  # safe fallback\n    for total in range(1, 65):\n        # tile area depends only on the tile count; pick the squarest\n        # rows x cols split so tiles skip out-of-state area effectively\n        km2 = (span_lat * lat_km) * (span_lon * lon_km) / total\n        if km2 > config.TOMTOM_TILE_MAX_KM2:\n            continue\n        splits = [(r_, total // r_) for r_ in range(1, total + 1)\n                  if total % r_ == 0]\n        rows, cols = min(splits, key=lambda rc: abs(\n            span_lat / rc[0] * lat_km - span_lon / rc[1] * lon_km))\n        break\n    step_lat, step_lon = span_lat / rows, span_lon / cols\n    tiles = []\n    for i in range(rows):\n        for j in range(cols):\n            s_ = b["south"] + i * step_lat\n            w_ = b["west"] + j * step_lon\n            n_, e_ = s_ + step_lat, w_ + step_lon\n            if poly_index and not any(\n                    cs <= n_ and cn >= s_ and cw <= e_ and ce >= w_\n                    for _nm, (cs, cn, cw, ce), _gm in poly_index):\n                continue  # tile entirely outside Indiana counties\n            tiles.append((s_, w_, n_, e_))\n    events, seen, tile_fails = [], set(), 0\n    for (s_, w_, n_, e_) in tiles[:config.TOMTOM_MAX_REQUESTS]:\n        params = {\n            "key": key,\n            "bbox": f"{w_},{s_},{e_},{n_}",  # minLon,minLat,maxLon,maxLat\n            "fields": _TOMTOM_FIELDS,\n            "language": "en-US",\n            "timeValidityFilter": "present",\n        }\n        try:\n            r = requests.get(config.TOMTOM_URL, params=params, timeout=20)\n            r.raise_for_status()\n            incidents = r.json().get("incidents") or []\n        except Exception as ex:  # noqa: BLE001\n            tile_fails += 1\n            print(f"[warn] tomtom tile ({s_:.1f},{w_:.1f}) failed: {ex}",\n                  file=sys.stderr)\n            continue\n        for inc in incidents:\n            p = inc.get("properties") or {}\n            iid = p.get("id")\n            if iid and iid in seen:\n                continue  # incidents can straddle tile edges\n            if iid:\n                seen.add(iid)\n            pt = _tomtom_point(inc.get("geometry"))\n            if pt is None:\n                continue\n            descs = [str(ev.get("description") or "")\n                     for ev in (p.get("events") or [])]\n            desc = "; ".join(d for d in descs if d)\n            icon = p.get("iconCategory")\n            if icon in TOMTOM_ICON_CATEGORIES:\n                cat, w = TOMTOM_ICON_CATEGORIES[icon]\n            else:  # unknown icon -> fall back to text classification\n                cat, w = classify_event(desc)\n            if w <= 0:\n                continue  # weather warnings etc.\n            roads = "/".join(p.get("roadNumbers") or [])\n            title = (desc.split(";")[0].strip().capitalize() or cat)\n            if roads:\n                title += f" on {roads}"\n            events.append({\n                "id": iid,\n                "lat": pt[0], "lon": pt[1],\n                "type": title[:80],\n                "desc": (desc or title)[:160],\n                "category": cat, "weight": w,\n                "severity": p.get("magnitudeOfDelay"),\n                "full_closure": icon == 8,\n                "src": "tomtom",\n            })\n    if tile_fails and not events:\n        raise RuntimeError(f"all TomTom tiles failed ({tile_fails})")\n    return events\n\ndef _norm_name(s: str) -> str:\n    import re\n    return re.sub(r"[^a-z]", "", str(s).lower())\n\n\ndef _point_in_ring(lat, lon, ring) -> bool:\n    """Ray-cast point-in-polygon. ring = [[lon, lat], ...]."""\n    inside = False\n    j = len(ring) - 1\n    for i in range(len(ring)):\n        xi, yi = ring[i][0], ring[i][1]\n        xj, yj = ring[j][0], ring[j][1]\n        if ((yi > lat) != (yj > lat)) and (\n                lon < (xj - xi) * (lat - yi) / (yj - yi) + xi):\n            inside = not inside\n        j = i\n    return inside\n\n\ndef _point_in_geom(lat, lon, geom) -> bool:\n    polys = ([geom["coordinates"]] if geom["type"] == "Polygon"\n             else geom["coordinates"])\n    for poly in polys:  # poly[0] = outer ring, rest = holes\n        if _point_in_ring(lat, lon, poly[0]):\n            if any(_point_in_ring(lat, lon, hole) for hole in poly[1:]):\n                continue\n            return True\n    return False\n\n\ndef _county_polygon_index(geodata, county_names):\n    """[(name, bbox, geometry)] for exact event->county assignment.\n    Names are canonicalized to the opportunity table\'s spelling (e.g.\n    Census "LaPorte" -> CSV "Laporte") so risk boosts join correctly."""\n    if not geodata:\n        return None\n    canon = {_norm_name(n): n for n in (county_names or [])}\n    index = []\n    for f in geodata.get("features", []):\n        name = f.get("properties", {}).get("NAME") or f.get("id")\n        name = canon.get(_norm_name(name), name)\n        geom = f.get("geometry") or {}\n        pts = []\n        polys = ([geom["coordinates"]] if geom.get("type") == "Polygon"\n                 else geom.get("coordinates") or [])\n        for poly in polys:\n            pts.extend(poly[0])\n        if not pts:\n            continue\n        lons = [p[0] for p in pts]\n        lats = [p[1] for p in pts]\n        index.append((name, (min(lats), max(lats), min(lons), max(lons)),\n                      geom))\n    return index or None\n\n\ndef _assign_county(lat, lon, poly_index) -> str | None:\n    for name, (s, n, w, e), geom in poly_index:\n        if s <= lat <= n and w <= lon <= e and _point_in_geom(lat, lon,\n                                                              geom):\n            return name\n    return None\n\n\nLAST_STATUS: dict = {}   # per-run source health, read by the caller\n\n\ndef fetch_incidents(geodata=None, county_names=None,\n                    include_tomtom=True,\n                    tomtom_cache=None) -> tuple[pd.Series, list[dict]]:\n    """(county -> weighted activity, event-level list). Events are\n    assigned to the county whose polygon contains them (all 92 counties;\n    out-of-state events from the bbox overhang into Chicago/Louisville/\n    Cincinnati are dropped exactly). If county boundaries are unavailable,\n    falls back to the old nearest-dynamic-centroid-within-35km rule.\n    Primary sources: 511in.org GraphQL (INDOT-managed roads; legacy JSON\n    endpoints as fallback) blended with TomTom probe-data incidents (adds\n    local roads). TomTom events within TOMTOM_DEDUP_KM of a 511 event are\n    dropped so nothing is double-counted.\n\n    tomtom_cache: optional mutable dict persisted by the caller (stored\n    under "_tomtom" in incident_history.json). While the cached snapshot\n    is younger than the day/night refresh threshold it is reused instead\n    of spending API requests; on fetch failure it is the fallback."""\n    poly_index = _county_polygon_index(geodata, county_names)\n    counts = ({n: 0 for n in county_names} if poly_index and county_names\n              else {n: 0 for n in config.COUNTY_CENTROIDS})\n    LAST_STATUS.clear()\n    LAST_STATUS.update({"g511": -1, "tt": "off" if not include_tomtom\n                        else -1})\n    raw = None\n    try:\n        raw = _fetch_incidents_graphql()\n        LAST_STATUS["g511"] = len(raw)\n        print(f"[info] 511 incident feed OK (graphql): "\n              f"{len(raw)} event(s) statewide")\n    except Exception as e:  # noqa: BLE001\n        print(f"[warn] 511 graphql feed failed: {e}", file=sys.stderr)\n    if raw is None:\n        raw = _fetch_incidents_legacy()\n        if raw is not None:\n            LAST_STATUS["g511"] = len(raw)\n    if raw is None:\n        print("[warn] incident feed unavailable: all event feeds failed",\n              file=sys.stderr)\n        raw = []\n    # --- TomTom blend (local-road coverage) --------------------------------\n    tomtom = []\n    if include_tomtom:\n        cache = tomtom_cache if isinstance(tomtom_cache, dict) else {}\n        now = dt.datetime.now()\n        thresh = (config.TOMTOM_REFRESH_DAY_MIN if 6 <= now.hour < 22\n                  else config.TOMTOM_REFRESH_NIGHT_MIN)\n        age_min = None\n        if cache.get("fetched_at"):\n            try:\n                age_min = (now - dt.datetime.fromisoformat(\n                    cache["fetched_at"])).total_seconds() / 60\n            except ValueError:\n                pass\n        if age_min is not None and 0 <= age_min < thresh:\n            tomtom = cache.get("events") or []\n            LAST_STATUS["tt"] = "cache"\n            print(f"[info] tomtom snapshot reused ({age_min:.0f} min old; "\n                  f"refresh threshold {thresh} min) — no API requests spent")\n        else:\n            try:\n                tomtom = _fetch_incidents_tomtom(poly_index)\n                LAST_STATUS["tt"] = len(tomtom)\n                cache["fetched_at"] = now.isoformat(timespec="seconds")\n                cache["events"] = tomtom\n            except Exception as e:  # noqa: BLE001\n                tomtom = cache.get("events") or []\n                LAST_STATUS["tt"] = "cache" if tomtom else -1\n                print(f"[warn] tomtom incident feed failed: {e}"\n                      + (f" — reusing {age_min:.0f} min old snapshot"\n                         if tomtom and age_min is not None else ""),\n                      file=sys.stderr)\n    if tomtom:\n        deg = config.TOMTOM_DEDUP_KM / 111.0\n        kept = [tv for tv in tomtom\n                if not any(abs(tv["lat"] - ev["lat"]) < deg\n                           and abs(tv["lon"] - ev["lon"]) < deg\n                           for ev in raw)]\n        print(f"[info] tomtom incident feed OK: {len(tomtom)} event(s) "\n              f"statewide, {len(kept)} kept after 511 de-dup")\n        raw = raw + kept\n    events: list[dict] = []\n    for ev in raw:\n        if poly_index:  # exact assignment, all 92 counties\n            best = _assign_county(ev["lat"], ev["lon"], poly_index)\n        else:  # fallback: nearest dynamic centroid within ~35 km\n            best, bd = None, 0.35\n            for name, (cla, clo) in config.COUNTY_CENTROIDS.items():\n                d = math.hypot(ev["lat"] - cla, ev["lon"] - clo)\n                if d < bd:\n                    best, bd = name, d\n        if best:\n            counts.setdefault(best, 0)\n            counts[best] += ev.get("weight", 0.3)  # severity-weighted\n            events.append({**ev, "county": best})\n    if raw:\n        cats: dict[str, int] = {}\n        for ev in events:\n            c = ev.get("category", "other")\n            cats[c] = cats.get(c, 0) + 1\n        breakdown = ", ".join(f"{v} {k}" for k, v in\n                              sorted(cats.items(), key=lambda x: -x[1]))\n        scope = ("Indiana counties (statewide polygons)" if poly_index\n                 else "dynamic counties (centroid fallback)")\n        print(f"[info] {len(events)} of {len(raw)} event(s) mapped to "\n              f"{scope} ({breakdown or \'none\'})")\n    return pd.Series(counts), events\n'
_FILES['memory.py'] = '"""\nTrailing-incident memory.\n\nEvery run logs the live 511 events it observes. Events that have dropped\noff the live feed become "trailing": their importance decays as\n\n    importance = magnitude * 0.5 ** (hours_since_last_seen / HALF_LIFE_H)\n\nso a magnitude-5 pileup from 3 days ago still registers (~0.35 of its\noriginal weight at the default 48 h half-life) while minor events fade\nfast. Trailing weight boosts county risk at half the per-point strength\nof a live event and is drawn on the map as fading markers.\n\nPersistence: JSON file. In Colab, mount Google Drive to keep memory\nacross sessions; otherwise memory covers the current session only.\n"""\nfrom __future__ import annotations\n\nimport datetime as dt\nimport hashlib\nimport json\nimport os\n\nimport config\n\nMAGNITUDE_KEYWORDS = [\n    ("pileup", 5), ("multi vehicle", 5), ("multi-vehicle", 5),\n    ("closed", 4), ("closure", 4), ("hazmat", 4), ("spill", 4),\n    ("overturned", 4), ("jackknif", 4),\n    ("crash", 3), ("accident", 3), ("collision", 3),\n    ("lane blocked", 2), ("lane closed", 2), ("restriction", 2),\n    ("stalled", 1), ("disabled", 1), ("construction", 1),\n]\nDEFAULT_MAGNITUDE = 2\n\n\ndef magnitude_of(event_type: str, desc: str = "", severity=None,\n                 full_closure: bool = False) -> int:\n    t = f"{event_type} {desc}".lower()\n    mag = DEFAULT_MAGNITUDE\n    for kw, m in MAGNITUDE_KEYWORDS:\n        if kw in t:\n            mag = m\n            break\n    if full_closure:\n        mag = max(mag, 4)\n    try:  # Castle Rock Severity is often "1".."5"\n        mag = max(mag, min(int(severity), 5))\n    except (TypeError, ValueError):\n        pass\n    return mag\n\n\ndef event_id(ev: dict) -> str:\n    raw = ev.get("id") or f\'{ev.get("lat"):.3f}|{ev.get("lon"):.3f}|\' \\\n                          f\'{ev.get("type", "")}\'\n    return hashlib.md5(str(raw).encode()).hexdigest()[:12]\n\n\ndef history_path() -> str:\n    envp = os.environ.get("HISTORY_PATH")\n    if envp:\n        return envp\n    drive = "/content/drive/MyDrive/accident_forecaster"\n    if os.path.isdir("/content/drive/MyDrive"):\n        os.makedirs(drive, exist_ok=True)\n        return f"{drive}/incident_history.json"\n    return "incident_history.json"\n\n\ndef load() -> dict:\n    """Local history, merged with the machine-built archive from the\n    GitHub Actions poller when config.INCIDENT_LOG_URL is set. The remote\n    archive wins for events it knows about (its last_seen is fresher)."""\n    hist = {}\n    try:\n        with open(history_path()) as f:\n            hist = json.load(f)\n    except Exception:  # noqa: BLE001\n        pass\n    if config.INCIDENT_LOG_URL:\n        try:\n            import requests\n            remote = requests.get(config.INCIDENT_LOG_URL, timeout=30).json()\n            for eid, e in remote.items():\n                if eid.startswith("_"):  # reserved: ledger, tomtom cache\n                    hist.setdefault(eid, e)\n                    continue\n                if (eid not in hist\n                        or e["last_seen"] >= hist[eid]["last_seen"]):\n                    hist[eid] = e\n            print(f"[info] merged {len(remote)} events from remote archive")\n        except Exception as e:  # noqa: BLE001\n            print(f"[warn] remote incident archive unavailable: {e}")\n    return hist\n\n\ndef save(hist: dict) -> None:\n    with open(history_path(), "w") as f:\n        json.dump(hist, f)\n\n\ndef update(hist: dict, live_events: list[dict],\n           now: dt.datetime | None = None) -> dict:\n    """Merge this run\'s live events into history; prune fully-faded ones."""\n    now = now or config.local_now()\n    now_s = now.isoformat(timespec="seconds")\n    live_ids = set()\n    for ev in live_events:\n        if ev.get("weight", 1.0) < config.MEMORY_MIN_WEIGHT:\n            continue  # roadwork/congestion: no trailing value, bloats file\n        eid = event_id(ev)\n        live_ids.add(eid)\n        if eid in hist:\n            h = hist[eid]\n            h["last_seen"] = now_s\n            # Feeds enrich event text after first sighting ("Crash" ->\n            # "Crash, overturned semi trailer"). Keep the richest text so\n            # truck detection, map badges, and the ledger reconcile pass\n            # (ledger._reconcile_truck) see the full description. Magnitude\n            # only ratchets up; shrinking it mid-decay would be surprising.\n            new_desc = str(ev.get("desc", "") or "")\n            if len(new_desc) > len(str(h.get("desc") or "")):\n                h["desc"] = new_desc\n                h["type"] = ev.get("type", h.get("type", "event"))\n                h["magnitude"] = max(\n                    float(h.get("magnitude", 0) or 0),\n                    magnitude_of(ev.get("type", ""), new_desc,\n                                 ev.get("severity"),\n                                 ev.get("full_closure", False)))\n            if ev.get("road") and not h.get("road"):\n                h["road"] = ev["road"]\n        else:\n            hist[eid] = {\n                "first_seen": now_s, "last_seen": now_s,\n                "lat": ev.get("lat"), "lon": ev.get("lon"),\n                "county": ev.get("county"), "type": ev.get("type", "event"),\n                "desc": ev.get("desc", ""),\n                "road": ev.get("road", ""),\n                "category": ev.get("category", ""),\n                "magnitude": magnitude_of(ev.get("type", ""),\n                                          ev.get("desc", ""),\n                                          ev.get("severity"),\n                                          ev.get("full_closure", False)),\n            }\n    # prune events decayed below 5% of a magnitude-1 event\n    keep = {}\n    for eid, e in hist.items():\n        if eid.startswith("_"):\n            keep[eid] = e  # reserved keys (e.g. the crash ledger)\n            continue\n        if eid in live_ids or _decay(e, now) * e["magnitude"] >= 0.05:\n            keep[eid] = e\n    return keep\n\n\ndef _decay(e: dict, now: dt.datetime) -> float:\n    last = dt.datetime.fromisoformat(e["last_seen"])\n    # Stale-crash cap: for crashes, decay as if the event ended no later\n    # than first_seen + CRASH_LIVE_MAX_H. A feed-hygiene ghost re-listed\n    # for days keeps refreshing last_seen; without this cap it would decay\n    # from its final sighting and linger in trailing risk long after.\n    if e.get("category") == "crash" and e.get("first_seen"):\n        try:\n            cap = (dt.datetime.fromisoformat(e["first_seen"])\n                   + dt.timedelta(hours=config.CRASH_LIVE_MAX_H))\n            last = min(last, cap)\n        except ValueError:\n            pass\n    hours = max((now - last).total_seconds() / 3600, 0)\n    return 0.5 ** (hours / config.TRAILING_HALF_LIFE_H)\n\n\ndef trailing(hist: dict, live_ids: set[str],\n             now: dt.datetime | None = None) -> list[dict]:\n    """Decayed non-live events: [{lat, lon, county, type, magnitude,\n    importance, age_h}] with importance = magnitude * decay."""\n    now = now or config.local_now()\n    out = []\n    for eid, e in hist.items():\n        if eid in live_ids or eid.startswith("_"):\n            continue\n        d = _decay(e, now)\n        imp = e["magnitude"] * d\n        if imp < 0.05:\n            continue\n        # Age semantics: a CRASH "happened" at first sighting — a listing\n        # that stayed on 511 for hours must not make it look fresher.\n        # Non-crash events (closures, roadwork) are current while listed,\n        # so their age runs from last_seen as before.\n        ref = ("first_seen" if e.get("category") == "crash"\n               else "last_seen")\n        try:\n            age_h = (now - dt.datetime.fromisoformat(e[ref])\n                     ).total_seconds() / 3600\n        except (KeyError, ValueError):\n            age_h = (now - dt.datetime.fromisoformat(e["last_seen"])\n                     ).total_seconds() / 3600\n        if age_h > config.TRAIL_MAX_AGE_H:\n            continue  # hard display/model cutoff (see config)\n        out.append({**e, "importance": round(imp, 3),\n                    "decay": round(d, 3), "age_h": round(age_h, 1)})\n    return sorted(out, key=lambda x: -x["importance"])\n\n\ndef county_trailing_scores(trail: list[dict]) -> dict[str, float]:\n    scores: dict[str, float] = {}\n    for e in trail:\n        c = e.get("county")\n        if c:\n            scores[c] = scores.get(c, 0.0) + e["importance"]\n    return scores\n'
_FILES['model.py'] = '"""\nCounty risk model (v2).\n\nrisk(county, hour) = opportunity(county) × exposure(hour-of-week)\n                     × weather_multiplier(county, hour)\ncounty_score       = Σ_hours risk × incident_boost(county)\n\nStatic-tier counties (outside the top DYNAMIC_N) use neutral weather, so\ntheir score is pure baseline — they can\'t gain from conditions but remain\nin the allocation.\n"""\nfrom __future__ import annotations\n\nimport numpy as np\nimport pandas as pd\n\nimport config\nfrom sources import weather_multiplier\n\n\ndef hourly_exposure() -> np.ndarray:\n    vec = []\n    for wd in range(7):\n        prof = config.WEEKDAY_HOURLY if wd < 5 else config.WEEKEND_HOURLY\n        vec.extend(prof)\n    v = np.array(vec, dtype=float)\n    return v / v.mean()\n\n\ndef score(counties: pd.DataFrame,\n          weather: dict[str, pd.DataFrame],\n          incidents: pd.Series,\n          hours: int = 48,\n          trailing_scores: dict[str, float] | None = None,\n          ledger_factors: dict[str, float] | None = None\n          ) -> tuple[pd.DataFrame, pd.DataFrame]:\n    """Returns (county_scores, county_hourly)."""\n    exposure = hourly_exposure()\n    hourly_rows = []\n    horizon, drivers = {}, {}\n    for _, c in counties.iterrows():\n        name = c["county"]\n        wdf = weather.get(name)\n        if c["dynamic"] and wdf is not None:\n            total = 0.0\n            cond_hours: dict[str, int] = {}\n            peak_ts, peak_risk = None, -1.0\n            for ts, row in wdf.iloc[:hours].iterrows():\n                wm = weather_multiplier(row)\n                ex = float(exposure[ts.weekday() * 24 + ts.hour])\n                risk = wm * ex\n                total += risk\n                lab = condition_label(row)\n                if lab:\n                    cond_hours[lab] = cond_hours.get(lab, 0) + 1\n                if risk > peak_risk:\n                    peak_risk, peak_ts = risk, ts\n                hourly_rows.append({\n                    "county": name, "time": ts,\n                    "weather_mult": round(wm, 3), "exposure": round(ex, 3),\n                    "hour_risk": round(risk, 3),\n                })\n            horizon[name] = total\n            cond_txt = ", ".join(f"{v}h {k}" for k, v in sorted(\n                cond_hours.items(), key=lambda x: -x[1])) or "clear/dry"\n            drivers[name] = {\n                "conditions": cond_txt,\n                "peak": peak_ts.strftime("%a %H:00") if peak_ts is not None\n                        else "",\n            }\n        else:\n            horizon[name] = float(hours)  # neutral: mean multiplier 1.0\n\n    out = counties.copy()\n    out["horizon_weather"] = out["county"].map(horizon)\n    out["wx_conditions"] = out["county"].map(\n        lambda n: drivers.get(n, {}).get("conditions", "static tier"))\n    out["wx_peak"] = out["county"].map(\n        lambda n: drivers.get(n, {}).get("peak", ""))\n    out["weather_lift"] = (out["horizon_weather"] / hours).round(3)\n    ev = out["county"].map(incidents).fillna(0)\n    out["active_events"] = ev.round(2)  # severity-weighted activity\n    tr = out["county"].map(trailing_scores or {}).fillna(0.0)\n    out["trailing_weight"] = tr.round(2)\n    out["incident_boost"] = np.minimum(\n        1 + config.INCIDENT_BOOST_PER_EVENT * ev\n        + config.TRAILING_BOOST_PER_POINT * tr,\n        config.INCIDENT_BOOST_CAP)\n    lf = out["county"].map(ledger_factors or {}).fillna(1.0)\n    out["learned_adj"] = lf.round(3)  # long-term crash-ledger factor\n    out["risk_score"] = (out["opportunity_score"] * out["horizon_weather"]\n                         * out["incident_boost"] * lf)\n    out["risk_score"] = (100 * out["risk_score"]\n                         / out["risk_score"].max()).round(2)\n    out = out.sort_values("risk_score", ascending=False)\n    return out, pd.DataFrame(hourly_rows)\n\n\ndef condition_label(row) -> str | None:\n    """Human label for the dominant adverse condition in a forecast hour."""\n    rain = row.get("precipitation", 0.0)\n    snow = row.get("snowfall", 0.0)\n    if row.get("freezing_precip_flag", False) or (\n            rain > 0.1 and row.get("temperature_2m", 15) <= 0):\n        return "freezing rain/ice"\n    if snow > 1.0:\n        return "heavy snow"\n    if snow > 0.1:\n        return "snow"\n    if rain > 2.5:\n        return "heavy rain"\n    if rain > 0.1:\n        return "rain"\n    if row.get("visibility", 20000) < 1000:\n        return "fog"\n    return None\n'
_FILES['geo.py'] = '"""\nGeometry + commuter-flow data (fetched live in Colab; graceful fallbacks).\n\n- Indiana county polygons: Census/plotly counties GeoJSON, filtered to\n  STATE == "18". Gives real boundaries for the choropleth and centroids\n  computed from the polygons (replacing hand-entered centroids for flows).\n- Commuter origins: Census LODES8 origin-destination files for Indiana\n  (block-level home->work job counts, aggregated to county). The inbound\n  commuter mix of a county is the best public proxy for "where the people\n  driving through it come from." main = both ends in Indiana; aux adds\n  out-of-state residents working in Indiana (rolled up to state level).\n"""\nfrom __future__ import annotations\n\nimport re\nimport sys\n\nimport pandas as pd\nimport requests\n\nimport config\n\nGEOJSON_URL = ("https://raw.githubusercontent.com/plotly/datasets/master/"\n               "geojson-counties-fips.json")\nLODES_MAIN = ("https://lehd.ces.census.gov/data/lodes/LODES8/in/od/"\n              "in_od_main_JT00_2022.csv.gz")\nLODES_AUX = ("https://lehd.ces.census.gov/data/lodes/LODES8/in/od/"\n             "in_od_aux_JT00_2022.csv.gz")\n\nNEIGHBOR_STATES = {  # state FIPS -> (label, approx centroid) for flow lines\n    "17": ("Illinois", (40.0, -89.2)), "21": ("Kentucky", (37.5, -85.3)),\n    "39": ("Ohio", (40.3, -82.8)), "26": ("Michigan", (43.3, -84.6)),\n}\nSTATE_NAMES = {"17": "Illinois", "21": "Kentucky", "39": "Ohio",\n               "26": "Michigan", "state": "out of state"}\n\n\ndef _norm(s: str) -> str:\n    return re.sub(r"[^a-z]", "", str(s).lower())\n\n\ndef fetch_indiana_geojson() -> dict | None:\n    """{\'features\': [...], \'fips_to_name\': {}, \'name_to_fips\': {},\n        \'centroids\': {fips: (lat, lon)}} or None if unreachable."""\n    try:\n        gj = requests.get(GEOJSON_URL, timeout=90).json()\n    except Exception as e:  # noqa: BLE001\n        print(f"[warn] county GeoJSON unavailable ({e}); map falls back "\n              "to geographic circles.", file=sys.stderr)\n        return None\n    feats = [f for f in gj["features"]\n             if f.get("properties", {}).get("STATE") == "18"]\n    fips_to_name, centroids = {}, {}\n    for f in feats:\n        fips = f.get("id") or ("18" + f["properties"]["COUNTY"])\n        f["id"] = fips\n        name = f["properties"].get("NAME", fips)\n        fips_to_name[fips] = name\n        centroids[fips] = _centroid(f["geometry"])\n    return {"features": feats, "fips_to_name": fips_to_name,\n            "name_to_fips": {_norm(v): k for k, v in fips_to_name.items()},\n            "centroids": centroids}\n\n\ndef _centroid(geom: dict) -> tuple[float, float]:\n    if geom["type"] == "Polygon":\n        ring = geom["coordinates"][0]\n    else:  # MultiPolygon: use largest ring\n        ring = max((p[0] for p in geom["coordinates"]), key=len)\n    lon = sum(p[0] for p in ring) / len(ring)\n    lat = sum(p[1] for p in ring) / len(ring)\n    return (round(lat, 4), round(lon, 4))\n\n\ndef fetch_flows() -> pd.DataFrame | None:\n    """County-level OD: columns w_cty (workplace FIPS, all 18xxx),\n    h_cty (home FIPS, any state), jobs. None if unreachable."""\n    frames = []\n    for url in (LODES_MAIN, LODES_AUX):\n        try:\n            df = pd.read_csv(url, usecols=["w_geocode", "h_geocode", "S000"],\n                             dtype={"w_geocode": str, "h_geocode": str})\n            frames.append(df)\n        except Exception as e:  # noqa: BLE001\n            print(f"[warn] LODES fetch failed for {url.split(\'/\')[-1]} "\n                  f"({e})", file=sys.stderr)\n    if not frames:\n        return None\n    od = pd.concat(frames, ignore_index=True)\n    od["w_cty"] = od["w_geocode"].str[:5]\n    od["h_cty"] = od["h_geocode"].str[:5]\n    return (od.groupby(["w_cty", "h_cty"])["S000"].sum()\n            .rename("jobs").reset_index())\n\n\ndef top_origins(flows: pd.DataFrame | None, geo: dict | None,\n                k: int = 6) -> dict:\n    """{workplace_fips: [{label, share, lat, lon(or None)}...]} — the top\n    inbound commuter origins for every Indiana county."""\n    if flows is None:\n        return {}\n    fips_to_name = geo["fips_to_name"] if geo else {}\n    centroids = geo["centroids"] if geo else {}\n    out = {}\n    for w, grp in flows.groupby("w_cty"):\n        total = grp["jobs"].sum()\n        ext = grp[grp["h_cty"] != w].copy()\n        # roll out-of-state homes up to state level\n        ext["origin"] = ext["h_cty"].where(\n            ext["h_cty"].str.startswith("18"), "S" + ext["h_cty"].str[:2])\n        agg = (ext.groupby("origin")["jobs"].sum()\n               .sort_values(ascending=False).head(k))\n        rows = []\n        for origin, jobs in agg.items():\n            if origin.startswith("S"):\n                sf = origin[1:]\n                label, cen = NEIGHBOR_STATES.get(\n                    sf, (STATE_NAMES.get(sf, f"state {sf}"), None))\n            else:\n                label = fips_to_name.get(origin, origin) + " Co."\n                cen = centroids.get(origin)\n            rows.append({\n                "label": label, "share": round(float(jobs / total), 3),\n                "lat": cen[0] if cen else None,\n                "lon": cen[1] if cen else None,\n            })\n        internal = float(grp[grp["h_cty"] == w]["jobs"].sum() / total)\n        out[w] = {"origins": rows, "internal_share": round(internal, 3)}\n    return out\n\n\ndef spill_matrix(flows: pd.DataFrame | None, geo: dict | None,\n                 county_names: list[str]) -> dict | None:\n    """{work county name: [(home county name, fraction)]} from LODES\n    county OD. fraction = SPILLOVER_FRAC * (home share of the county\'s\n    commuters), Indiana-internal homes only, top SPILLOVER_TOP_K. Used to\n    credit part of a crash\'s evidence to where its drivers likely live."""\n    if flows is None or not geo:\n        return None\n    normfn = lambda s: re.sub(r"[^a-z]", "", str(s).lower())  # noqa: E731\n    canon = {normfn(n): n for n in (county_names or [])}\n    f2n = {}\n    for fips, nm in (geo.get("fips_to_name") or {}).items():\n        c = canon.get(normfn(nm))\n        if c:\n            f2n[fips] = c\n    out = {}\n    for w, grp in flows.groupby("w_cty"):\n        wname = f2n.get(w)\n        if not wname:\n            continue\n        total = float(grp["jobs"].sum()) or 1.0\n        ext = grp[(grp["h_cty"] != w) & grp["h_cty"].isin(f2n)]\n        if ext.empty:\n            continue\n        top = (ext.groupby("h_cty")["jobs"].sum()\n               .sort_values(ascending=False).head(config.SPILLOVER_TOP_K))\n        rows = [(f2n[h], round(config.SPILLOVER_FRAC * float(j) / total, 4))\n                for h, j in top.items()]\n        rows = [r for r in rows if r[1] >= 0.002]\n        if rows:\n            out[wname] = rows\n    return out or None\n'
_FILES['ui.py'] = '"""\nShared presentation layer for every page the forecaster publishes.\n\nOne design system, one tab bar, one set of chart primitives, so the map,\nthe two public-safety reports and the ad ops sheet read as one site\ninstead of four separately-invented HTML documents.\n\nDesign direction — "highway instrumentation": the visual vocabulary is\nborrowed from the roads the data describes. Condensed signage type for\nheadings, a serif reading face for prose, tabular mono for numbers.\nThe signature element is the STRIPE BAR: every bar chart is drawn as\nlane striping where one dash = one recorded crash, so a reader can\nliterally count the evidence instead of trusting a bar\'s length.\n\nNothing here fetches or computes anything; callers pass finished numbers.\nNo external fonts, no CDN, no JS libraries — these pages are committed to\na repo and served as static files, so they must render offline and\nsurvive Pages caching forever.\n"""\nfrom __future__ import annotations\n\nimport html as _html\n\n# --- palette -------------------------------------------------------------\n# Accents are page identities, drawn from Indiana highway sign colours:\n# guide-sign green (public safety), interstate-shield blue (policy),\n# work-zone orange-brown (internal ops). Deliberately NOT interchangeable\n# — the accent is how a reader knows which page they\'re on before reading.\nACCENTS = {\n    "safety": "#14603C",   # INDOT guide-sign green\n    "brief": "#1B3A6B",    # interstate shield blue\n    "ops": "#8C3A12",      # work-zone orange, darkened for text contrast\n    "map": "#14603C",\n}\n\n\ndef esc(x) -> str:\n    return _html.escape(str(x))\n\n\ndef _tokens(accent: str) -> str:\n    return (\n        ":root{"\n        "--ink:#12171C;--ink2:#3D4750;--ink3:#6E7880;"\n        "--paper:#F5F7F4;--surface:#FFFFFF;--sunk:#EEF1EC;"\n        "--line:#D9DFD8;--line2:#EBEFE9;"\n        "--accent:%s;--accent-w:color-mix(in srgb,var(--accent) 12%%,white);"\n        "--accent-m:color-mix(in srgb,var(--accent) 45%%,white);"\n        "--amber:#B9861B;--amber-w:#FBF3DF;"\n        "--danger:#9E2B2B;--danger-w:#FBEDED;"\n        "--ok:#14603C;"\n        "--display:\'Oswald\',\'Archivo Narrow\',\'Roboto Condensed\',"\n        "\'Franklin Gothic Medium\',\'Arial Narrow\',system-ui,sans-serif;"\n        "--body:Charter,\'Bitstream Charter\',\'Iowan Old Style\',"\n        "\'Source Serif 4\',Georgia,\'Times New Roman\',serif;"\n        "--data:ui-monospace,\'SF Mono\',\'Cascadia Mono\',\'Segoe UI Mono\',"\n        "Consolas,monospace;"\n        "--r:3px}" % accent\n    )\n\n\n_STRUCTURE = """\n*{box-sizing:border-box}\nhtml{-webkit-text-size-adjust:100%}\nbody{margin:0;background:var(--paper);color:var(--ink);\nfont-family:var(--body);font-size:16.5px;line-height:1.6;\nfont-feature-settings:"kern" 1}\n.wrap{max-width:940px;margin:0 auto;padding:0 20px 72px}\na{color:var(--accent);text-underline-offset:2px}\na:hover{text-decoration-thickness:2px}\n:focus-visible{outline:3px solid var(--accent);outline-offset:2px}\n\n/* --- sign gantry: the tab bar ------------------------------------- */\n.gantry{position:sticky;top:0;z-index:900;background:var(--surface);\nborder-bottom:1px solid var(--line);\nbox-shadow:0 1px 0 rgba(18,23,28,.04),0 6px 18px -14px rgba(18,23,28,.5)}\n.gantry-in{max-width:940px;margin:0 auto;display:flex;align-items:stretch;\ngap:2px;padding:0 12px;overflow-x:auto;scrollbar-width:none}\n.gantry-in::-webkit-scrollbar{display:none}\n.tab{font-family:var(--display);font-size:13px;font-weight:600;\nletter-spacing:.09em;text-transform:uppercase;text-decoration:none;\ncolor:var(--ink3);padding:15px 14px 12px;border-bottom:3px solid transparent;\nwhite-space:nowrap;display:flex;align-items:center;gap:8px;\ntransition:color .12s,border-color .12s,background .12s}\n.tab:hover{color:var(--ink);background:var(--sunk)}\n.tab[aria-current="page"]{color:var(--accent);border-bottom-color:var(--accent)}\n.tab .dot{width:7px;height:7px;border-radius:50%;background:currentColor;\nopacity:.55;flex:0 0 auto}\n.tab[aria-current="page"] .dot{opacity:1}\n.gantry .draftflag{margin-left:auto;align-self:center;flex:0 0 auto;\nfont-family:var(--display);font-size:11px;letter-spacing:.12em;\ntext-transform:uppercase;color:var(--amber);border:1px solid var(--amber);\nborder-radius:2px;padding:3px 7px;background:var(--amber-w)}\n@media (max-width:700px){.tab{font-size:11.5px;padding:12px 10px 9px}\n.gantry .draftflag{display:none}}\n\n/* --- masthead ------------------------------------------------------ */\n.mast{padding:38px 0 20px;border-bottom:2px solid var(--ink)}\n.eyebrow{font-family:var(--display);font-size:12px;letter-spacing:.16em;\ntext-transform:uppercase;color:var(--accent);margin:0 0 10px}\nh1{font-family:var(--display);font-weight:600;font-size:clamp(30px,5vw,44px);\nline-height:1.06;letter-spacing:-.005em;margin:0 0 12px;max-width:22ch}\n.standfirst{font-size:18.5px;line-height:1.5;color:var(--ink2);margin:0;\nmax-width:60ch}\n.stamp{margin-top:16px;font-family:var(--data);font-size:12px;\ncolor:var(--ink3);letter-spacing:.02em}\n\n/* --- sections: milepost headings ----------------------------------- */\nh2{font-family:var(--display);font-weight:600;font-size:23px;\nletter-spacing:.005em;margin:52px 0 14px;padding-left:0;\ndisplay:flex;align-items:baseline;gap:12px}\nh2 .post{font-size:12px;letter-spacing:.12em;color:var(--accent);\nborder:1.5px solid var(--accent);border-radius:2px;padding:2px 6px;\nflex:0 0 auto;position:relative;top:-3px}\nh3{font-family:var(--display);font-weight:600;font-size:18px;margin:0 0 6px;\nletter-spacing:.01em}\np{margin:0 0 14px}\n.lede{font-size:17.5px;color:var(--ink2)}\n.small,small{font-size:13.5px;color:var(--ink3);line-height:1.5}\n.hint{font-size:13.5px;color:var(--ink3);line-height:1.55;margin-top:10px;\npadding-left:12px;border-left:2px solid var(--line)}\n\n/* --- cards --------------------------------------------------------- */\n.card{background:var(--surface);border:1px solid var(--line);\nborder-radius:var(--r);padding:20px 22px;margin:16px 0}\n.card.rank{border-left:4px solid var(--accent)}\n.card-h{display:flex;justify-content:space-between;align-items:flex-start;\ngap:16px;flex-wrap:wrap;margin-bottom:10px}\n.where{font-family:var(--display);font-size:20px;font-weight:600;\nline-height:1.2}\n.where .cty{display:block;font-size:12.5px;letter-spacing:.1em;\ntext-transform:uppercase;color:var(--ink3);font-weight:500;margin-top:3px}\n.kicker{font-family:var(--display);font-size:11.5px;letter-spacing:.11em;\ntext-transform:uppercase;color:var(--ink3)}\n\n/* --- chips --------------------------------------------------------- */\n.chip{display:inline-flex;align-items:center;gap:5px;font-family:var(--display);\nfont-size:11.5px;letter-spacing:.08em;text-transform:uppercase;\npadding:3px 8px;border-radius:2px;border:1px solid var(--line);\ncolor:var(--ink2);background:var(--sunk);white-space:nowrap}\n.chip.on{border-color:var(--accent);color:var(--accent);\nbackground:var(--accent-w)}\n.chip.good{border-color:var(--ok);color:var(--ok);\nbackground:color-mix(in srgb,var(--ok) 10%,white)}\n.chip.warn{border-color:var(--amber);color:var(--amber);\nbackground:var(--amber-w)}\n.chip.bad{border-color:var(--danger);color:var(--danger);\nbackground:var(--danger-w)}\n.chips{display:flex;flex-wrap:wrap;gap:6px;margin:10px 0}\n\n/* --- the signature: stripe bars ------------------------------------ */\n.stripe-row{display:grid;grid-template-columns:minmax(0,1fr) auto;\nalign-items:center;gap:14px;padding:7px 0;border-bottom:1px solid var(--line2)}\n.stripe-row:last-child{border-bottom:0}\n.stripe-lab{font-size:14.5px;line-height:1.3;min-width:0}\n.stripe-lab b{font-family:var(--display);font-weight:600}\n.stripe-lab span{display:block;font-size:12px;color:var(--ink3);\nletter-spacing:.06em;text-transform:uppercase;font-family:var(--display)}\n.stripe-wrap{display:flex;align-items:center;gap:10px;justify-self:end}\n.stripe{height:13px;border-radius:1px;flex:0 0 auto}\n.stripe-n{font-family:var(--data);font-size:13.5px;font-weight:600;\nmin-width:2.6ch;text-align:right}\n\n/* --- tables -------------------------------------------------------- */\n.tbl-scroll{overflow-x:auto;margin:14px 0}\ntable{border-collapse:collapse;width:100%;font-size:14px;\nbackground:var(--surface)}\nth{font-family:var(--display);font-size:11.5px;letter-spacing:.09em;\ntext-transform:uppercase;text-align:left;color:var(--ink2);\nbackground:var(--sunk);border-bottom:2px solid var(--line);\npadding:9px 11px;white-space:nowrap;font-weight:600}\ntd{border-bottom:1px solid var(--line2);padding:9px 11px;vertical-align:top}\ntr:last-child td{border-bottom:0}\ntd.num,th.num{text-align:right;font-family:var(--data);\nfont-variant-numeric:tabular-nums}\ntbody tr:hover{background:var(--sunk)}\n\n/* --- disclosure ---------------------------------------------------- */\ndetails{background:var(--surface);border:1px solid var(--line);\nborder-radius:var(--r);margin:8px 0}\ndetails[open]{border-color:var(--accent-m)}\nsummary{cursor:pointer;padding:12px 16px;list-style:none;\ndisplay:grid;grid-template-columns:auto minmax(0,1fr) auto;\nalign-items:center;gap:12px}\nsummary::-webkit-details-marker{display:none}\nsummary:hover{background:var(--sunk)}\nsummary .car{font-family:var(--data);font-size:11px;color:var(--ink3);\ntransition:transform .15s}\ndetails[open] summary .car{transform:rotate(90deg)}\n@media (prefers-reduced-motion:reduce){summary .car{transition:none}}\n.det-body{padding:2px 16px 16px;border-top:1px solid var(--line2);\nmargin-top:2px}\n\n/* --- callouts ------------------------------------------------------ */\n.note{border:1px solid var(--line);border-left:4px solid var(--ink3);\nbackground:var(--surface);padding:14px 16px;margin:16px 0;font-size:14.5px;\nline-height:1.55;border-radius:var(--r)}\n.note.draft{border-left-color:var(--amber);background:var(--amber-w)}\n.note.hold{border-left-color:var(--danger);background:var(--danger-w)}\n.note.good{border-left-color:var(--ok)}\n.note b{font-family:var(--display);letter-spacing:.02em}\n\n/* --- key figures --------------------------------------------------- */\n.figs{display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));\ngap:1px;background:var(--line);border:1px solid var(--line);\nborder-radius:var(--r);overflow:hidden;margin:18px 0}\n.fig{background:var(--surface);padding:14px 16px}\n.fig .v{font-family:var(--display);font-size:30px;font-weight:600;\nline-height:1;color:var(--accent);font-variant-numeric:tabular-nums}\n.fig .k{font-family:var(--display);font-size:11px;letter-spacing:.1em;\ntext-transform:uppercase;color:var(--ink3);margin-top:6px}\n.fig .sub{font-size:12.5px;color:var(--ink3);margin-top:4px;line-height:1.4}\n\n/* --- charts -------------------------------------------------------- */\nfigure{margin:18px 0}\nfigcaption{font-size:13px;color:var(--ink3);line-height:1.5;margin-top:8px}\nsvg{display:block;max-width:100%;height:auto}\n.svg-lab{font-family:var(--display);font-size:10.5px;letter-spacing:.08em;\ntext-transform:uppercase;fill:var(--ink3)}\n.svg-val{font-family:var(--data);font-size:10.5px;fill:var(--ink2)}\n\n/* --- proportion bar ------------------------------------------------ */\n.prop{display:flex;height:26px;border-radius:2px;overflow:hidden;\nborder:1px solid var(--line);margin:10px 0}\n.prop div{display:flex;align-items:center;justify-content:center;\nfont-family:var(--display);font-size:11px;letter-spacing:.05em;color:#fff;\nmin-width:0;overflow:hidden}\n.prop-key{display:flex;flex-wrap:wrap;gap:12px;font-size:12.5px;\ncolor:var(--ink3);margin-top:2px}\n.prop-key i{width:10px;height:10px;border-radius:1px;display:inline-block;\nmargin-right:5px;vertical-align:-1px}\n\n/* --- footer -------------------------------------------------------- */\n.foot{margin-top:56px;padding:20px 22px;background:var(--sunk);\nborder:1px solid var(--line);border-radius:var(--r);font-size:13.5px;\nline-height:1.6;color:var(--ink2)}\n.foot b{font-family:var(--display)}\n@media print{.gantry{position:static}.card,table{break-inside:avoid}}\n"""\n\n\ndef head(title: str, accent_key: str = "safety") -> str:\n    """Opening tags + the full stylesheet for a page."""\n    return ("<!DOCTYPE html><html lang=\'en\'><head><meta charset=\'utf-8\'>"\n            "<meta name=\'viewport\' content=\'width=device-width,"\n            "initial-scale=1\'><title>" + esc(title) + "</title><style>"\n            + _tokens(ACCENTS.get(accent_key, ACCENTS["safety"]))\n            + _STRUCTURE + "</style></head><body>")\n\n\n# Page identities. Each entry: (slug, label, draft filename or None).\nPAGES = [\n    ("index.html", "Live Risk Map", None),\n    ("safety_watch.html", "Road Safety Watch", "safety_watch_draft.html"),\n    ("action_brief.html", "Hotspot Action Brief", "action_brief_draft.html"),\n    ("ad_ops.html", "Ad Ops Sheet", None),\n]\n\n\ndef tabs(current: str, draft: bool = False) -> str:\n    """Site tab bar.\n\n    `draft=True` renders the DRAFT variant: every link that HAS a draft\n    twin points at the twin, so a reviewer clicking through the review\n    copies stays inside the review copies. On published pages the links\n    point at published pages. Getting this wrong is how a reviewer ends\n    up reading a stale published page and approving it as if it were the\n    new draft.\n    """\n    out = ["<nav class=\'gantry\' aria-label=\'Report sections\'>"\n           "<div class=\'gantry-in\'>"]\n    for slug, label, draft_slug in PAGES:\n        href = draft_slug if (draft and draft_slug) else slug\n        cur = (current == slug)\n        out.append("<a class=\'tab\' href=\'%s\'%s><span class=\'dot\'></span>%s</a>"\n                   % (esc(href), " aria-current=\'page\'" if cur else "",\n                      esc(label)))\n    if draft:\n        out.append("<span class=\'draftflag\'>Draft</span>")\n    out.append("</div></nav>")\n    return "".join(out)\n\n\ndef masthead(eyebrow: str, title: str, standfirst: str, stamp: str) -> str:\n    return ("<header class=\'mast\'><p class=\'eyebrow\'>" + esc(eyebrow)\n            + "</p><h1>" + esc(title) + "</h1><p class=\'standfirst\'>"\n            + esc(standfirst) + "</p><div class=\'stamp\'>" + esc(stamp)\n            + "</div></header>")\n\n\ndef h2(post: str, text: str) -> str:\n    """Section heading with a milepost tag (the tag carries the section\'s\n    short name, so it works as an in-page landmark, not decoration)."""\n    return ("<h2><span class=\'post\'>" + esc(post) + "</span>"\n            + esc(text) + "</h2>")\n\n\ndef figs(items: list[tuple]) -> str:\n    """Key-figure strip. items = [(value, label, subtext)]."""\n    cells = "".join(\n        "<div class=\'fig\'><div class=\'v\'>%s</div><div class=\'k\'>%s</div>"\n        "%s</div>"\n        % (esc(v), esc(k),\n           ("<div class=\'sub\'>%s</div>" % esc(s)) if s else "")\n        for v, k, s in items)\n    return "<div class=\'figs\'>" + cells + "</div>"\n\n\n# --- the signature chart -------------------------------------------------\n\ndef stripe(n: int, mx: int, maxw: int = 240, color: str = "var(--accent)"\n           ) -> str:\n    """Lane-striping bar: one dash = one recorded crash, so the reader can\n    count the evidence rather than estimate a bar length."""\n    mx = max(int(mx or 1), 1)\n    n = max(int(n or 0), 0)\n    per = max(2.6, min(9.0, maxw / mx))\n    dash = max(1.6, per * 0.6)\n    w = per * n\n    return ("<span class=\'stripe\' style=\'width:%.1fpx;background:"\n            "repeating-linear-gradient(90deg,%s 0 %.2fpx,transparent "\n            "%.2fpx %.2fpx)\' title=\'%d\'></span>"\n            % (w, color, dash, dash, per, n))\n\n\ndef stripe_rows(rows: list[tuple], maxw: int = 240,\n                color: str = "var(--accent)") -> str:\n    """rows = [(label, sublabel, n)] rendered as ranked stripe bars."""\n    if not rows:\n        return ""\n    mx = max(r[2] for r in rows) or 1\n    out = []\n    for lab, sub, n in rows:\n        out.append(\n            "<div class=\'stripe-row\'><div class=\'stripe-lab\'><b>%s</b>%s</div>"\n            "<div class=\'stripe-wrap\'>%s<span class=\'stripe-n\'>%d</span></div>"\n            "</div>"\n            % (esc(lab), ("<span>%s</span>" % esc(sub)) if sub else "",\n               stripe(n, mx, maxw, color), n))\n    return "".join(out)\n\n\ndef hour_chart(counts: dict, height: int = 108) -> str:\n    """24-hour crash profile with the commute windows shaded, so the\n    reader sees the peaks against the periods people actually plan\n    around rather than against an unlabelled axis."""\n    vals = [int(counts.get(h, 0) or 0) for h in range(24)]\n    mx = max(vals) or 1\n    w, pad, top = 720, 26, 12\n    bw = (w - pad * 2) / 24.0\n    body = []\n    for a, b in ((6, 10), (15, 19)):\n        body.append("<rect x=\'%.1f\' y=\'%d\' width=\'%.1f\' height=\'%d\' "\n                    "fill=\'var(--sunk)\'/>"\n                    % (pad + a * bw, top, (b - a) * bw, height))\n    for h, v in enumerate(vals):\n        bh = (v / mx) * height\n        body.append("<rect x=\'%.1f\' y=\'%.1f\' width=\'%.1f\' height=\'%.1f\' "\n                    "fill=\'var(--accent)\' opacity=\'%.2f\'><title>%02d:00 — "\n                    "%d crashes</title></rect>"\n                    % (pad + h * bw + 1.2, top + height - bh, bw - 2.4,\n                       max(bh, 0.8), 0.45 + 0.55 * (v / mx), h, v))\n    for h in (0, 6, 12, 18, 23):\n        body.append("<text class=\'svg-lab\' x=\'%.1f\' y=\'%d\' "\n                    "text-anchor=\'middle\'>%02d</text>"\n                    % (pad + h * bw + bw / 2, top + height + 15, h))\n    body.append("<text class=\'svg-lab\' x=\'%.1f\' y=\'%d\' text-anchor=\'middle\'>"\n                "AM peak</text>" % (pad + 8 * bw, top - 2))\n    body.append("<text class=\'svg-lab\' x=\'%.1f\' y=\'%d\' text-anchor=\'middle\'>"\n                "PM peak</text>" % (pad + 17 * bw, top - 2))\n    body.append("<text class=\'svg-val\' x=\'%d\' y=\'%d\'>%d</text>"\n                % (2, top + 9, mx))\n    return ("<svg viewBox=\'0 0 %d %d\' role=\'img\' aria-label=\'Crashes by "\n            "hour of day\'>%s</svg>" % (w, top + height + 22, "".join(body)))\n\n\ndef day_chart(counts: dict) -> str:\n    """Weekday profile as horizontal stripe bars."""\n    order = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday",\n             "Saturday", "Sunday"]\n    rows = [(d[:3], "", int(counts.get(d, 0) or 0)) for d in order]\n    return stripe_rows(rows, maxw=300)\n\n\ndef prop_bar(parts: list[tuple]) -> str:\n    """Stacked proportion bar. parts = [(label, value, colour)]."""\n    tot = sum(max(p[1], 0) for p in parts) or 1\n    segs, keys = [], []\n    for lab, v, col in parts:\n        if v <= 0:\n            continue\n        pct = 100.0 * v / tot\n        segs.append("<div style=\'width:%.2f%%;background:%s\' title=\'%s: %d "\n                    "(%.0f%%)\'>%s</div>"\n                    % (pct, col, esc(lab), v, pct,\n                       ("%.0f%%" % pct) if pct >= 11 else ""))\n        keys.append("<span><i style=\'background:%s\'></i>%s <b>%d</b></span>"\n                    % (col, esc(lab), v))\n    return ("<div class=\'prop\'>" + "".join(segs) + "</div>"\n            "<div class=\'prop-key\'>" + "".join(keys) + "</div>")\n\n\ndef month_chart(series: list[tuple], height: int = 92) -> str:\n    """series = [(month label, count)] as a column chart with the value\n    printed above each column — trend plus exact figures."""\n    if not series:\n        return ""\n    mx = max(v for _, v in series) or 1\n    w, pad, top = 720, 30, 18\n    n = len(series)\n    bw = (w - pad * 2) / max(n, 1)\n    body = []\n    for i, (lab, v) in enumerate(series):\n        bh = (v / mx) * height\n        x = pad + i * bw\n        body.append("<rect x=\'%.1f\' y=\'%.1f\' width=\'%.1f\' height=\'%.1f\' "\n                    "fill=\'var(--accent)\' opacity=\'.82\' rx=\'1\'/>"\n                    % (x + bw * .18, top + height - bh, bw * .64,\n                       max(bh, 1.0)))\n        body.append("<text class=\'svg-val\' x=\'%.1f\' y=\'%.1f\' "\n                    "text-anchor=\'middle\'>%d</text>"\n                    % (x + bw / 2, top + height - bh - 5, v))\n        body.append("<text class=\'svg-lab\' x=\'%.1f\' y=\'%.1f\' "\n                    "text-anchor=\'middle\'>%s</text>"\n                    % (x + bw / 2, top + height + 15, esc(lab)))\n    return ("<svg viewBox=\'0 0 %d %d\' role=\'img\' aria-label=\'Crashes "\n            "recorded per month\'>%s</svg>"\n            % (w, top + height + 22, "".join(body)))\n\n\ndef funnel(stages: list[tuple]) -> str:\n    """Gate funnel. stages = [(label, count, note)]. Shows how many\n    locations survive each publication gate — the honest answer to\n    \'why isn\'t my location in the report?\'."""\n    if not stages:\n        return ""\n    mx = max(c for _, c, _ in stages) or 1\n    w, rowh, pad = 720, 34, 4\n    body = []\n    for i, (lab, c, note) in enumerate(stages):\n        y = pad + i * rowh\n        bw = max(2.0, (c / mx) * 330)\n        body.append("<rect x=\'150\' y=\'%d\' width=\'%.1f\' height=\'18\' rx=\'1\' "\n                    "fill=\'var(--accent)\' opacity=\'%.2f\'/>"\n                    % (y, bw, 0.92 - i * 0.13))\n        body.append("<text class=\'svg-lab\' x=\'142\' y=\'%d\' text-anchor=\'end\'>"\n                    "%s</text>" % (y + 13, esc(lab)))\n        body.append("<text class=\'svg-val\' x=\'%.1f\' y=\'%d\'>%d</text>"\n                    % (150 + bw + 7, y + 13, c))\n        if note:\n            body.append("<text class=\'svg-lab\' x=\'%.1f\' y=\'%d\' "\n                        "opacity=\'.85\'>%s</text>"\n                        % (150 + bw + 7 + 12 + len(str(c)) * 7, y + 13,\n                           esc(note)))\n    return ("<svg viewBox=\'0 0 %d %d\' role=\'img\' aria-label=\'Publication "\n            "gate funnel\'>%s</svg>"\n            % (w, pad * 2 + len(stages) * rowh, "".join(body)))\n\n\ndef sparkpath(path: list, w: int = 300, h: int = 74) -> str:\n    """Plot a corridor\'s crash coordinates as a mini route sketch — an\n    at-a-glance sense of whether crashes string along the road evenly or\n    bunch at one end. Not a map: no basemap, no scale claim."""\n    pts = [(float(p[0]), float(p[1])) for p in (path or [])\n           if p and len(p) >= 2]\n    if len(pts) < 2:\n        return ""\n    lats = [p[0] for p in pts]\n    lons = [p[1] for p in pts]\n    la0, la1 = min(lats), max(lats)\n    lo0, lo1 = min(lons), max(lons)\n    dla, dlo = max(la1 - la0, 1e-6), max(lo1 - lo0, 1e-6)\n    m = 10\n\n    def xy(p):\n        x = m + (p[1] - lo0) / dlo * (w - 2 * m)\n        y = h - m - (p[0] - la0) / dla * (h - 2 * m)\n        return x, y\n\n    segs = []\n    for i, p in enumerate(pts):\n        x, y = xy(p)\n        segs.append("%s%.1f %.1f" % ("M" if i == 0 else "L", x, y))\n    d = " ".join(segs)\n    dots = "".join("<circle cx=\'%.1f\' cy=\'%.1f\' r=\'2.6\' fill=\'var(--accent)\' "\n                   "opacity=\'.75\'/>" % xy(p) for p in pts)\n    return ("<svg viewBox=\'0 0 %d %d\' role=\'img\' aria-label=\'Crash "\n            "positions along the corridor\'><path d=\'%s\' fill=\'none\' "\n            "stroke=\'var(--accent)\' stroke-width=\'1.6\' opacity=\'.35\' "\n            "stroke-dasharray=\'5 4\'/>%s</svg>" % (w, h, d, dots))\n\n\ndef detail(summary_html: str, body_html: str, right: str = "",\n           open_: bool = False) -> str:\n    return ("<details%s><summary><span class=\'car\'>&#9656;</span>"\n            "<span>%s</span><span>%s</span></summary>"\n            "<div class=\'det-body\'>%s</div></details>"\n            % (" open" if open_ else "", summary_html, right, body_html))\n\n\ndef foot(text: str) -> str:\n    return "<div class=\'foot\'>" + text + "</div>"\n\n\ndef close() -> str:\n    return "</div></body></html>"\n\n\ndef open_wrap() -> str:\n    return "<div class=\'wrap\'>"\n'
_FILES['ui.py'] = '"""\nShared presentation layer for every page the forecaster publishes.\n\nOne design system, one tab bar, one set of chart primitives, so the map,\nthe two public-safety reports and the ad ops sheet read as one site\ninstead of four separately-invented HTML documents.\n\nDesign direction — "highway instrumentation": the visual vocabulary is\nborrowed from the roads the data describes. Condensed signage type for\nheadings, a serif reading face for prose, tabular mono for numbers.\nThe signature element is the STRIPE BAR: every bar chart is drawn as\nlane striping where one dash = one recorded crash, so a reader can\nliterally count the evidence instead of trusting a bar\'s length.\n\nNothing here fetches or computes anything; callers pass finished numbers.\nNo external fonts, no CDN, no JS libraries — these pages are committed to\na repo and served as static files, so they must render offline and\nsurvive Pages caching forever.\n"""\nfrom __future__ import annotations\n\nimport html as _html\n\n# --- palette -------------------------------------------------------------\n# Accents are page identities, drawn from Indiana highway sign colours:\n# guide-sign green (public safety), interstate-shield blue (policy),\n# work-zone orange-brown (internal ops). Deliberately NOT interchangeable\n# — the accent is how a reader knows which page they\'re on before reading.\nACCENTS = {\n    "safety": "#14603C",   # INDOT guide-sign green\n    "brief": "#1B3A6B",    # interstate shield blue\n    "ops": "#8C3A12",      # work-zone orange, darkened for text contrast\n    "map": "#14603C",\n}\n\n\ndef esc(x) -> str:\n    return _html.escape(str(x))\n\n\ndef _tokens(accent: str) -> str:\n    return (\n        ":root{"\n        "--ink:#12171C;--ink2:#3D4750;--ink3:#6E7880;"\n        "--paper:#F5F7F4;--surface:#FFFFFF;--sunk:#EEF1EC;"\n        "--line:#D9DFD8;--line2:#EBEFE9;"\n        "--accent:%s;--accent-w:color-mix(in srgb,var(--accent) 12%%,white);"\n        "--accent-m:color-mix(in srgb,var(--accent) 45%%,white);"\n        "--amber:#B9861B;--amber-w:#FBF3DF;"\n        "--danger:#9E2B2B;--danger-w:#FBEDED;"\n        "--ok:#14603C;"\n        "--display:\'Oswald\',\'Archivo Narrow\',\'Roboto Condensed\',"\n        "\'Franklin Gothic Medium\',\'Arial Narrow\',system-ui,sans-serif;"\n        "--body:Charter,\'Bitstream Charter\',\'Iowan Old Style\',"\n        "\'Source Serif 4\',Georgia,\'Times New Roman\',serif;"\n        "--data:ui-monospace,\'SF Mono\',\'Cascadia Mono\',\'Segoe UI Mono\',"\n        "Consolas,monospace;"\n        "--r:3px}" % accent\n    )\n\n\n_STRUCTURE = """\n*{box-sizing:border-box}\nhtml{-webkit-text-size-adjust:100%}\nbody{margin:0;background:var(--paper);color:var(--ink);\nfont-family:var(--body);font-size:16.5px;line-height:1.6;\nfont-feature-settings:"kern" 1}\n.wrap{max-width:940px;margin:0 auto;padding:0 20px 72px}\na{color:var(--accent);text-underline-offset:2px}\na:hover{text-decoration-thickness:2px}\n:focus-visible{outline:3px solid var(--accent);outline-offset:2px}\n\n/* --- sign gantry: the tab bar ------------------------------------- */\n.gantry{position:sticky;top:0;z-index:900;background:var(--surface);\nborder-bottom:1px solid var(--line);\nbox-shadow:0 1px 0 rgba(18,23,28,.04),0 6px 18px -14px rgba(18,23,28,.5)}\n.gantry-in{max-width:940px;margin:0 auto;display:flex;align-items:stretch;\ngap:2px;padding:0 12px;overflow-x:auto;scrollbar-width:none}\n.gantry-in::-webkit-scrollbar{display:none}\n.tab{font-family:var(--display);font-size:13px;font-weight:600;\nletter-spacing:.09em;text-transform:uppercase;text-decoration:none;\ncolor:var(--ink3);padding:15px 14px 12px;border-bottom:3px solid transparent;\nwhite-space:nowrap;display:flex;align-items:center;gap:8px;\ntransition:color .12s,border-color .12s,background .12s}\n.tab:hover{color:var(--ink);background:var(--sunk)}\n.tab[aria-current="page"]{color:var(--accent);border-bottom-color:var(--accent)}\n.tab .dot{width:7px;height:7px;border-radius:50%;background:currentColor;\nopacity:.55;flex:0 0 auto}\n.tab[aria-current="page"] .dot{opacity:1}\n.gantry .draftflag{margin-left:auto;align-self:center;flex:0 0 auto;\nfont-family:var(--display);font-size:11px;letter-spacing:.12em;\ntext-transform:uppercase;color:var(--amber);border:1px solid var(--amber);\nborder-radius:2px;padding:3px 7px;background:var(--amber-w)}\n@media (max-width:700px){.tab{font-size:11.5px;padding:12px 10px 9px}\n.gantry .draftflag{display:none}}\n\n/* --- masthead ------------------------------------------------------ */\n.mast{padding:38px 0 20px;border-bottom:2px solid var(--ink)}\n.eyebrow{font-family:var(--display);font-size:12px;letter-spacing:.16em;\ntext-transform:uppercase;color:var(--accent);margin:0 0 10px}\nh1{font-family:var(--display);font-weight:600;font-size:clamp(30px,5vw,44px);\nline-height:1.06;letter-spacing:-.005em;margin:0 0 12px;max-width:22ch}\n.standfirst{font-size:18.5px;line-height:1.5;color:var(--ink2);margin:0;\nmax-width:60ch}\n.stamp{margin-top:16px;font-family:var(--data);font-size:12px;\ncolor:var(--ink3);letter-spacing:.02em}\n\n/* --- sections: milepost headings ----------------------------------- */\nh2{font-family:var(--display);font-weight:600;font-size:23px;\nletter-spacing:.005em;margin:52px 0 14px;padding-left:0;\ndisplay:flex;align-items:baseline;gap:12px}\nh2 .post{font-size:12px;letter-spacing:.12em;color:var(--accent);\nborder:1.5px solid var(--accent);border-radius:2px;padding:2px 6px;\nflex:0 0 auto;position:relative;top:-3px}\nh3{font-family:var(--display);font-weight:600;font-size:18px;margin:0 0 6px;\nletter-spacing:.01em}\np{margin:0 0 14px}\n.lede{font-size:17.5px;color:var(--ink2)}\n.small,small{font-size:13.5px;color:var(--ink3);line-height:1.5}\n.hint{font-size:13.5px;color:var(--ink3);line-height:1.55;margin-top:10px;\npadding-left:12px;border-left:2px solid var(--line)}\n\n/* --- cards --------------------------------------------------------- */\n.card{background:var(--surface);border:1px solid var(--line);\nborder-radius:var(--r);padding:20px 22px;margin:16px 0}\n.card.rank{border-left:4px solid var(--accent)}\n.card-h{display:flex;justify-content:space-between;align-items:flex-start;\ngap:16px;flex-wrap:wrap;margin-bottom:10px}\n.where{font-family:var(--display);font-size:20px;font-weight:600;\nline-height:1.2}\n.where .cty{display:block;font-size:12.5px;letter-spacing:.1em;\ntext-transform:uppercase;color:var(--ink3);font-weight:500;margin-top:3px}\n.kicker{font-family:var(--display);font-size:11.5px;letter-spacing:.11em;\ntext-transform:uppercase;color:var(--ink3)}\n\n/* --- chips --------------------------------------------------------- */\n.chip{display:inline-flex;align-items:center;gap:5px;font-family:var(--display);\nfont-size:11.5px;letter-spacing:.08em;text-transform:uppercase;\npadding:3px 8px;border-radius:2px;border:1px solid var(--line);\ncolor:var(--ink2);background:var(--sunk);white-space:nowrap}\n.chip.on{border-color:var(--accent);color:var(--accent);\nbackground:var(--accent-w)}\n.chip.good{border-color:var(--ok);color:var(--ok);\nbackground:color-mix(in srgb,var(--ok) 10%,white)}\n.chip.warn{border-color:var(--amber);color:var(--amber);\nbackground:var(--amber-w)}\n.chip.bad{border-color:var(--danger);color:var(--danger);\nbackground:var(--danger-w)}\n.chips{display:flex;flex-wrap:wrap;gap:6px;margin:10px 0}\n\n/* --- the signature: stripe bars ------------------------------------ */\n.stripe-row{display:grid;grid-template-columns:minmax(0,1fr) auto;\nalign-items:center;gap:14px;padding:7px 0;border-bottom:1px solid var(--line2)}\n.stripe-row:last-child{border-bottom:0}\n.stripe-lab{font-size:14.5px;line-height:1.3;min-width:0}\n.stripe-lab b{font-family:var(--display);font-weight:600}\n.stripe-lab span{display:block;font-size:12px;color:var(--ink3);\nletter-spacing:.06em;text-transform:uppercase;font-family:var(--display)}\n.stripe-wrap{display:flex;align-items:center;gap:10px;justify-self:end}\n.stripe{height:13px;border-radius:1px;flex:0 0 auto}\n.stripe-n{font-family:var(--data);font-size:13.5px;font-weight:600;\nmin-width:2.6ch;text-align:right}\n\n/* --- tables -------------------------------------------------------- */\n.tbl-scroll{overflow-x:auto;margin:14px 0}\ntable{border-collapse:collapse;width:100%;font-size:14px;\nbackground:var(--surface)}\nth{font-family:var(--display);font-size:11.5px;letter-spacing:.09em;\ntext-transform:uppercase;text-align:left;color:var(--ink2);\nbackground:var(--sunk);border-bottom:2px solid var(--line);\npadding:9px 11px;white-space:nowrap;font-weight:600}\ntd{border-bottom:1px solid var(--line2);padding:9px 11px;vertical-align:top}\ntr:last-child td{border-bottom:0}\ntd.num,th.num{text-align:right;font-family:var(--data);\nfont-variant-numeric:tabular-nums}\ntbody tr:hover{background:var(--sunk)}\n\n/* --- disclosure ---------------------------------------------------- */\ndetails{background:var(--surface);border:1px solid var(--line);\nborder-radius:var(--r);margin:8px 0}\ndetails[open]{border-color:var(--accent-m)}\nsummary{cursor:pointer;padding:12px 16px;list-style:none;\ndisplay:grid;grid-template-columns:auto minmax(0,1fr) auto;\nalign-items:center;gap:12px}\nsummary::-webkit-details-marker{display:none}\nsummary:hover{background:var(--sunk)}\nsummary .car{font-family:var(--data);font-size:11px;color:var(--ink3);\ntransition:transform .15s}\ndetails[open] summary .car{transform:rotate(90deg)}\n@media (prefers-reduced-motion:reduce){summary .car{transition:none}}\n.det-body{padding:2px 16px 16px;border-top:1px solid var(--line2);\nmargin-top:2px}\n\n/* --- callouts ------------------------------------------------------ */\n.note{border:1px solid var(--line);border-left:4px solid var(--ink3);\nbackground:var(--surface);padding:14px 16px;margin:16px 0;font-size:14.5px;\nline-height:1.55;border-radius:var(--r)}\n.note.draft{border-left-color:var(--amber);background:var(--amber-w)}\n.note.hold{border-left-color:var(--danger);background:var(--danger-w)}\n.note.good{border-left-color:var(--ok)}\n.note b{font-family:var(--display);letter-spacing:.02em}\n\n/* --- key figures --------------------------------------------------- */\n.figs{display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));\ngap:1px;background:var(--line);border:1px solid var(--line);\nborder-radius:var(--r);overflow:hidden;margin:18px 0}\n.fig{background:var(--surface);padding:14px 16px}\n.fig .v{font-family:var(--display);font-size:30px;font-weight:600;\nline-height:1;color:var(--accent);font-variant-numeric:tabular-nums}\n.fig .k{font-family:var(--display);font-size:11px;letter-spacing:.1em;\ntext-transform:uppercase;color:var(--ink3);margin-top:6px}\n.fig .sub{font-size:12.5px;color:var(--ink3);margin-top:4px;line-height:1.4}\n\n/* --- charts -------------------------------------------------------- */\nfigure{margin:18px 0}\nfigcaption{font-size:13px;color:var(--ink3);line-height:1.5;margin-top:8px}\nsvg{display:block;max-width:100%;height:auto}\n.svg-lab{font-family:var(--display);font-size:10.5px;letter-spacing:.08em;\ntext-transform:uppercase;fill:var(--ink3)}\n.svg-val{font-family:var(--data);font-size:10.5px;fill:var(--ink2)}\n\n/* --- proportion bar ------------------------------------------------ */\n.prop{display:flex;height:26px;border-radius:2px;overflow:hidden;\nborder:1px solid var(--line);margin:10px 0}\n.prop div{display:flex;align-items:center;justify-content:center;\nfont-family:var(--display);font-size:11px;letter-spacing:.05em;color:#fff;\nmin-width:0;overflow:hidden}\n.prop-key{display:flex;flex-wrap:wrap;gap:12px;font-size:12.5px;\ncolor:var(--ink3);margin-top:2px}\n.prop-key i{width:10px;height:10px;border-radius:1px;display:inline-block;\nmargin-right:5px;vertical-align:-1px}\n\n/* --- footer -------------------------------------------------------- */\n.foot{margin-top:56px;padding:20px 22px;background:var(--sunk);\nborder:1px solid var(--line);border-radius:var(--r);font-size:13.5px;\nline-height:1.6;color:var(--ink2)}\n.foot b{font-family:var(--display)}\n@media print{.gantry{position:static}.card,table{break-inside:avoid}}\n"""\n\n\ndef head(title: str, accent_key: str = "safety") -> str:\n    """Opening tags + the full stylesheet for a page."""\n    return ("<!DOCTYPE html><html lang=\'en\'><head><meta charset=\'utf-8\'>"\n            "<meta name=\'viewport\' content=\'width=device-width,"\n            "initial-scale=1\'><title>" + esc(title) + "</title><style>"\n            + _tokens(ACCENTS.get(accent_key, ACCENTS["safety"]))\n            + _STRUCTURE + "</style></head><body>")\n\n\n# Page identities. Each entry: (slug, label, draft filename or None).\nPAGES = [\n    ("index.html", "Live Risk Map", None),\n    ("safety_watch.html", "Road Safety Watch", "safety_watch_draft.html"),\n    ("action_brief.html", "Hotspot Action Brief", "action_brief_draft.html"),\n    ("ad_ops.html", "Ad Ops Sheet", None),\n]\n\n\ndef tabs(current: str, draft: bool = False) -> str:\n    """Site tab bar.\n\n    `draft=True` renders the DRAFT variant: every link that HAS a draft\n    twin points at the twin, so a reviewer clicking through the review\n    copies stays inside the review copies. On published pages the links\n    point at published pages. Getting this wrong is how a reviewer ends\n    up reading a stale published page and approving it as if it were the\n    new draft.\n    """\n    out = ["<nav class=\'gantry\' aria-label=\'Report sections\'>"\n           "<div class=\'gantry-in\'>"]\n    for slug, label, draft_slug in PAGES:\n        href = draft_slug if (draft and draft_slug) else slug\n        cur = (current == slug)\n        out.append("<a class=\'tab\' href=\'%s\'%s><span class=\'dot\'></span>%s</a>"\n                   % (esc(href), " aria-current=\'page\'" if cur else "",\n                      esc(label)))\n    if draft:\n        out.append("<span class=\'draftflag\'>Draft</span>")\n    # On a narrow screen the bar scrolls horizontally, and the current\n    # page\'s tab can sit off-screen — so the reader gets no indication of\n    # where they are. Nudge it into view on load.\n    out.append("</div><script>(function(){var t=document."\n               "querySelector(\'.tab[aria-current]\');if(t&&t.scrollIntoView)"\n               "t.scrollIntoView({block:\'nearest\',inline:\'center\'});})();"\n               "</script></nav>")\n    return "".join(out)\n\n\ndef masthead(eyebrow: str, title: str, standfirst: str, stamp: str) -> str:\n    return ("<header class=\'mast\'><p class=\'eyebrow\'>" + esc(eyebrow)\n            + "</p><h1>" + esc(title) + "</h1><p class=\'standfirst\'>"\n            + esc(standfirst) + "</p><div class=\'stamp\'>" + esc(stamp)\n            + "</div></header>")\n\n\ndef h2(post: str, text: str) -> str:\n    """Section heading with a milepost tag (the tag carries the section\'s\n    short name, so it works as an in-page landmark, not decoration)."""\n    return ("<h2><span class=\'post\'>" + esc(post) + "</span>"\n            + esc(text) + "</h2>")\n\n\ndef figs(items: list[tuple]) -> str:\n    """Key-figure strip. items = [(value, label, subtext)]."""\n    cells = "".join(\n        "<div class=\'fig\'><div class=\'v\'>%s</div><div class=\'k\'>%s</div>"\n        "%s</div>"\n        % (esc(v), esc(k),\n           ("<div class=\'sub\'>%s</div>" % esc(s)) if s else "")\n        for v, k, s in items)\n    return "<div class=\'figs\'>" + cells + "</div>"\n\n\n# --- the signature chart -------------------------------------------------\n\ndef stripe(n: int, mx: int, maxw: int = 240, color: str = "var(--accent)"\n           ) -> str:\n    """Lane-striping bar: one dash = one recorded crash, so the reader can\n    count the evidence rather than estimate a bar length."""\n    mx = max(int(mx or 1), 1)\n    n = max(int(n or 0), 0)\n    per = max(2.6, min(9.0, maxw / mx))\n    dash = max(1.6, per * 0.6)\n    w = per * n\n    return ("<span class=\'stripe\' style=\'width:%.1fpx;background:"\n            "repeating-linear-gradient(90deg,%s 0 %.2fpx,transparent "\n            "%.2fpx %.2fpx)\' title=\'%d\'></span>"\n            % (w, color, dash, dash, per, n))\n\n\ndef stripe_rows(rows: list[tuple], maxw: int = 240,\n                color: str = "var(--accent)") -> str:\n    """rows = [(label, sublabel, n)] rendered as ranked stripe bars."""\n    if not rows:\n        return ""\n    mx = max(r[2] for r in rows) or 1\n    out = []\n    for lab, sub, n in rows:\n        out.append(\n            "<div class=\'stripe-row\'><div class=\'stripe-lab\'><b>%s</b>%s</div>"\n            "<div class=\'stripe-wrap\'>%s<span class=\'stripe-n\'>%d</span></div>"\n            "</div>"\n            % (esc(lab), ("<span>%s</span>" % esc(sub)) if sub else "",\n               stripe(n, mx, maxw, color), n))\n    return "".join(out)\n\n\ndef hour_chart(counts: dict, height: int = 108) -> str:\n    """24-hour crash profile with the commute windows shaded, so the\n    reader sees the peaks against the periods people actually plan\n    around rather than against an unlabelled axis."""\n    vals = [int(counts.get(h, 0) or 0) for h in range(24)]\n    mx = max(vals) or 1\n    w, pad, top = 720, 26, 12\n    bw = (w - pad * 2) / 24.0\n    body = []\n    for a, b in ((6, 10), (15, 19)):\n        body.append("<rect x=\'%.1f\' y=\'%d\' width=\'%.1f\' height=\'%d\' "\n                    "fill=\'var(--sunk)\'/>"\n                    % (pad + a * bw, top, (b - a) * bw, height))\n    for h, v in enumerate(vals):\n        bh = (v / mx) * height\n        body.append("<rect x=\'%.1f\' y=\'%.1f\' width=\'%.1f\' height=\'%.1f\' "\n                    "fill=\'var(--accent)\' opacity=\'%.2f\'><title>%02d:00 — "\n                    "%d crashes</title></rect>"\n                    % (pad + h * bw + 1.2, top + height - bh, bw - 2.4,\n                       max(bh, 0.8), 0.45 + 0.55 * (v / mx), h, v))\n    for h in (0, 6, 12, 18, 23):\n        body.append("<text class=\'svg-lab\' x=\'%.1f\' y=\'%d\' "\n                    "text-anchor=\'middle\'>%02d</text>"\n                    % (pad + h * bw + bw / 2, top + height + 15, h))\n    body.append("<text class=\'svg-lab\' x=\'%.1f\' y=\'%d\' text-anchor=\'middle\'>"\n                "AM peak</text>" % (pad + 8 * bw, top - 2))\n    body.append("<text class=\'svg-lab\' x=\'%.1f\' y=\'%d\' text-anchor=\'middle\'>"\n                "PM peak</text>" % (pad + 17 * bw, top - 2))\n    body.append("<text class=\'svg-val\' x=\'%d\' y=\'%d\'>%d</text>"\n                % (2, top + 9, mx))\n    return ("<svg viewBox=\'0 0 %d %d\' role=\'img\' aria-label=\'Crashes by "\n            "hour of day\'>%s</svg>" % (w, top + height + 22, "".join(body)))\n\n\ndef day_chart(counts: dict) -> str:\n    """Weekday profile as horizontal stripe bars."""\n    order = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday",\n             "Saturday", "Sunday"]\n    rows = [(d[:3], "", int(counts.get(d, 0) or 0)) for d in order]\n    return stripe_rows(rows, maxw=300)\n\n\ndef prop_bar(parts: list[tuple]) -> str:\n    """Stacked proportion bar. parts = [(label, value, colour)]."""\n    tot = sum(max(p[1], 0) for p in parts) or 1\n    segs, keys = [], []\n    for lab, v, col in parts:\n        if v <= 0:\n            continue\n        pct = 100.0 * v / tot\n        segs.append("<div style=\'width:%.2f%%;background:%s\' title=\'%s: %d "\n                    "(%.0f%%)\'>%s</div>"\n                    % (pct, col, esc(lab), v, pct,\n                       ("%.0f%%" % pct) if pct >= 11 else ""))\n        keys.append("<span><i style=\'background:%s\'></i>%s <b>%d</b></span>"\n                    % (col, esc(lab), v))\n    return ("<div class=\'prop\'>" + "".join(segs) + "</div>"\n            "<div class=\'prop-key\'>" + "".join(keys) + "</div>")\n\n\ndef month_chart(series: list[tuple], height: int = 92) -> str:\n    """series = [(month label, count)] as a column chart with the value\n    printed above each column — trend plus exact figures."""\n    if not series:\n        return ""\n    mx = max(v for _, v in series) or 1\n    w, pad, top = 720, 30, 18\n    n = len(series)\n    bw = (w - pad * 2) / max(n, 1)\n    body = []\n    for i, (lab, v) in enumerate(series):\n        bh = (v / mx) * height\n        x = pad + i * bw\n        body.append("<rect x=\'%.1f\' y=\'%.1f\' width=\'%.1f\' height=\'%.1f\' "\n                    "fill=\'var(--accent)\' opacity=\'.82\' rx=\'1\'/>"\n                    % (x + bw * .18, top + height - bh, bw * .64,\n                       max(bh, 1.0)))\n        body.append("<text class=\'svg-val\' x=\'%.1f\' y=\'%.1f\' "\n                    "text-anchor=\'middle\'>%d</text>"\n                    % (x + bw / 2, top + height - bh - 5, v))\n        body.append("<text class=\'svg-lab\' x=\'%.1f\' y=\'%.1f\' "\n                    "text-anchor=\'middle\'>%s</text>"\n                    % (x + bw / 2, top + height + 15, esc(lab)))\n    return ("<svg viewBox=\'0 0 %d %d\' role=\'img\' aria-label=\'Crashes "\n            "recorded per month\'>%s</svg>"\n            % (w, top + height + 22, "".join(body)))\n\n\ndef funnel(stages: list[tuple]) -> str:\n    """Gate funnel. stages = [(label, count, note)]. Shows how many\n    locations survive each publication gate — the honest answer to\n    \'why isn\'t my location in the report?\'."""\n    if not stages:\n        return ""\n    mx = max(c for _, c, _ in stages) or 1\n    w, rowh, pad = 720, 34, 4\n    body = []\n    for i, (lab, c, note) in enumerate(stages):\n        y = pad + i * rowh\n        bw = max(2.0, (c / mx) * 330)\n        body.append("<rect x=\'150\' y=\'%d\' width=\'%.1f\' height=\'18\' rx=\'1\' "\n                    "fill=\'var(--accent)\' opacity=\'%.2f\'/>"\n                    % (y, bw, 0.92 - i * 0.13))\n        body.append("<text class=\'svg-lab\' x=\'142\' y=\'%d\' text-anchor=\'end\'>"\n                    "%s</text>" % (y + 13, esc(lab)))\n        body.append("<text class=\'svg-val\' x=\'%.1f\' y=\'%d\'>%d</text>"\n                    % (150 + bw + 7, y + 13, c))\n        if note:\n            body.append("<text class=\'svg-lab\' x=\'%.1f\' y=\'%d\' "\n                        "opacity=\'.85\'>%s</text>"\n                        % (150 + bw + 7 + 12 + len(str(c)) * 7, y + 13,\n                           esc(note)))\n    return ("<svg viewBox=\'0 0 %d %d\' role=\'img\' aria-label=\'Publication "\n            "gate funnel\'>%s</svg>"\n            % (w, pad * 2 + len(stages) * rowh, "".join(body)))\n\n\ndef sparkpath(path: list, w: int = 300, h: int = 74) -> str:\n    """Plot a corridor\'s crash coordinates as a mini route sketch — an\n    at-a-glance sense of whether crashes string along the road evenly or\n    bunch at one end. Not a map: no basemap, no scale claim."""\n    pts = [(float(p[0]), float(p[1])) for p in (path or [])\n           if p and len(p) >= 2]\n    if len(pts) < 2:\n        return ""\n    lats = [p[0] for p in pts]\n    lons = [p[1] for p in pts]\n    la0, la1 = min(lats), max(lats)\n    lo0, lo1 = min(lons), max(lons)\n    dla, dlo = max(la1 - la0, 1e-6), max(lo1 - lo0, 1e-6)\n    m = 10\n\n    def xy(p):\n        x = m + (p[1] - lo0) / dlo * (w - 2 * m)\n        y = h - m - (p[0] - la0) / dla * (h - 2 * m)\n        return x, y\n\n    segs = []\n    for i, p in enumerate(pts):\n        x, y = xy(p)\n        segs.append("%s%.1f %.1f" % ("M" if i == 0 else "L", x, y))\n    d = " ".join(segs)\n    dots = "".join("<circle cx=\'%.1f\' cy=\'%.1f\' r=\'2.6\' fill=\'var(--accent)\' "\n                   "opacity=\'.75\'/>" % xy(p) for p in pts)\n    return ("<svg viewBox=\'0 0 %d %d\' role=\'img\' aria-label=\'Crash "\n            "positions along the corridor\'><path d=\'%s\' fill=\'none\' "\n            "stroke=\'var(--accent)\' stroke-width=\'1.6\' opacity=\'.35\' "\n            "stroke-dasharray=\'5 4\'/>%s</svg>" % (w, h, d, dots))\n\n\ndef detail(summary_html: str, body_html: str, right: str = "",\n           open_: bool = False) -> str:\n    return ("<details%s><summary><span class=\'car\'>&#9656;</span>"\n            "<span>%s</span><span>%s</span></summary>"\n            "<div class=\'det-body\'>%s</div></details>"\n            % (" open" if open_ else "", summary_html, right, body_html))\n\n\ndef foot(text: str) -> str:\n    return "<div class=\'foot\'>" + text + "</div>"\n\n\ndef close() -> str:\n    return "</div></body></html>"\n\n\ndef open_wrap() -> str:\n    return "<div class=\'wrap\'>"\n'
_FILES['ui.py'] = '"""\nShared presentation layer for every page the forecaster publishes.\n\nOne design system, one tab bar, one set of chart primitives, so the map,\nthe two public-safety reports and the ad ops sheet read as one site\ninstead of four separately-invented HTML documents.\n\nDesign direction — "highway instrumentation": the visual vocabulary is\nborrowed from the roads the data describes. Condensed signage type for\nheadings, a serif reading face for prose, tabular mono for numbers.\nThe signature element is the STRIPE BAR: every bar chart is drawn as\nlane striping where one dash = one recorded crash, so a reader can\nliterally count the evidence instead of trusting a bar\'s length.\n\nNothing here fetches or computes anything; callers pass finished numbers.\nNo external fonts, no CDN, no JS libraries — these pages are committed to\na repo and served as static files, so they must render offline and\nsurvive Pages caching forever.\n"""\nfrom __future__ import annotations\n\nimport html as _html\n\n# --- palette -------------------------------------------------------------\n# Accents are page identities, drawn from Indiana highway sign colours:\n# guide-sign green (public safety), interstate-shield blue (policy),\n# work-zone orange-brown (internal ops). Deliberately NOT interchangeable\n# — the accent is how a reader knows which page they\'re on before reading.\nACCENTS = {\n    "safety": "#14603C",   # INDOT guide-sign green\n    "brief": "#1B3A6B",    # interstate shield blue\n    "ops": "#8C3A12",      # work-zone orange, darkened for text contrast\n    "map": "#14603C",\n}\n\n\ndef esc(x) -> str:\n    return _html.escape(str(x))\n\n\ndef _tokens(accent: str) -> str:\n    return (\n        ":root{"\n        "--ink:#12171C;--ink2:#3D4750;--ink3:#6E7880;"\n        "--paper:#F5F7F4;--surface:#FFFFFF;--sunk:#EEF1EC;"\n        "--line:#D9DFD8;--line2:#EBEFE9;"\n        "--accent:%s;--accent-w:color-mix(in srgb,var(--accent) 12%%,white);"\n        "--accent-m:color-mix(in srgb,var(--accent) 45%%,white);"\n        "--amber:#B9861B;--amber-w:#FBF3DF;"\n        "--danger:#9E2B2B;--danger-w:#FBEDED;"\n        "--ok:#14603C;"\n        "--display:\'Oswald\',\'Archivo Narrow\',\'Roboto Condensed\',"\n        "\'Franklin Gothic Medium\',\'Arial Narrow\',system-ui,sans-serif;"\n        "--body:Charter,\'Bitstream Charter\',\'Iowan Old Style\',"\n        "\'Source Serif 4\',Georgia,\'Times New Roman\',serif;"\n        "--data:ui-monospace,\'SF Mono\',\'Cascadia Mono\',\'Segoe UI Mono\',"\n        "Consolas,monospace;"\n        "--r:3px}" % accent\n    )\n\n\n_STRUCTURE = """\n*{box-sizing:border-box}\nhtml{-webkit-text-size-adjust:100%}\nbody{margin:0;background:var(--paper);color:var(--ink);\nfont-family:var(--body);font-size:16.5px;line-height:1.6;\nfont-feature-settings:"kern" 1}\n.wrap{max-width:940px;margin:0 auto;padding:0 20px 72px}\na{color:var(--accent);text-underline-offset:2px}\na:hover{text-decoration-thickness:2px}\n:focus-visible{outline:3px solid var(--accent);outline-offset:2px}\n\n/* --- sign gantry: the tab bar ------------------------------------- */\n.gantry{position:sticky;top:0;z-index:900;background:var(--surface);\nborder-bottom:1px solid var(--line);\nbox-shadow:0 1px 0 rgba(18,23,28,.04),0 6px 18px -14px rgba(18,23,28,.5)}\n.gantry-in{max-width:940px;margin:0 auto;display:flex;align-items:stretch;\ngap:2px;padding:0 12px;overflow-x:auto;scrollbar-width:none}\n.gantry-in::-webkit-scrollbar{display:none}\n.tab{font-family:var(--display);font-size:13px;font-weight:600;\nletter-spacing:.09em;text-transform:uppercase;text-decoration:none;\ncolor:var(--ink3);padding:15px 14px 12px;border-bottom:3px solid transparent;\nwhite-space:nowrap;display:flex;align-items:center;gap:8px;\ntransition:color .12s,border-color .12s,background .12s}\n.tab:hover{color:var(--ink);background:var(--sunk)}\n.tab[aria-current="page"]{color:var(--accent);border-bottom-color:var(--accent)}\n.tab .dot{width:7px;height:7px;border-radius:50%;background:currentColor;\nopacity:.55;flex:0 0 auto}\n.tab[aria-current="page"] .dot{opacity:1}\n.gantry .draftflag{margin-left:auto;align-self:center;flex:0 0 auto;\nfont-family:var(--display);font-size:11px;letter-spacing:.12em;\ntext-transform:uppercase;color:var(--amber);border:1px solid var(--amber);\nborder-radius:2px;padding:3px 7px;background:var(--amber-w)}\n@media (max-width:700px){.tab{font-size:11.5px;padding:12px 10px 9px}\n.gantry .draftflag{display:none}}\n\n/* --- masthead ------------------------------------------------------ */\n.mast{padding:38px 0 20px;border-bottom:2px solid var(--ink)}\n.eyebrow{font-family:var(--display);font-size:12px;letter-spacing:.16em;\ntext-transform:uppercase;color:var(--accent);margin:0 0 10px}\nh1{font-family:var(--display);font-weight:600;font-size:clamp(30px,5vw,44px);\nline-height:1.06;letter-spacing:-.005em;margin:0 0 12px;max-width:22ch}\n.standfirst{font-size:18.5px;line-height:1.5;color:var(--ink2);margin:0;\nmax-width:60ch}\n.stamp{margin-top:16px;font-family:var(--data);font-size:12px;\ncolor:var(--ink3);letter-spacing:.02em}\n\n/* --- sections: milepost headings ----------------------------------- */\nh2{font-family:var(--display);font-weight:600;font-size:23px;\nletter-spacing:.005em;margin:52px 0 14px;padding-left:0;\ndisplay:flex;align-items:baseline;gap:12px}\nh2 .post{font-size:12px;letter-spacing:.12em;color:var(--accent);\nborder:1.5px solid var(--accent);border-radius:2px;padding:2px 6px;\nflex:0 0 auto;position:relative;top:-3px}\nh3{font-family:var(--display);font-weight:600;font-size:18px;margin:0 0 6px;\nletter-spacing:.01em}\np{margin:0 0 14px}\n.lede{font-size:17.5px;color:var(--ink2)}\n.small,small{font-size:13.5px;color:var(--ink3);line-height:1.5}\n.hint{font-size:13.5px;color:var(--ink3);line-height:1.55;margin-top:10px;\npadding-left:12px;border-left:2px solid var(--line)}\n\n/* --- cards --------------------------------------------------------- */\n.card{background:var(--surface);border:1px solid var(--line);\nborder-radius:var(--r);padding:20px 22px;margin:16px 0}\n.card.rank{border-left:4px solid var(--accent)}\n.card-h{display:flex;justify-content:space-between;align-items:flex-start;\ngap:16px;flex-wrap:wrap;margin-bottom:10px}\n.where{font-family:var(--display);font-size:20px;font-weight:600;\nline-height:1.2}\n.where .cty{display:block;font-size:12.5px;letter-spacing:.1em;\ntext-transform:uppercase;color:var(--ink3);font-weight:500;margin-top:3px}\n.kicker{font-family:var(--display);font-size:11.5px;letter-spacing:.11em;\ntext-transform:uppercase;color:var(--ink3)}\n\n/* --- chips --------------------------------------------------------- */\n.chip{display:inline-flex;align-items:center;gap:5px;font-family:var(--display);\nfont-size:11.5px;letter-spacing:.08em;text-transform:uppercase;\npadding:3px 8px;border-radius:2px;border:1px solid var(--line);\ncolor:var(--ink2);background:var(--sunk);white-space:nowrap}\n.chip.on{border-color:var(--accent);color:var(--accent);\nbackground:var(--accent-w)}\n.chip.good{border-color:var(--ok);color:var(--ok);\nbackground:color-mix(in srgb,var(--ok) 10%,white)}\n.chip.warn{border-color:var(--amber);color:var(--amber);\nbackground:var(--amber-w)}\n.chip.bad{border-color:var(--danger);color:var(--danger);\nbackground:var(--danger-w)}\n.chips{display:flex;flex-wrap:wrap;gap:6px;margin:10px 0}\n\n/* --- the signature: stripe bars ------------------------------------ */\n.stripe-row{display:grid;grid-template-columns:minmax(0,1fr) auto;\nalign-items:center;gap:14px;padding:7px 0;border-bottom:1px solid var(--line2)}\n.stripe-row:last-child{border-bottom:0}\n.stripe-lab{font-size:14.5px;line-height:1.3;min-width:0}\n.stripe-lab b{font-family:var(--display);font-weight:600}\n.stripe-lab span{display:block;font-size:12px;color:var(--ink3);\nletter-spacing:.06em;text-transform:uppercase;font-family:var(--display)}\n.stripe-wrap{display:flex;align-items:center;gap:10px;justify-self:end}\n.stripe{height:13px;border-radius:1px;flex:0 0 auto}\n.stripe-n{font-family:var(--data);font-size:13.5px;font-weight:600;\nmin-width:2.6ch;text-align:right}\n\n/* --- tables -------------------------------------------------------- */\n.tbl-scroll{overflow-x:auto;margin:14px 0}\ntable{border-collapse:collapse;width:100%;font-size:14px;\nbackground:var(--surface)}\nth{font-family:var(--display);font-size:11.5px;letter-spacing:.09em;\ntext-transform:uppercase;text-align:left;color:var(--ink2);\nbackground:var(--sunk);border-bottom:2px solid var(--line);\npadding:9px 11px;white-space:nowrap;font-weight:600}\ntd{border-bottom:1px solid var(--line2);padding:9px 11px;vertical-align:top}\ntr:last-child td{border-bottom:0}\ntd.num,th.num{text-align:right;font-family:var(--data);\nfont-variant-numeric:tabular-nums}\ntbody tr:hover{background:var(--sunk)}\n\n/* --- disclosure ---------------------------------------------------- */\ndetails{background:var(--surface);border:1px solid var(--line);\nborder-radius:var(--r);margin:8px 0}\ndetails[open]{border-color:var(--accent-m)}\nsummary{cursor:pointer;padding:12px 16px;list-style:none;\ndisplay:grid;grid-template-columns:auto minmax(0,1fr) auto;\nalign-items:center;gap:12px}\nsummary::-webkit-details-marker{display:none}\nsummary:hover{background:var(--sunk)}\nsummary .car{font-family:var(--data);font-size:11px;color:var(--ink3);\ntransition:transform .15s}\ndetails[open] summary .car{transform:rotate(90deg)}\n@media (prefers-reduced-motion:reduce){summary .car{transition:none}}\n.det-body{padding:2px 16px 16px;border-top:1px solid var(--line2);\nmargin-top:2px}\n\n/* --- callouts ------------------------------------------------------ */\n.note{border:1px solid var(--line);border-left:4px solid var(--ink3);\nbackground:var(--surface);padding:14px 16px;margin:16px 0;font-size:14.5px;\nline-height:1.55;border-radius:var(--r)}\n.note.draft{border-left-color:var(--amber);background:var(--amber-w)}\n.note.hold{border-left-color:var(--danger);background:var(--danger-w)}\n.note.good{border-left-color:var(--ok)}\n.note b{font-family:var(--display);letter-spacing:.02em}\n\n/* --- key figures --------------------------------------------------- */\n.figs{display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));\ngap:1px;background:var(--line);border:1px solid var(--line);\nborder-radius:var(--r);overflow:hidden;margin:18px 0}\n.fig{background:var(--surface);padding:14px 16px}\n.fig .v{font-family:var(--display);font-size:30px;font-weight:600;\nline-height:1;color:var(--accent);font-variant-numeric:tabular-nums}\n.fig .k{font-family:var(--display);font-size:11px;letter-spacing:.1em;\ntext-transform:uppercase;color:var(--ink3);margin-top:6px}\n.fig .sub{font-size:12.5px;color:var(--ink3);margin-top:4px;line-height:1.4}\n\n/* --- charts -------------------------------------------------------- */\nfigure{margin:18px 0}\nfigcaption{font-size:13px;color:var(--ink3);line-height:1.5;margin-top:8px}\nsvg{display:block;max-width:100%;height:auto}\n.svg-lab{font-family:var(--display);font-size:10.5px;letter-spacing:.08em;\ntext-transform:uppercase;fill:var(--ink3)}\n.svg-val{font-family:var(--data);font-size:10.5px;fill:var(--ink2)}\n\n/* --- proportion bar ------------------------------------------------ */\n.prop{display:flex;height:26px;border-radius:2px;overflow:hidden;\nborder:1px solid var(--line);margin:10px 0}\n.prop div{display:flex;align-items:center;justify-content:center;\nfont-family:var(--display);font-size:11px;letter-spacing:.05em;color:#fff;\nmin-width:0;overflow:hidden}\n.prop-key{display:flex;flex-wrap:wrap;gap:12px;font-size:12.5px;\ncolor:var(--ink3);margin-top:2px}\n.prop-key i{width:10px;height:10px;border-radius:1px;display:inline-block;\nmargin-right:5px;vertical-align:-1px}\n\n/* --- published mode ------------------------------------------------\n   The publish step copies the draft file byte-for-byte to the public\n   URL, so the same document has to present correctly at both addresses.\n   A synchronous script in <head> sets data-published on <html> when the\n   filename lacks the _draft suffix; these rules then drop the review-only\n   furniture with no flash of draft content. */\nhtml[data-published] .note.draft,\nhtml[data-published] .draftflag{display:none}\n\n/* --- footer -------------------------------------------------------- */\n.foot{margin-top:56px;padding:20px 22px;background:var(--sunk);\nborder:1px solid var(--line);border-radius:var(--r);font-size:13.5px;\nline-height:1.6;color:var(--ink2)}\n.foot b{font-family:var(--display)}\n@media print{.gantry{position:static}.card,table{break-inside:avoid}}\n"""\n\n\n# Runs synchronously in <head> so the draft banner never flashes on the\n# published copy. The workflow publishes by copying safety_watch_draft.html\n# to safety_watch.html unchanged — deliberately, so the reviewer approves\n# exactly the bytes that go live — which means one file must render as a\n# draft at one URL and as the published report at the other.\n_PUBLISHED_JS = (\n    "<script>(function(){var p=!/_draft\\\\.html$/.test("\n    "location.pathname);if(!p)return;document.documentElement"\n    ".setAttribute(\'data-published\',\'1\');document.addEventListener("\n    "\'DOMContentLoaded\',function(){document.querySelectorAll("\n    "\'a[href$=\\"_draft.html\\"]\').forEach(function(a){a.setAttribute("\n    "\'href\',a.getAttribute(\'href\').replace(\'_draft.html\',\'.html\'));});"\n    "});})();</script>")\n\n\ndef head(title: str, accent_key: str = "safety") -> str:\n    """Opening tags + the full stylesheet for a page."""\n    return ("<!DOCTYPE html><html lang=\'en\'><head><meta charset=\'utf-8\'>"\n            "<meta name=\'viewport\' content=\'width=device-width,"\n            "initial-scale=1\'><title>" + esc(title) + "</title><style>"\n            + _tokens(ACCENTS.get(accent_key, ACCENTS["safety"]))\n            + _STRUCTURE + "</style>" + _PUBLISHED_JS + "</head><body>")\n\n\n# Page identities. Each entry: (slug, label, draft filename or None).\nPAGES = [\n    ("index.html", "Live Risk Map", None),\n    ("safety_watch.html", "Road Safety Watch", "safety_watch_draft.html"),\n    ("action_brief.html", "Hotspot Action Brief", "action_brief_draft.html"),\n    ("ad_ops.html", "Ad Ops Sheet", None),\n]\n\n\ndef tabs(current: str, draft: bool = False) -> str:\n    """Site tab bar.\n\n    `draft=True` renders the DRAFT variant: every link that HAS a draft\n    twin points at the twin, so a reviewer clicking through the review\n    copies stays inside the review copies. On published pages the links\n    point at published pages. Getting this wrong is how a reviewer ends\n    up reading a stale published page and approving it as if it were the\n    new draft.\n    """\n    out = ["<nav class=\'gantry\' aria-label=\'Report sections\'>"\n           "<div class=\'gantry-in\'>"]\n    for slug, label, draft_slug in PAGES:\n        href = draft_slug if (draft and draft_slug) else slug\n        cur = (current == slug)\n        out.append("<a class=\'tab\' href=\'%s\'%s><span class=\'dot\'></span>%s</a>"\n                   % (esc(href), " aria-current=\'page\'" if cur else "",\n                      esc(label)))\n    if draft:\n        out.append("<span class=\'draftflag\'>Draft</span>")\n    # On a narrow screen the bar scrolls horizontally, and the current\n    # page\'s tab can sit off-screen — so the reader gets no indication of\n    # where they are. Nudge it into view on load.\n    out.append("</div><script>(function(){var t=document."\n               "querySelector(\'.tab[aria-current]\');if(t&&t.scrollIntoView)"\n               "t.scrollIntoView({block:\'nearest\',inline:\'center\'});})();"\n               "</script></nav>")\n    return "".join(out)\n\n\ndef masthead(eyebrow: str, title: str, standfirst: str, stamp: str) -> str:\n    return ("<header class=\'mast\'><p class=\'eyebrow\'>" + esc(eyebrow)\n            + "</p><h1>" + esc(title) + "</h1><p class=\'standfirst\'>"\n            + esc(standfirst) + "</p><div class=\'stamp\'>" + esc(stamp)\n            + "</div></header>")\n\n\ndef h2(post: str, text: str) -> str:\n    """Section heading with a milepost tag (the tag carries the section\'s\n    short name, so it works as an in-page landmark, not decoration)."""\n    return ("<h2><span class=\'post\'>" + esc(post) + "</span>"\n            + esc(text) + "</h2>")\n\n\ndef figs(items: list[tuple]) -> str:\n    """Key-figure strip. items = [(value, label, subtext)]."""\n    cells = "".join(\n        "<div class=\'fig\'><div class=\'v\'>%s</div><div class=\'k\'>%s</div>"\n        "%s</div>"\n        % (esc(v), esc(k),\n           ("<div class=\'sub\'>%s</div>" % esc(s)) if s else "")\n        for v, k, s in items)\n    return "<div class=\'figs\'>" + cells + "</div>"\n\n\n# --- the signature chart -------------------------------------------------\n\ndef stripe(n: int, mx: int, maxw: int = 240, color: str = "var(--accent)"\n           ) -> str:\n    """Lane-striping bar: one dash = one recorded crash, so the reader can\n    count the evidence rather than estimate a bar length."""\n    mx = max(int(mx or 1), 1)\n    n = max(int(n or 0), 0)\n    per = max(2.6, min(9.0, maxw / mx))\n    dash = max(1.6, per * 0.6)\n    w = per * n\n    return ("<span class=\'stripe\' style=\'width:%.1fpx;background:"\n            "repeating-linear-gradient(90deg,%s 0 %.2fpx,transparent "\n            "%.2fpx %.2fpx)\' title=\'%d\'></span>"\n            % (w, color, dash, dash, per, n))\n\n\ndef stripe_rows(rows: list[tuple], maxw: int = 240,\n                color: str = "var(--accent)") -> str:\n    """rows = [(label, sublabel, n)] rendered as ranked stripe bars."""\n    if not rows:\n        return ""\n    mx = max(r[2] for r in rows) or 1\n    out = []\n    for lab, sub, n in rows:\n        out.append(\n            "<div class=\'stripe-row\'><div class=\'stripe-lab\'><b>%s</b>%s</div>"\n            "<div class=\'stripe-wrap\'>%s<span class=\'stripe-n\'>%d</span></div>"\n            "</div>"\n            % (esc(lab), ("<span>%s</span>" % esc(sub)) if sub else "",\n               stripe(n, mx, maxw, color), n))\n    return "".join(out)\n\n\ndef hour_chart(counts: dict, height: int = 108) -> str:\n    """24-hour crash profile with the commute windows shaded, so the\n    reader sees the peaks against the periods people actually plan\n    around rather than against an unlabelled axis."""\n    vals = [int(counts.get(h, 0) or 0) for h in range(24)]\n    mx = max(vals) or 1\n    w, pad, top = 720, 26, 12\n    bw = (w - pad * 2) / 24.0\n    body = []\n    for a, b in ((6, 10), (15, 19)):\n        body.append("<rect x=\'%.1f\' y=\'%d\' width=\'%.1f\' height=\'%d\' "\n                    "fill=\'var(--sunk)\'/>"\n                    % (pad + a * bw, top, (b - a) * bw, height))\n    for h, v in enumerate(vals):\n        bh = (v / mx) * height\n        body.append("<rect x=\'%.1f\' y=\'%.1f\' width=\'%.1f\' height=\'%.1f\' "\n                    "fill=\'var(--accent)\' opacity=\'%.2f\'><title>%02d:00 — "\n                    "%d crashes</title></rect>"\n                    % (pad + h * bw + 1.2, top + height - bh, bw - 2.4,\n                       max(bh, 0.8), 0.45 + 0.55 * (v / mx), h, v))\n    for h in (0, 6, 12, 18, 23):\n        body.append("<text class=\'svg-lab\' x=\'%.1f\' y=\'%d\' "\n                    "text-anchor=\'middle\'>%02d</text>"\n                    % (pad + h * bw + bw / 2, top + height + 15, h))\n    body.append("<text class=\'svg-lab\' x=\'%.1f\' y=\'%d\' text-anchor=\'middle\'>"\n                "AM peak</text>" % (pad + 8 * bw, top - 2))\n    body.append("<text class=\'svg-lab\' x=\'%.1f\' y=\'%d\' text-anchor=\'middle\'>"\n                "PM peak</text>" % (pad + 17 * bw, top - 2))\n    body.append("<text class=\'svg-val\' x=\'%d\' y=\'%d\'>%d</text>"\n                % (2, top + 9, mx))\n    return ("<svg viewBox=\'0 0 %d %d\' role=\'img\' aria-label=\'Crashes by "\n            "hour of day\'>%s</svg>" % (w, top + height + 22, "".join(body)))\n\n\ndef day_chart(counts: dict) -> str:\n    """Weekday profile as horizontal stripe bars."""\n    order = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday",\n             "Saturday", "Sunday"]\n    rows = [(d[:3], "", int(counts.get(d, 0) or 0)) for d in order]\n    return stripe_rows(rows, maxw=300)\n\n\ndef prop_bar(parts: list[tuple]) -> str:\n    """Stacked proportion bar. parts = [(label, value, colour)]."""\n    tot = sum(max(p[1], 0) for p in parts) or 1\n    segs, keys = [], []\n    for lab, v, col in parts:\n        if v <= 0:\n            continue\n        pct = 100.0 * v / tot\n        segs.append("<div style=\'width:%.2f%%;background:%s\' title=\'%s: %d "\n                    "(%.0f%%)\'>%s</div>"\n                    % (pct, col, esc(lab), v, pct,\n                       ("%.0f%%" % pct) if pct >= 11 else ""))\n        keys.append("<span><i style=\'background:%s\'></i>%s <b>%d</b></span>"\n                    % (col, esc(lab), v))\n    return ("<div class=\'prop\'>" + "".join(segs) + "</div>"\n            "<div class=\'prop-key\'>" + "".join(keys) + "</div>")\n\n\ndef month_chart(series: list[tuple], height: int = 92) -> str:\n    """series = [(month label, count)] as a column chart with the value\n    printed above each column — trend plus exact figures."""\n    if not series:\n        return ""\n    mx = max(v for _, v in series) or 1\n    w, pad, top = 720, 30, 18\n    n = len(series)\n    bw = (w - pad * 2) / max(n, 1)\n    body = []\n    for i, (lab, v) in enumerate(series):\n        bh = (v / mx) * height\n        x = pad + i * bw\n        body.append("<rect x=\'%.1f\' y=\'%.1f\' width=\'%.1f\' height=\'%.1f\' "\n                    "fill=\'var(--accent)\' opacity=\'.82\' rx=\'1\'/>"\n                    % (x + bw * .18, top + height - bh, bw * .64,\n                       max(bh, 1.0)))\n        body.append("<text class=\'svg-val\' x=\'%.1f\' y=\'%.1f\' "\n                    "text-anchor=\'middle\'>%d</text>"\n                    % (x + bw / 2, top + height - bh - 5, v))\n        body.append("<text class=\'svg-lab\' x=\'%.1f\' y=\'%.1f\' "\n                    "text-anchor=\'middle\'>%s</text>"\n                    % (x + bw / 2, top + height + 15, esc(lab)))\n    return ("<svg viewBox=\'0 0 %d %d\' role=\'img\' aria-label=\'Crashes "\n            "recorded per month\'>%s</svg>"\n            % (w, top + height + 22, "".join(body)))\n\n\ndef funnel(stages: list[tuple]) -> str:\n    """Gate funnel. stages = [(label, count, note)]. Shows how many\n    locations survive each publication gate — the honest answer to\n    \'why isn\'t my location in the report?\'."""\n    if not stages:\n        return ""\n    mx = max(c for _, c, _ in stages) or 1\n    w, rowh, pad = 720, 34, 4\n    body = []\n    for i, (lab, c, note) in enumerate(stages):\n        y = pad + i * rowh\n        bw = max(2.0, (c / mx) * 330)\n        body.append("<rect x=\'150\' y=\'%d\' width=\'%.1f\' height=\'18\' rx=\'1\' "\n                    "fill=\'var(--accent)\' opacity=\'%.2f\'/>"\n                    % (y, bw, 0.92 - i * 0.13))\n        body.append("<text class=\'svg-lab\' x=\'142\' y=\'%d\' text-anchor=\'end\'>"\n                    "%s</text>" % (y + 13, esc(lab)))\n        body.append("<text class=\'svg-val\' x=\'%.1f\' y=\'%d\'>%d</text>"\n                    % (150 + bw + 7, y + 13, c))\n        if note:\n            body.append("<text class=\'svg-lab\' x=\'%.1f\' y=\'%d\' "\n                        "opacity=\'.85\'>%s</text>"\n                        % (150 + bw + 7 + 12 + len(str(c)) * 7, y + 13,\n                           esc(note)))\n    return ("<svg viewBox=\'0 0 %d %d\' role=\'img\' aria-label=\'Publication "\n            "gate funnel\'>%s</svg>"\n            % (w, pad * 2 + len(stages) * rowh, "".join(body)))\n\n\ndef sparkpath(path: list, w: int = 300, h: int = 74) -> str:\n    """Plot a corridor\'s crash coordinates as a mini route sketch — an\n    at-a-glance sense of whether crashes string along the road evenly or\n    bunch at one end. Not a map: no basemap, no scale claim."""\n    pts = [(float(p[0]), float(p[1])) for p in (path or [])\n           if p and len(p) >= 2]\n    if len(pts) < 2:\n        return ""\n    lats = [p[0] for p in pts]\n    lons = [p[1] for p in pts]\n    la0, la1 = min(lats), max(lats)\n    lo0, lo1 = min(lons), max(lons)\n    dla, dlo = max(la1 - la0, 1e-6), max(lo1 - lo0, 1e-6)\n    m = 10\n\n    def xy(p):\n        x = m + (p[1] - lo0) / dlo * (w - 2 * m)\n        y = h - m - (p[0] - la0) / dla * (h - 2 * m)\n        return x, y\n\n    segs = []\n    for i, p in enumerate(pts):\n        x, y = xy(p)\n        segs.append("%s%.1f %.1f" % ("M" if i == 0 else "L", x, y))\n    d = " ".join(segs)\n    dots = "".join("<circle cx=\'%.1f\' cy=\'%.1f\' r=\'2.6\' fill=\'var(--accent)\' "\n                   "opacity=\'.75\'/>" % xy(p) for p in pts)\n    return ("<svg viewBox=\'0 0 %d %d\' role=\'img\' aria-label=\'Crash "\n            "positions along the corridor\'><path d=\'%s\' fill=\'none\' "\n            "stroke=\'var(--accent)\' stroke-width=\'1.6\' opacity=\'.35\' "\n            "stroke-dasharray=\'5 4\'/>%s</svg>" % (w, h, d, dots))\n\n\ndef detail(summary_html: str, body_html: str, right: str = "",\n           open_: bool = False) -> str:\n    return ("<details%s><summary><span class=\'car\'>&#9656;</span>"\n            "<span>%s</span><span>%s</span></summary>"\n            "<div class=\'det-body\'>%s</div></details>"\n            % (" open" if open_ else "", summary_html, right, body_html))\n\n\ndef foot(text: str) -> str:\n    return "<div class=\'foot\'>" + text + "</div>"\n\n\ndef close() -> str:\n    return "</div></body></html>"\n\n\ndef open_wrap() -> str:\n    return "<div class=\'wrap\'>"\n'
_FILES['ui.py'] = '"""\nShared presentation layer for every page the forecaster publishes.\n\nOne design system, one tab bar, one set of chart primitives, so the map,\nthe two public-safety reports and the ad ops sheet read as one site\ninstead of four separately-invented HTML documents.\n\nDesign direction — "highway instrumentation": the visual vocabulary is\nborrowed from the roads the data describes. Condensed signage type for\nheadings, a serif reading face for prose, tabular mono for numbers.\nThe signature element is the STRIPE BAR: every bar chart is drawn as\nlane striping where one dash = one recorded crash, so a reader can\nliterally count the evidence instead of trusting a bar\'s length.\n\nNothing here fetches or computes anything; callers pass finished numbers.\nNo external fonts, no CDN, no JS libraries — these pages are committed to\na repo and served as static files, so they must render offline and\nsurvive Pages caching forever.\n"""\nfrom __future__ import annotations\n\nimport html as _html\n\n# --- palette -------------------------------------------------------------\n# Accents are page identities, drawn from Indiana highway sign colours:\n# guide-sign green (public safety), interstate-shield blue (policy),\n# work-zone orange-brown (internal ops). Deliberately NOT interchangeable\n# — the accent is how a reader knows which page they\'re on before reading.\nACCENTS = {\n    "safety": "#14603C",   # INDOT guide-sign green\n    "brief": "#1B3A6B",    # interstate shield blue\n    "ops": "#8C3A12",      # work-zone orange, darkened for text contrast\n    "map": "#14603C",\n}\n\n\ndef esc(x) -> str:\n    return _html.escape(str(x))\n\n\ndef _tokens(accent: str) -> str:\n    return (\n        ":root{"\n        "--ink:#12171C;--ink2:#3D4750;--ink3:#6E7880;"\n        "--paper:#F5F7F4;--surface:#FFFFFF;--sunk:#EEF1EC;"\n        "--line:#D9DFD8;--line2:#EBEFE9;"\n        "--accent:%s;--accent-w:color-mix(in srgb,var(--accent) 12%%,white);"\n        "--accent-m:color-mix(in srgb,var(--accent) 45%%,white);"\n        "--amber:#B9861B;--amber-w:#FBF3DF;"\n        "--danger:#9E2B2B;--danger-w:#FBEDED;"\n        "--ok:#14603C;"\n        "--display:\'Oswald\',\'Archivo Narrow\',\'Roboto Condensed\',"\n        "\'Franklin Gothic Medium\',\'Arial Narrow\',system-ui,sans-serif;"\n        "--body:Charter,\'Bitstream Charter\',\'Iowan Old Style\',"\n        "\'Source Serif 4\',Georgia,\'Times New Roman\',serif;"\n        "--data:ui-monospace,\'SF Mono\',\'Cascadia Mono\',\'Segoe UI Mono\',"\n        "Consolas,monospace;"\n        "--r:3px}" % accent\n    )\n\n\n_STRUCTURE = """\n*{box-sizing:border-box}\nhtml{-webkit-text-size-adjust:100%}\nbody{margin:0;background:var(--paper);color:var(--ink);\nfont-family:var(--body);font-size:16.5px;line-height:1.6;\nfont-feature-settings:"kern" 1}\n.wrap{max-width:940px;margin:0 auto;padding:0 20px 72px}\na{color:var(--accent);text-underline-offset:2px}\na:hover{text-decoration-thickness:2px}\n:focus-visible{outline:3px solid var(--accent);outline-offset:2px}\n\n/* --- sign gantry: the tab bar ------------------------------------- */\n.gantry{position:sticky;top:0;z-index:900;background:var(--surface);\nborder-bottom:1px solid var(--line);\nbox-shadow:0 1px 0 rgba(18,23,28,.04),0 6px 18px -14px rgba(18,23,28,.5)}\n.gantry-in{max-width:940px;margin:0 auto;display:flex;align-items:stretch;\ngap:2px;padding:0 12px;overflow-x:auto;scrollbar-width:none}\n.gantry-in::-webkit-scrollbar{display:none}\n.tab{font-family:var(--display);font-size:13px;font-weight:600;\nletter-spacing:.09em;text-transform:uppercase;text-decoration:none;\ncolor:var(--ink3);padding:15px 14px 12px;border-bottom:3px solid transparent;\nwhite-space:nowrap;display:flex;align-items:center;gap:8px;\ntransition:color .12s,border-color .12s,background .12s}\n.tab:hover{color:var(--ink);background:var(--sunk)}\n.tab[aria-current="page"]{color:var(--accent);border-bottom-color:var(--accent)}\n.tab .dot{width:7px;height:7px;border-radius:50%;background:currentColor;\nopacity:.55;flex:0 0 auto}\n.tab[aria-current="page"] .dot{opacity:1}\n.gantry .draftflag{margin-left:auto;align-self:center;flex:0 0 auto;\nfont-family:var(--display);font-size:11px;letter-spacing:.12em;\ntext-transform:uppercase;color:var(--amber);border:1px solid var(--amber);\nborder-radius:2px;padding:3px 7px;background:var(--amber-w)}\n@media (max-width:700px){.tab{font-size:11.5px;padding:12px 10px 9px}\n.gantry .draftflag{display:none}}\n\n/* --- masthead ------------------------------------------------------ */\n.mast{padding:38px 0 20px;border-bottom:2px solid var(--ink)}\n.eyebrow{font-family:var(--display);font-size:12px;letter-spacing:.16em;\ntext-transform:uppercase;color:var(--accent);margin:0 0 10px}\nh1{font-family:var(--display);font-weight:600;font-size:clamp(30px,5vw,44px);\nline-height:1.06;letter-spacing:-.005em;margin:0 0 12px;max-width:22ch}\n.standfirst{font-size:18.5px;line-height:1.5;color:var(--ink2);margin:0;\nmax-width:60ch}\n.stamp{margin-top:16px;font-family:var(--data);font-size:12px;\ncolor:var(--ink3);letter-spacing:.02em}\n\n/* --- sections: milepost headings ----------------------------------- */\nh2{font-family:var(--display);font-weight:600;font-size:23px;\nletter-spacing:.005em;margin:52px 0 14px;padding-left:0;\ndisplay:flex;align-items:baseline;gap:12px}\nh2 .post{font-size:12px;letter-spacing:.12em;color:var(--accent);\nborder:1.5px solid var(--accent);border-radius:2px;padding:2px 6px;\nflex:0 0 auto;position:relative;top:-3px}\nh3{font-family:var(--display);font-weight:600;font-size:18px;margin:0 0 6px;\nletter-spacing:.01em}\np{margin:0 0 14px}\n.lede{font-size:17.5px;color:var(--ink2)}\n.small,small{font-size:13.5px;color:var(--ink3);line-height:1.5}\n.hint{font-size:13.5px;color:var(--ink3);line-height:1.55;margin-top:10px;\npadding-left:12px;border-left:2px solid var(--line)}\n\n/* --- cards --------------------------------------------------------- */\n.card{background:var(--surface);border:1px solid var(--line);\nborder-radius:var(--r);padding:20px 22px;margin:16px 0}\n.card.rank{border-left:4px solid var(--accent)}\n.card-h{display:flex;justify-content:space-between;align-items:flex-start;\ngap:16px;flex-wrap:wrap;margin-bottom:10px}\n.where{font-family:var(--display);font-size:20px;font-weight:600;\nline-height:1.2}\n.where .cty{display:block;font-size:12.5px;letter-spacing:.1em;\ntext-transform:uppercase;color:var(--ink3);font-weight:500;margin-top:3px}\n.kicker{font-family:var(--display);font-size:11.5px;letter-spacing:.11em;\ntext-transform:uppercase;color:var(--ink3)}\n\n/* --- chips --------------------------------------------------------- */\n.chip{display:inline-flex;align-items:center;gap:5px;font-family:var(--display);\nfont-size:11.5px;letter-spacing:.08em;text-transform:uppercase;\npadding:3px 8px;border-radius:2px;border:1px solid var(--line);\ncolor:var(--ink2);background:var(--sunk);white-space:nowrap}\n.chip.on{border-color:var(--accent);color:var(--accent);\nbackground:var(--accent-w)}\n.chip.good{border-color:var(--ok);color:var(--ok);\nbackground:color-mix(in srgb,var(--ok) 10%,white)}\n.chip.warn{border-color:var(--amber);color:var(--amber);\nbackground:var(--amber-w)}\n.chip.bad{border-color:var(--danger);color:var(--danger);\nbackground:var(--danger-w)}\n.chips{display:flex;flex-wrap:wrap;gap:6px;margin:10px 0}\n\n/* --- the signature: stripe bars ------------------------------------ */\n.stripe-row{display:grid;\ngrid-template-columns:minmax(80px,24%) minmax(0,1fr) auto;\nalign-items:center;gap:14px;padding:7px 0;border-bottom:1px solid var(--line2)}\n.stripe-row:last-child{border-bottom:0}\n.stripe-lab{font-size:14.5px;line-height:1.3;min-width:0}\n.stripe-lab b{font-family:var(--display);font-weight:600}\n.stripe-lab span{display:block;font-size:12px;color:var(--ink3);\nletter-spacing:.06em;text-transform:uppercase;font-family:var(--display)}\n.stripe-wrap{display:flex;align-items:center;min-width:0}\n.stripe{height:13px;border-radius:1px;flex:0 0 auto}\n.stripe-n{font-family:var(--data);font-size:13.5px;font-weight:600;\nmin-width:3ch;text-align:right;justify-self:end}\n\n/* --- tables -------------------------------------------------------- */\n.tbl-scroll{overflow-x:auto;margin:14px 0}\ntable{border-collapse:collapse;width:100%;font-size:14px;\nbackground:var(--surface)}\nth{font-family:var(--display);font-size:11.5px;letter-spacing:.09em;\ntext-transform:uppercase;text-align:left;color:var(--ink2);\nbackground:var(--sunk);border-bottom:2px solid var(--line);\npadding:9px 11px;white-space:nowrap;font-weight:600}\ntd{border-bottom:1px solid var(--line2);padding:9px 11px;vertical-align:top}\ntr:last-child td{border-bottom:0}\ntd.num,th.num{text-align:right;font-family:var(--data);\nfont-variant-numeric:tabular-nums}\ntbody tr:hover{background:var(--sunk)}\n\n/* --- disclosure ---------------------------------------------------- */\ndetails{background:var(--surface);border:1px solid var(--line);\nborder-radius:var(--r);margin:8px 0}\ndetails[open]{border-color:var(--accent-m)}\nsummary{cursor:pointer;padding:12px 16px;list-style:none;\ndisplay:grid;grid-template-columns:auto minmax(0,1fr) auto;\nalign-items:center;gap:12px}\nsummary::-webkit-details-marker{display:none}\nsummary:hover{background:var(--sunk)}\nsummary .car{font-family:var(--data);font-size:11px;color:var(--ink3);\ntransition:transform .15s}\ndetails[open] summary .car{transform:rotate(90deg)}\n@media (prefers-reduced-motion:reduce){summary .car{transition:none}}\n.det-body{padding:2px 16px 16px;border-top:1px solid var(--line2);\nmargin-top:2px}\n\n/* --- callouts ------------------------------------------------------ */\n.note{border:1px solid var(--line);border-left:4px solid var(--ink3);\nbackground:var(--surface);padding:14px 16px;margin:16px 0;font-size:14.5px;\nline-height:1.55;border-radius:var(--r)}\n.note.draft{border-left-color:var(--amber);background:var(--amber-w)}\n.note.hold{border-left-color:var(--danger);background:var(--danger-w)}\n.note.good{border-left-color:var(--ok)}\n.note b{font-family:var(--display);letter-spacing:.02em}\n\n/* --- key figures --------------------------------------------------- */\n.figs{display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));\ngap:1px;background:var(--line);border:1px solid var(--line);\nborder-radius:var(--r);overflow:hidden;margin:18px 0}\n.fig{background:var(--surface);padding:14px 16px}\n.fig .v{font-family:var(--display);font-size:30px;font-weight:600;\nline-height:1;color:var(--accent);font-variant-numeric:tabular-nums}\n.fig .k{font-family:var(--display);font-size:11px;letter-spacing:.1em;\ntext-transform:uppercase;color:var(--ink3);margin-top:6px}\n.fig .sub{font-size:12.5px;color:var(--ink3);margin-top:4px;line-height:1.4}\n\n/* --- charts -------------------------------------------------------- */\nfigure{margin:18px 0}\nfigcaption{font-size:13px;color:var(--ink3);line-height:1.5;margin-top:8px}\nsvg{display:block;max-width:100%;height:auto}\n.svg-lab{font-family:var(--display);font-size:10.5px;letter-spacing:.08em;\ntext-transform:uppercase;fill:var(--ink3)}\n.svg-val{font-family:var(--data);font-size:10.5px;fill:var(--ink2)}\n\n/* --- proportion bar ------------------------------------------------ */\n.prop{display:flex;height:26px;border-radius:2px;overflow:hidden;\nborder:1px solid var(--line);margin:10px 0}\n.prop div{display:flex;align-items:center;justify-content:center;\nfont-family:var(--display);font-size:11px;letter-spacing:.05em;color:#fff;\nmin-width:0;overflow:hidden}\n.prop-key{display:flex;flex-wrap:wrap;gap:12px;font-size:12.5px;\ncolor:var(--ink3);margin-top:2px}\n.prop-key i{width:10px;height:10px;border-radius:1px;display:inline-block;\nmargin-right:5px;vertical-align:-1px}\n\n/* --- published mode ------------------------------------------------\n   The publish step copies the draft file byte-for-byte to the public\n   URL, so the same document has to present correctly at both addresses.\n   A synchronous script in <head> sets data-published on <html> when the\n   filename lacks the _draft suffix; these rules then drop the review-only\n   furniture with no flash of draft content. */\nhtml[data-published] .note.draft,\nhtml[data-published] .draftflag{display:none}\n\n/* --- footer -------------------------------------------------------- */\n.foot{margin-top:56px;padding:20px 22px;background:var(--sunk);\nborder:1px solid var(--line);border-radius:var(--r);font-size:13.5px;\nline-height:1.6;color:var(--ink2)}\n.foot b{font-family:var(--display)}\n@media print{.gantry{position:static}.card,table{break-inside:avoid}}\n"""\n\n\n# Runs synchronously in <head> so the draft banner never flashes on the\n# published copy. The workflow publishes by copying safety_watch_draft.html\n# to safety_watch.html unchanged — deliberately, so the reviewer approves\n# exactly the bytes that go live — which means one file must render as a\n# draft at one URL and as the published report at the other.\n_PUBLISHED_JS = (\n    "<script>(function(){var p=!/_draft\\\\.html$/.test("\n    "location.pathname);if(!p)return;document.documentElement"\n    ".setAttribute(\'data-published\',\'1\');document.addEventListener("\n    "\'DOMContentLoaded\',function(){document.querySelectorAll("\n    "\'a[href$=\\"_draft.html\\"]\').forEach(function(a){a.setAttribute("\n    "\'href\',a.getAttribute(\'href\').replace(\'_draft.html\',\'.html\'));});"\n    "});})();</script>")\n\n\ndef head(title: str, accent_key: str = "safety") -> str:\n    """Opening tags + the full stylesheet for a page."""\n    return ("<!DOCTYPE html><html lang=\'en\'><head><meta charset=\'utf-8\'>"\n            "<meta name=\'viewport\' content=\'width=device-width,"\n            "initial-scale=1\'><title>" + esc(title) + "</title><style>"\n            + _tokens(ACCENTS.get(accent_key, ACCENTS["safety"]))\n            + _STRUCTURE + "</style>" + _PUBLISHED_JS + "</head><body>")\n\n\n# Page identities. Each entry: (slug, label, draft filename or None).\nPAGES = [\n    ("index.html", "Live Risk Map", None),\n    ("safety_watch.html", "Road Safety Watch", "safety_watch_draft.html"),\n    ("action_brief.html", "Hotspot Action Brief", "action_brief_draft.html"),\n    ("ad_ops.html", "Ad Ops Sheet", None),\n]\n\n\ndef tabs(current: str, draft: bool = False) -> str:\n    """Site tab bar.\n\n    `draft=True` renders the DRAFT variant: every link that HAS a draft\n    twin points at the twin, so a reviewer clicking through the review\n    copies stays inside the review copies. On published pages the links\n    point at published pages. Getting this wrong is how a reviewer ends\n    up reading a stale published page and approving it as if it were the\n    new draft.\n    """\n    out = ["<nav class=\'gantry\' aria-label=\'Report sections\'>"\n           "<div class=\'gantry-in\'>"]\n    for slug, label, draft_slug in PAGES:\n        href = draft_slug if (draft and draft_slug) else slug\n        cur = (current == slug)\n        out.append("<a class=\'tab\' href=\'%s\'%s><span class=\'dot\'></span>%s</a>"\n                   % (esc(href), " aria-current=\'page\'" if cur else "",\n                      esc(label)))\n    if draft:\n        out.append("<span class=\'draftflag\'>Draft</span>")\n    # On a narrow screen the bar scrolls horizontally, and the current\n    # page\'s tab can sit off-screen — so the reader gets no indication of\n    # where they are. Nudge it into view on load.\n    out.append("</div><script>(function(){var t=document."\n               "querySelector(\'.tab[aria-current]\');if(t&&t.scrollIntoView)"\n               "t.scrollIntoView({block:\'nearest\',inline:\'center\'});})();"\n               "</script></nav>")\n    return "".join(out)\n\n\ndef masthead(eyebrow: str, title: str, standfirst: str, stamp: str) -> str:\n    return ("<header class=\'mast\'><p class=\'eyebrow\'>" + esc(eyebrow)\n            + "</p><h1>" + esc(title) + "</h1><p class=\'standfirst\'>"\n            + esc(standfirst) + "</p><div class=\'stamp\'>" + esc(stamp)\n            + "</div></header>")\n\n\ndef h2(post: str, text: str) -> str:\n    """Section heading with a milepost tag (the tag carries the section\'s\n    short name, so it works as an in-page landmark, not decoration)."""\n    return ("<h2><span class=\'post\'>" + esc(post) + "</span>"\n            + esc(text) + "</h2>")\n\n\ndef figs(items: list[tuple]) -> str:\n    """Key-figure strip. items = [(value, label, subtext)]."""\n    cells = "".join(\n        "<div class=\'fig\'><div class=\'v\'>%s</div><div class=\'k\'>%s</div>"\n        "%s</div>"\n        % (esc(v), esc(k),\n           ("<div class=\'sub\'>%s</div>" % esc(s)) if s else "")\n        for v, k, s in items)\n    return "<div class=\'figs\'>" + cells + "</div>"\n\n\n# --- the signature chart -------------------------------------------------\n\ndef stripe(n: int, mx: int, maxw: int = 240, color: str = "var(--accent)"\n           ) -> str:\n    """Lane-striping bar: one dash = one recorded crash, so the reader can\n    count the evidence rather than estimate a bar length."""\n    mx = max(int(mx or 1), 1)\n    n = max(int(n or 0), 0)\n    per = max(2.6, min(9.0, maxw / mx))\n    dash = max(1.6, per * 0.6)\n    w = per * n\n    return ("<span class=\'stripe\' style=\'width:%.1fpx;background:"\n            "repeating-linear-gradient(90deg,%s 0 %.2fpx,transparent "\n            "%.2fpx %.2fpx)\' title=\'%d\'></span>"\n            % (w, color, dash, dash, per, n))\n\n\ndef stripe_rows(rows: list[tuple], maxw: int = 240,\n                color: str = "var(--accent)") -> str:\n    """rows = [(label, sublabel, n)] rendered as ranked stripe bars."""\n    if not rows:\n        return ""\n    mx = max(r[2] for r in rows) or 1\n    out = []\n    for lab, sub, n in rows:\n        out.append(\n            "<div class=\'stripe-row\'><div class=\'stripe-lab\'><b>%s</b>%s</div>"\n            "<div class=\'stripe-wrap\'>%s</div>"\n            "<span class=\'stripe-n\'>%d</span></div>"\n            % (esc(lab), ("<span>%s</span>" % esc(sub)) if sub else "",\n               stripe(n, mx, maxw, color), n))\n    return "".join(out)\n\n\ndef hour_chart(counts: dict, height: int = 108) -> str:\n    """24-hour crash profile with the commute windows shaded, so the\n    reader sees the peaks against the periods people actually plan\n    around rather than against an unlabelled axis."""\n    vals = [int(counts.get(h, 0) or 0) for h in range(24)]\n    mx = max(vals) or 1\n    w, pad, top = 720, 26, 12\n    bw = (w - pad * 2) / 24.0\n    body = []\n    for a, b in ((6, 10), (15, 19)):\n        body.append("<rect x=\'%.1f\' y=\'%d\' width=\'%.1f\' height=\'%d\' "\n                    "fill=\'var(--sunk)\'/>"\n                    % (pad + a * bw, top, (b - a) * bw, height))\n    for h, v in enumerate(vals):\n        bh = (v / mx) * height\n        body.append("<rect x=\'%.1f\' y=\'%.1f\' width=\'%.1f\' height=\'%.1f\' "\n                    "fill=\'var(--accent)\' opacity=\'%.2f\'><title>%02d:00 — "\n                    "%d crashes</title></rect>"\n                    % (pad + h * bw + 1.2, top + height - bh, bw - 2.4,\n                       max(bh, 0.8), 0.45 + 0.55 * (v / mx), h, v))\n    for h in (0, 6, 12, 18, 23):\n        body.append("<text class=\'svg-lab\' x=\'%.1f\' y=\'%d\' "\n                    "text-anchor=\'middle\'>%02d</text>"\n                    % (pad + h * bw + bw / 2, top + height + 15, h))\n    body.append("<text class=\'svg-lab\' x=\'%.1f\' y=\'%d\' text-anchor=\'middle\'>"\n                "AM peak</text>" % (pad + 8 * bw, top - 2))\n    body.append("<text class=\'svg-lab\' x=\'%.1f\' y=\'%d\' text-anchor=\'middle\'>"\n                "PM peak</text>" % (pad + 17 * bw, top - 2))\n    body.append("<text class=\'svg-lab\' x=\'%d\' y=\'%d\'>max %d</text>"\n                % (2, top + 9, mx))\n    return ("<svg viewBox=\'0 0 %d %d\' role=\'img\' aria-label=\'Crashes by "\n            "hour of day\'>%s</svg>" % (w, top + height + 22, "".join(body)))\n\n\ndef day_chart(counts: dict) -> str:\n    """Weekday profile as horizontal stripe bars."""\n    order = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday",\n             "Saturday", "Sunday"]\n    rows = [(d[:3], "", int(counts.get(d, 0) or 0)) for d in order]\n    return stripe_rows(rows, maxw=300)\n\n\ndef prop_bar(parts: list[tuple]) -> str:\n    """Stacked proportion bar. parts = [(label, value, colour)]."""\n    tot = sum(max(p[1], 0) for p in parts) or 1\n    segs, keys = [], []\n    for lab, v, col in parts:\n        if v <= 0:\n            continue\n        pct = 100.0 * v / tot\n        segs.append("<div style=\'width:%.2f%%;background:%s\' title=\'%s: %d "\n                    "(%.0f%%)\'>%s</div>"\n                    % (pct, col, esc(lab), v, pct,\n                       ("%.0f%%" % pct) if pct >= 11 else ""))\n        keys.append("<span><i style=\'background:%s\'></i>%s <b>%d</b></span>"\n                    % (col, esc(lab), v))\n    return ("<div class=\'prop\'>" + "".join(segs) + "</div>"\n            "<div class=\'prop-key\'>" + "".join(keys) + "</div>")\n\n\ndef month_chart(series: list[tuple], height: int = 92) -> str:\n    """series = [(month label, count)] as a column chart with the value\n    printed above each column — trend plus exact figures."""\n    if not series:\n        return ""\n    mx = max(v for _, v in series) or 1\n    w, pad, top = 720, 30, 18\n    n = len(series)\n    bw = (w - pad * 2) / max(n, 1)\n    body = []\n    for i, (lab, v) in enumerate(series):\n        bh = (v / mx) * height\n        x = pad + i * bw\n        body.append("<rect x=\'%.1f\' y=\'%.1f\' width=\'%.1f\' height=\'%.1f\' "\n                    "fill=\'var(--accent)\' opacity=\'.82\' rx=\'1\'/>"\n                    % (x + bw * .18, top + height - bh, bw * .64,\n                       max(bh, 1.0)))\n        body.append("<text class=\'svg-val\' x=\'%.1f\' y=\'%.1f\' "\n                    "text-anchor=\'middle\'>%d</text>"\n                    % (x + bw / 2, top + height - bh - 5, v))\n        body.append("<text class=\'svg-lab\' x=\'%.1f\' y=\'%.1f\' "\n                    "text-anchor=\'middle\'>%s</text>"\n                    % (x + bw / 2, top + height + 15, esc(lab)))\n    return ("<svg viewBox=\'0 0 %d %d\' role=\'img\' aria-label=\'Crashes "\n            "recorded per month\'>%s</svg>"\n            % (w, top + height + 22, "".join(body)))\n\n\ndef funnel(stages: list[tuple]) -> str:\n    """Gate funnel. stages = [(label, count, note)]. Shows how many\n    locations survive each publication gate — the honest answer to\n    \'why isn\'t my location in the report?\'."""\n    if not stages:\n        return ""\n    mx = max(c for _, c, _ in stages) or 1\n    w, rowh, pad = 720, 34, 4\n    body = []\n    for i, (lab, c, note) in enumerate(stages):\n        y = pad + i * rowh\n        bw = max(2.0, (c / mx) * 330)\n        body.append("<rect x=\'150\' y=\'%d\' width=\'%.1f\' height=\'18\' rx=\'1\' "\n                    "fill=\'var(--accent)\' opacity=\'%.2f\'/>"\n                    % (y, bw, 0.92 - i * 0.13))\n        body.append("<text class=\'svg-lab\' x=\'142\' y=\'%d\' text-anchor=\'end\'>"\n                    "%s</text>" % (y + 13, esc(lab)))\n        body.append("<text class=\'svg-val\' x=\'%.1f\' y=\'%d\'>%d</text>"\n                    % (150 + bw + 7, y + 13, c))\n        if note:\n            body.append("<text class=\'svg-lab\' x=\'%.1f\' y=\'%d\' "\n                        "opacity=\'.85\'>%s</text>"\n                        % (150 + bw + 7 + 12 + len(str(c)) * 7, y + 13,\n                           esc(note)))\n    return ("<svg viewBox=\'0 0 %d %d\' role=\'img\' aria-label=\'Publication "\n            "gate funnel\'>%s</svg>"\n            % (w, pad * 2 + len(stages) * rowh, "".join(body)))\n\n\ndef sparkpath(path: list, w: int = 300, h: int = 74) -> str:\n    """Plot a corridor\'s crash coordinates as a mini route sketch — an\n    at-a-glance sense of whether crashes string along the road evenly or\n    bunch at one end. Not a map: no basemap, no scale claim."""\n    pts = [(float(p[0]), float(p[1])) for p in (path or [])\n           if p and len(p) >= 2]\n    if len(pts) < 2:\n        return ""\n    lats = [p[0] for p in pts]\n    lons = [p[1] for p in pts]\n    la0, la1 = min(lats), max(lats)\n    lo0, lo1 = min(lons), max(lons)\n    dla, dlo = max(la1 - la0, 1e-6), max(lo1 - lo0, 1e-6)\n    m = 10\n\n    def xy(p):\n        x = m + (p[1] - lo0) / dlo * (w - 2 * m)\n        y = h - m - (p[0] - la0) / dla * (h - 2 * m)\n        return x, y\n\n    segs = []\n    for i, p in enumerate(pts):\n        x, y = xy(p)\n        segs.append("%s%.1f %.1f" % ("M" if i == 0 else "L", x, y))\n    d = " ".join(segs)\n    dots = "".join("<circle cx=\'%.1f\' cy=\'%.1f\' r=\'2.6\' fill=\'var(--accent)\' "\n                   "opacity=\'.75\'/>" % xy(p) for p in pts)\n    return ("<svg viewBox=\'0 0 %d %d\' role=\'img\' aria-label=\'Crash "\n            "positions along the corridor\'><path d=\'%s\' fill=\'none\' "\n            "stroke=\'var(--accent)\' stroke-width=\'1.6\' opacity=\'.35\' "\n            "stroke-dasharray=\'5 4\'/>%s</svg>" % (w, h, d, dots))\n\n\ndef detail(summary_html: str, body_html: str, right: str = "",\n           open_: bool = False) -> str:\n    return ("<details%s><summary><span class=\'car\'>&#9656;</span>"\n            "<span>%s</span><span>%s</span></summary>"\n            "<div class=\'det-body\'>%s</div></details>"\n            % (" open" if open_ else "", summary_html, right, body_html))\n\n\ndef foot(text: str) -> str:\n    return "<div class=\'foot\'>" + text + "</div>"\n\n\ndef close() -> str:\n    return "</div></body></html>"\n\n\ndef open_wrap() -> str:\n    return "<div class=\'wrap\'>"\n'
_FILES['ui.py'] = '"""\nShared presentation layer for every page the forecaster publishes.\n\nOne design system, one tab bar, one set of chart primitives, so the map,\nthe two public-safety reports and the ad ops sheet read as one site\ninstead of four separately-invented HTML documents.\n\nDesign direction — "highway instrumentation": the visual vocabulary is\nborrowed from the roads the data describes. Condensed signage type for\nheadings, a serif reading face for prose, tabular mono for numbers.\nThe signature element is the STRIPE BAR: every bar chart is drawn as\nlane striping where one dash = one recorded crash, so a reader can\nliterally count the evidence instead of trusting a bar\'s length.\n\nNothing here fetches or computes anything; callers pass finished numbers.\nNo external fonts, no CDN, no JS libraries — these pages are committed to\na repo and served as static files, so they must render offline and\nsurvive Pages caching forever.\n"""\nfrom __future__ import annotations\n\nimport html as _html\n\n# --- palette -------------------------------------------------------------\n# Accents are page identities, drawn from Indiana highway sign colours:\n# guide-sign green (public safety), interstate-shield blue (policy),\n# work-zone orange-brown (internal ops). Deliberately NOT interchangeable\n# — the accent is how a reader knows which page they\'re on before reading.\nACCENTS = {\n    "safety": "#14603C",   # INDOT guide-sign green\n    "brief": "#1B3A6B",    # interstate shield blue\n    "ops": "#8C3A12",      # work-zone orange, darkened for text contrast\n    "map": "#14603C",\n}\n\n\ndef esc(x) -> str:\n    return _html.escape(str(x))\n\n\ndef _tokens(accent: str) -> str:\n    return (\n        ":root{"\n        "--ink:#12171C;--ink2:#3D4750;--ink3:#6E7880;"\n        "--paper:#F5F7F4;--surface:#FFFFFF;--sunk:#EEF1EC;"\n        "--line:#D9DFD8;--line2:#EBEFE9;"\n        "--accent:%s;--accent-w:color-mix(in srgb,var(--accent) 12%%,white);"\n        "--accent-m:color-mix(in srgb,var(--accent) 45%%,white);"\n        "--amber:#B9861B;--amber-w:#FBF3DF;"\n        "--danger:#9E2B2B;--danger-w:#FBEDED;"\n        "--ok:#14603C;"\n        "--display:\'Oswald\',\'Archivo Narrow\',\'Roboto Condensed\',"\n        "\'Franklin Gothic Medium\',\'Arial Narrow\',system-ui,sans-serif;"\n        "--body:Charter,\'Bitstream Charter\',\'Iowan Old Style\',"\n        "\'Source Serif 4\',Georgia,\'Times New Roman\',serif;"\n        "--data:ui-monospace,\'SF Mono\',\'Cascadia Mono\',\'Segoe UI Mono\',"\n        "Consolas,monospace;"\n        "--r:3px}" % accent\n    )\n\n\n_STRUCTURE = """\n*{box-sizing:border-box}\nhtml{-webkit-text-size-adjust:100%}\nbody{margin:0;background:var(--paper);color:var(--ink);\nfont-family:var(--body);font-size:16.5px;line-height:1.6;\nfont-feature-settings:"kern" 1}\n.wrap{max-width:940px;margin:0 auto;padding:0 20px 72px}\na{color:var(--accent);text-underline-offset:2px}\na:hover{text-decoration-thickness:2px}\n:focus-visible{outline:3px solid var(--accent);outline-offset:2px}\n\n/* --- sign gantry: the tab bar ------------------------------------- */\n.gantry{position:sticky;top:0;z-index:900;background:var(--surface);\nborder-bottom:1px solid var(--line);\nbox-shadow:0 1px 0 rgba(18,23,28,.04),0 6px 18px -14px rgba(18,23,28,.5)}\n.gantry-in{max-width:940px;margin:0 auto;display:flex;align-items:stretch;\ngap:2px;padding:0 12px;overflow-x:auto;scrollbar-width:none}\n.gantry-in::-webkit-scrollbar{display:none}\n.tab{font-family:var(--display);font-size:13px;font-weight:600;\nletter-spacing:.09em;text-transform:uppercase;text-decoration:none;\ncolor:var(--ink3);padding:15px 14px 12px;border-bottom:3px solid transparent;\nwhite-space:nowrap;display:flex;align-items:center;gap:8px;\ntransition:color .12s,border-color .12s,background .12s}\n.tab:hover{color:var(--ink);background:var(--sunk)}\n.tab[aria-current="page"]{color:var(--accent);border-bottom-color:var(--accent)}\n.tab .dot{width:7px;height:7px;border-radius:50%;background:currentColor;\nopacity:.55;flex:0 0 auto}\n.tab[aria-current="page"] .dot{opacity:1}\n.gantry .draftflag{margin-left:auto;align-self:center;flex:0 0 auto;\nfont-family:var(--display);font-size:11px;letter-spacing:.12em;\ntext-transform:uppercase;color:var(--amber);border:1px solid var(--amber);\nborder-radius:2px;padding:3px 7px;background:var(--amber-w)}\n@media (max-width:700px){.tab{font-size:11.5px;padding:12px 10px 9px}\n.gantry .draftflag{display:none}}\n\n/* --- masthead ------------------------------------------------------ */\n.mast{padding:38px 0 20px;border-bottom:2px solid var(--ink)}\n.eyebrow{font-family:var(--display);font-size:12px;letter-spacing:.16em;\ntext-transform:uppercase;color:var(--accent);margin:0 0 10px}\nh1{font-family:var(--display);font-weight:600;font-size:clamp(30px,5vw,44px);\nline-height:1.06;letter-spacing:-.005em;margin:0 0 12px;max-width:22ch}\n.standfirst{font-size:18.5px;line-height:1.5;color:var(--ink2);margin:0;\nmax-width:60ch}\n.stamp{margin-top:16px;font-family:var(--data);font-size:12px;\ncolor:var(--ink3);letter-spacing:.02em}\n\n/* --- sections: milepost headings ----------------------------------- */\nh2{font-family:var(--display);font-weight:600;font-size:23px;\nletter-spacing:.005em;margin:52px 0 14px;padding-left:0;\ndisplay:flex;align-items:baseline;gap:12px}\nh2 .post{font-size:12px;letter-spacing:.12em;color:var(--accent);\nborder:1.5px solid var(--accent);border-radius:2px;padding:2px 6px;\nflex:0 0 auto;position:relative;top:-3px}\nh3{font-family:var(--display);font-weight:600;font-size:18px;margin:0 0 6px;\nletter-spacing:.01em}\np{margin:0 0 14px}\n.lede{font-size:17.5px;color:var(--ink2)}\n.small,small{font-size:13.5px;color:var(--ink3);line-height:1.5}\n.hint{font-size:13.5px;color:var(--ink3);line-height:1.55;margin-top:10px;\npadding-left:12px;border-left:2px solid var(--line)}\n\n/* --- cards --------------------------------------------------------- */\n.card{background:var(--surface);border:1px solid var(--line);\nborder-radius:var(--r);padding:20px 22px;margin:16px 0}\n.card.rank{border-left:4px solid var(--accent)}\n.card-h{display:flex;justify-content:space-between;align-items:flex-start;\ngap:16px;flex-wrap:wrap;margin-bottom:10px}\n.where{font-family:var(--display);font-size:20px;font-weight:600;\nline-height:1.2}\n.where .cty{display:block;font-size:12.5px;letter-spacing:.1em;\ntext-transform:uppercase;color:var(--ink3);font-weight:500;margin-top:3px}\n.kicker{font-family:var(--display);font-size:11.5px;letter-spacing:.11em;\ntext-transform:uppercase;color:var(--ink3)}\n\n/* --- chips --------------------------------------------------------- */\n.chip{display:inline-flex;align-items:center;gap:5px;font-family:var(--display);\nfont-size:11.5px;letter-spacing:.08em;text-transform:uppercase;\npadding:3px 8px;border-radius:2px;border:1px solid var(--line);\ncolor:var(--ink2);background:var(--sunk);white-space:nowrap}\n.chip.on{border-color:var(--accent);color:var(--accent);\nbackground:var(--accent-w)}\n.chip.good{border-color:var(--ok);color:var(--ok);\nbackground:color-mix(in srgb,var(--ok) 10%,white)}\n.chip.warn{border-color:var(--amber);color:var(--amber);\nbackground:var(--amber-w)}\n.chip.bad{border-color:var(--danger);color:var(--danger);\nbackground:var(--danger-w)}\n.chips{display:flex;flex-wrap:wrap;gap:6px;margin:10px 0}\n\n/* --- the signature: stripe bars ------------------------------------ */\n.stripe-row{display:grid;\ngrid-template-columns:minmax(80px,24%) minmax(0,1fr) auto;\nalign-items:center;gap:14px;padding:7px 0;border-bottom:1px solid var(--line2)}\n.stripe-row:last-child{border-bottom:0}\n.stripe-lab{font-size:14.5px;line-height:1.3;min-width:0}\n.stripe-lab b{font-family:var(--display);font-weight:600}\n.stripe-lab span{display:block;font-size:12px;color:var(--ink3);\nletter-spacing:.06em;text-transform:uppercase;font-family:var(--display)}\n.stripe-wrap{display:flex;align-items:center;min-width:0}\n.stripe{height:13px;border-radius:1px;flex:0 0 auto}\n.stripe-n{font-family:var(--data);font-size:13.5px;font-weight:600;\nmin-width:3ch;text-align:right;justify-self:end}\n\n/* --- tables -------------------------------------------------------- */\n.tbl-scroll{overflow-x:auto;margin:14px 0}\ntable{border-collapse:collapse;width:100%;font-size:14px;\nbackground:var(--surface)}\nth{font-family:var(--display);font-size:11.5px;letter-spacing:.09em;\ntext-transform:uppercase;text-align:left;color:var(--ink2);\nbackground:var(--sunk);border-bottom:2px solid var(--line);\npadding:9px 11px;white-space:nowrap;font-weight:600}\ntd{border-bottom:1px solid var(--line2);padding:9px 11px;vertical-align:top}\ntr:last-child td{border-bottom:0}\ntd.num,th.num{text-align:right;font-family:var(--data);\nfont-variant-numeric:tabular-nums}\ntbody tr:hover{background:var(--sunk)}\n\n/* --- disclosure ---------------------------------------------------- */\ndetails{background:var(--surface);border:1px solid var(--line);\nborder-radius:var(--r);margin:8px 0}\ndetails[open]{border-color:var(--accent-m)}\nsummary{cursor:pointer;padding:12px 16px;list-style:none;\ndisplay:grid;grid-template-columns:auto minmax(0,1fr) auto;\nalign-items:center;gap:12px}\nsummary::-webkit-details-marker{display:none}\nsummary:hover{background:var(--sunk)}\nsummary .car{font-family:var(--data);font-size:11px;color:var(--ink3);\ntransition:transform .15s}\ndetails[open] summary .car{transform:rotate(90deg)}\n@media (prefers-reduced-motion:reduce){summary .car{transition:none}}\n.det-body{padding:2px 16px 16px;border-top:1px solid var(--line2);\nmargin-top:2px}\n\n/* --- callouts ------------------------------------------------------ */\n.note{border:1px solid var(--line);border-left:4px solid var(--ink3);\nbackground:var(--surface);padding:14px 16px;margin:16px 0;font-size:14.5px;\nline-height:1.55;border-radius:var(--r)}\n.note.draft{border-left-color:var(--amber);background:var(--amber-w)}\n.note.hold{border-left-color:var(--danger);background:var(--danger-w)}\n.note.good{border-left-color:var(--ok)}\n.note b{font-family:var(--display);letter-spacing:.02em}\n\n/* --- key figures --------------------------------------------------- */\n.figs{display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));\ngap:1px;background:var(--line);border:1px solid var(--line);\nborder-radius:var(--r);overflow:hidden;margin:18px 0}\n.fig{background:var(--surface);padding:14px 16px}\n.fig .v{font-family:var(--display);font-size:30px;font-weight:600;\nline-height:1;color:var(--accent);font-variant-numeric:tabular-nums}\n.fig .k{font-family:var(--display);font-size:11px;letter-spacing:.1em;\ntext-transform:uppercase;color:var(--ink3);margin-top:6px}\n.fig .sub{font-size:12.5px;color:var(--ink3);margin-top:4px;line-height:1.4}\n\n/* --- charts -------------------------------------------------------- */\nfigure{margin:18px 0}\nfigcaption{font-size:13px;color:var(--ink3);line-height:1.5;margin-top:8px}\nsvg{display:block;max-width:100%;height:auto}\n.svg-lab{font-family:var(--display);font-size:10.5px;letter-spacing:.08em;\ntext-transform:uppercase;fill:var(--ink3)}\n.svg-val{font-family:var(--data);font-size:10.5px;fill:var(--ink2)}\n\n/* --- proportion bar ------------------------------------------------ */\n.prop{display:flex;height:26px;border-radius:2px;overflow:hidden;\nborder:1px solid var(--line);margin:10px 0}\n.prop div{display:flex;align-items:center;justify-content:center;\nfont-family:var(--display);font-size:11px;letter-spacing:.05em;color:#fff;\nmin-width:0;overflow:hidden}\n.prop-key{display:flex;flex-wrap:wrap;gap:12px;font-size:12.5px;\ncolor:var(--ink3);margin-top:2px}\n.prop-key i{width:10px;height:10px;border-radius:1px;display:inline-block;\nmargin-right:5px;vertical-align:-1px}\n\n/* --- published mode ------------------------------------------------\n   The publish step copies the draft file byte-for-byte to the public\n   URL, so the same document has to present correctly at both addresses.\n   A synchronous script in <head> sets data-published on <html> when the\n   filename lacks the _draft suffix; these rules then drop the review-only\n   furniture with no flash of draft content. */\nhtml[data-published] .note.draft,\nhtml[data-published] .draftflag{display:none}\n\n/* --- footer -------------------------------------------------------- */\n.foot{margin-top:56px;padding:20px 22px;background:var(--sunk);\nborder:1px solid var(--line);border-radius:var(--r);font-size:13.5px;\nline-height:1.6;color:var(--ink2)}\n.foot b{font-family:var(--display)}\n@media print{.gantry{position:static}.card,table{break-inside:avoid}}\n"""\n\n\n# Runs synchronously in <head> so the draft banner never flashes on the\n# published copy. The workflow publishes by copying safety_watch_draft.html\n# to safety_watch.html unchanged — deliberately, so the reviewer approves\n# exactly the bytes that go live — which means one file must render as a\n# draft at one URL and as the published report at the other.\n_PUBLISHED_JS = (\n    "<script>(function(){var p=!/_draft\\\\.html$/.test("\n    "location.pathname);if(!p)return;document.documentElement"\n    ".setAttribute(\'data-published\',\'1\');document.addEventListener("\n    "\'DOMContentLoaded\',function(){document.querySelectorAll("\n    "\'a[href$=\\"_draft.html\\"]\').forEach(function(a){a.setAttribute("\n    "\'href\',a.getAttribute(\'href\').replace(\'_draft.html\',\'.html\'));});"\n    "});})();</script>")\n\n\ndef head(title: str, accent_key: str = "safety") -> str:\n    """Opening tags + the full stylesheet for a page."""\n    return ("<!DOCTYPE html><html lang=\'en\'><head><meta charset=\'utf-8\'>"\n            "<meta name=\'viewport\' content=\'width=device-width,"\n            "initial-scale=1\'><title>" + esc(title) + "</title><style>"\n            + _tokens(ACCENTS.get(accent_key, ACCENTS["safety"]))\n            + _STRUCTURE + "</style>" + _PUBLISHED_JS + "</head><body>")\n\n\n# Page identities. Each entry: (slug, label, draft filename or None).\nPAGES = [\n    ("index.html", "Live Risk Map", None),\n    ("safety_watch.html", "Road Safety Watch", "safety_watch_draft.html"),\n    ("action_brief.html", "Hotspot Action Brief", "action_brief_draft.html"),\n    ("ad_ops.html", "Ad Ops Sheet", None),\n]\n\n\ndef tabs(current: str, draft: bool = False) -> str:\n    """Site tab bar.\n\n    `draft=True` renders the DRAFT variant: every link that HAS a draft\n    twin points at the twin, so a reviewer clicking through the review\n    copies stays inside the review copies. On published pages the links\n    point at published pages. Getting this wrong is how a reviewer ends\n    up reading a stale published page and approving it as if it were the\n    new draft.\n    """\n    out = ["<nav class=\'gantry\' aria-label=\'Report sections\'>"\n           "<div class=\'gantry-in\'>"]\n    for slug, label, draft_slug in PAGES:\n        href = draft_slug if (draft and draft_slug) else slug\n        cur = (current == slug)\n        out.append("<a class=\'tab\' href=\'%s\'%s><span class=\'dot\'></span>%s</a>"\n                   % (esc(href), " aria-current=\'page\'" if cur else "",\n                      esc(label)))\n    if draft:\n        out.append("<span class=\'draftflag\'>Draft</span>")\n    # On a narrow screen the bar scrolls horizontally, and the current\n    # page\'s tab can sit off-screen — so the reader gets no indication of\n    # where they are. Nudge it into view on load.\n    out.append("</div><script>(function(){var t=document."\n               "querySelector(\'.tab[aria-current]\');if(t&&t.scrollIntoView)"\n               "t.scrollIntoView({block:\'nearest\',inline:\'center\'});})();"\n               "</script></nav>")\n    return "".join(out)\n\n\ndef masthead(eyebrow: str, title: str, standfirst: str, stamp: str) -> str:\n    return ("<header class=\'mast\'><p class=\'eyebrow\'>" + esc(eyebrow)\n            + "</p><h1>" + esc(title) + "</h1><p class=\'standfirst\'>"\n            + esc(standfirst) + "</p><div class=\'stamp\'>" + esc(stamp)\n            + "</div></header>")\n\n\ndef h2(post: str, text: str) -> str:\n    """Section heading with a milepost tag (the tag carries the section\'s\n    short name, so it works as an in-page landmark, not decoration)."""\n    return ("<h2><span class=\'post\'>" + esc(post) + "</span>"\n            + esc(text) + "</h2>")\n\n\ndef figs(items: list[tuple]) -> str:\n    """Key-figure strip. items = [(value, label, subtext)]."""\n    cells = "".join(\n        "<div class=\'fig\'><div class=\'v\'>%s</div><div class=\'k\'>%s</div>"\n        "%s</div>"\n        % (esc(v), esc(k),\n           ("<div class=\'sub\'>%s</div>" % esc(s)) if s else "")\n        for v, k, s in items)\n    return "<div class=\'figs\'>" + cells + "</div>"\n\n\n# --- the signature chart -------------------------------------------------\n\ndef stripe(n: int, mx: int, maxw: int = 240, color: str = "var(--accent)"\n           ) -> str:\n    """Lane-striping bar: one dash = one recorded crash, so the reader can\n    count the evidence rather than estimate a bar length."""\n    mx = max(int(mx or 1), 1)\n    n = max(int(n or 0), 0)\n    per = max(2.6, min(9.0, maxw / mx))\n    dash = max(1.6, per * 0.6)\n    w = per * n\n    return ("<span class=\'stripe\' style=\'width:%.1fpx;background:"\n            "repeating-linear-gradient(90deg,%s 0 %.2fpx,transparent "\n            "%.2fpx %.2fpx)\' title=\'%d\'></span>"\n            % (w, color, dash, dash, per, n))\n\n\ndef stripe_rows(rows: list[tuple], maxw: int = 240,\n                color: str = "var(--accent)") -> str:\n    """rows = [(label, sublabel, n)] rendered as ranked stripe bars."""\n    if not rows:\n        return ""\n    mx = max(r[2] for r in rows) or 1\n    out = []\n    for lab, sub, n in rows:\n        out.append(\n            "<div class=\'stripe-row\'><div class=\'stripe-lab\'><b>%s</b>%s</div>"\n            "<div class=\'stripe-wrap\'>%s</div>"\n            "<span class=\'stripe-n\'>%d</span></div>"\n            % (esc(lab), ("<span>%s</span>" % esc(sub)) if sub else "",\n               stripe(n, mx, maxw, color), n))\n    return "".join(out)\n\n\ndef hour_chart(counts: dict, height: int = 108) -> str:\n    """24-hour crash profile with the commute windows shaded, so the\n    reader sees the peaks against the periods people actually plan\n    around rather than against an unlabelled axis."""\n    vals = [int(counts.get(h, 0) or 0) for h in range(24)]\n    mx = max(vals) or 1\n    w, pad, top = 720, 26, 12\n    bw = (w - pad * 2) / 24.0\n    body = []\n    for a, b in ((6, 10), (15, 19)):\n        body.append("<rect x=\'%.1f\' y=\'%d\' width=\'%.1f\' height=\'%d\' "\n                    "fill=\'var(--sunk)\'/>"\n                    % (pad + a * bw, top, (b - a) * bw, height))\n    for h, v in enumerate(vals):\n        bh = (v / mx) * height\n        body.append("<rect x=\'%.1f\' y=\'%.1f\' width=\'%.1f\' height=\'%.1f\' "\n                    "fill=\'var(--accent)\' opacity=\'%.2f\'><title>%02d:00 — "\n                    "%d crashes</title></rect>"\n                    % (pad + h * bw + 1.2, top + height - bh, bw - 2.4,\n                       max(bh, 0.8), 0.45 + 0.55 * (v / mx), h, v))\n    for h in (0, 6, 12, 18, 23):\n        body.append("<text class=\'svg-lab\' x=\'%.1f\' y=\'%d\' "\n                    "text-anchor=\'middle\'>%02d</text>"\n                    % (pad + h * bw + bw / 2, top + height + 15, h))\n    body.append("<text class=\'svg-lab\' x=\'%.1f\' y=\'%d\' text-anchor=\'middle\'>"\n                "AM peak</text>" % (pad + 8 * bw, top - 2))\n    body.append("<text class=\'svg-lab\' x=\'%.1f\' y=\'%d\' text-anchor=\'middle\'>"\n                "PM peak</text>" % (pad + 17 * bw, top - 2))\n    body.append("<text class=\'svg-lab\' x=\'%d\' y=\'%d\'>max %d</text>"\n                % (2, top + 9, mx))\n    return ("<svg viewBox=\'0 0 %d %d\' role=\'img\' aria-label=\'Crashes by "\n            "hour of day\'>%s</svg>" % (w, top + height + 22, "".join(body)))\n\n\ndef day_chart(counts: dict) -> str:\n    """Weekday profile as horizontal stripe bars."""\n    order = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday",\n             "Saturday", "Sunday"]\n    rows = [(d[:3], "", int(counts.get(d, 0) or 0)) for d in order]\n    return stripe_rows(rows, maxw=300)\n\n\ndef prop_bar(parts: list[tuple]) -> str:\n    """Stacked proportion bar. parts = [(label, value, colour)]."""\n    tot = sum(max(p[1], 0) for p in parts) or 1\n    segs, keys = [], []\n    for lab, v, col in parts:\n        if v <= 0:\n            continue\n        pct = 100.0 * v / tot\n        segs.append("<div style=\'width:%.2f%%;background:%s\' title=\'%s: %d "\n                    "(%.0f%%)\'>%s</div>"\n                    % (pct, col, esc(lab), v, pct,\n                       ("%.0f%%" % pct) if pct >= 11 else ""))\n        keys.append("<span><i style=\'background:%s\'></i>%s <b>%d</b></span>"\n                    % (col, esc(lab), v))\n    return ("<div class=\'prop\'>" + "".join(segs) + "</div>"\n            "<div class=\'prop-key\'>" + "".join(keys) + "</div>")\n\n\ndef month_chart(series: list[tuple], height: int = 92) -> str:\n    """series = [(month label, count)] as a column chart with the value\n    printed above each column — trend plus exact figures."""\n    if not series:\n        return ""\n    mx = max(v for _, v in series) or 1\n    w, pad, top = 720, 30, 18\n    n = len(series)\n    bw = (w - pad * 2) / max(n, 1)\n    body = []\n    for i, (lab, v) in enumerate(series):\n        bh = (v / mx) * height\n        x = pad + i * bw\n        body.append("<rect x=\'%.1f\' y=\'%.1f\' width=\'%.1f\' height=\'%.1f\' "\n                    "fill=\'var(--accent)\' opacity=\'.82\' rx=\'1\'/>"\n                    % (x + bw * .18, top + height - bh, bw * .64,\n                       max(bh, 1.0)))\n        body.append("<text class=\'svg-val\' x=\'%.1f\' y=\'%.1f\' "\n                    "text-anchor=\'middle\'>%d</text>"\n                    % (x + bw / 2, top + height - bh - 5, v))\n        body.append("<text class=\'svg-lab\' x=\'%.1f\' y=\'%.1f\' "\n                    "text-anchor=\'middle\'>%s</text>"\n                    % (x + bw / 2, top + height + 15, esc(lab)))\n    return ("<svg viewBox=\'0 0 %d %d\' role=\'img\' aria-label=\'Crashes "\n            "recorded per month\'>%s</svg>"\n            % (w, top + height + 22, "".join(body)))\n\n\ndef funnel(stages: list[tuple]) -> str:\n    """Gate funnel. stages = [(label, count, note)]. Shows how many\n    locations survive each publication gate — the honest answer to\n    \'why isn\'t my location in the report?\'."""\n    if not stages:\n        return ""\n    mx = max(c for _, c, _ in stages) or 1\n    w, rowh, pad = 720, 34, 4\n    body = []\n    for i, (lab, c, note) in enumerate(stages):\n        y = pad + i * rowh\n        bw = max(2.0, (c / mx) * 330)\n        body.append("<rect x=\'150\' y=\'%d\' width=\'%.1f\' height=\'18\' rx=\'1\' "\n                    "fill=\'var(--accent)\' opacity=\'%.2f\'/>"\n                    % (y, bw, 0.92 - i * 0.13))\n        body.append("<text class=\'svg-lab\' x=\'142\' y=\'%d\' text-anchor=\'end\'>"\n                    "%s</text>" % (y + 13, esc(lab)))\n        body.append("<text class=\'svg-val\' x=\'%.1f\' y=\'%d\'>%d</text>"\n                    % (150 + bw + 7, y + 13, c))\n        if note:\n            body.append("<text class=\'svg-lab\' x=\'%.1f\' y=\'%d\' "\n                        "opacity=\'.85\'>%s</text>"\n                        % (150 + bw + 7 + 12 + len(str(c)) * 7, y + 13,\n                           esc(note)))\n    return ("<svg viewBox=\'0 0 %d %d\' role=\'img\' aria-label=\'Publication "\n            "gate funnel\'>%s</svg>"\n            % (w, pad * 2 + len(stages) * rowh, "".join(body)))\n\n\ndef sparkpath(path: list, w: int = 300, h: int = 74) -> str:\n    """Plot a corridor\'s crash coordinates as a mini route sketch — an\n    at-a-glance sense of whether crashes string along the road evenly or\n    bunch at one end. Not a map: no basemap, no scale claim."""\n    pts = [(float(p[0]), float(p[1])) for p in (path or [])\n           if p and len(p) >= 2]\n    if len(pts) < 2:\n        return ""\n    lats = [p[0] for p in pts]\n    lons = [p[1] for p in pts]\n    la0, la1 = min(lats), max(lats)\n    lo0, lo1 = min(lons), max(lons)\n    dla, dlo = max(la1 - la0, 1e-6), max(lo1 - lo0, 1e-6)\n    m = 10\n\n    def xy(p):\n        x = m + (p[1] - lo0) / dlo * (w - 2 * m)\n        y = h - m - (p[0] - la0) / dla * (h - 2 * m)\n        return x, y\n\n    segs = []\n    for i, p in enumerate(pts):\n        x, y = xy(p)\n        segs.append("%s%.1f %.1f" % ("M" if i == 0 else "L", x, y))\n    d = " ".join(segs)\n    dots = "".join("<circle cx=\'%.1f\' cy=\'%.1f\' r=\'2.6\' fill=\'var(--accent)\' "\n                   "opacity=\'.75\'/>" % xy(p) for p in pts)\n    return ("<svg viewBox=\'0 0 %d %d\' role=\'img\' aria-label=\'Crash "\n            "positions along the corridor\'><path d=\'%s\' fill=\'none\' "\n            "stroke=\'var(--accent)\' stroke-width=\'1.6\' opacity=\'.35\' "\n            "stroke-dasharray=\'5 4\'/>%s</svg>" % (w, h, d, dots))\n\n\ndef detail(summary_html: str, body_html: str, right: str = "",\n           open_: bool = False) -> str:\n    return ("<details%s><summary><span class=\'car\'>&#9656;</span>"\n            "<span>%s</span><span>%s</span></summary>"\n            "<div class=\'det-body\'>%s</div></details>"\n            % (" open" if open_ else "", summary_html, right, body_html))\n\n\ndef foot(text: str) -> str:\n    return "<div class=\'foot\'>" + text + "</div>"\n\n\ndef close() -> str:\n    return "</div></body></html>"\n\n\ndef open_wrap() -> str:\n    return "<div class=\'wrap\'>"\n'
_FILES['mapbuild.py'] = '"""\nInteractive risk map (v4).\n\nCollisions vs contributing factors: only actual crashes get map markers —\nlive ⚠ plus recent 💥 crashes from trailing memory, which fade over ~2\ndays (the caller passes trail pre-filtered to crashes).\nEverything else — weather, recent-incident echo, closures/roadwork/\ncongestion — shapes the county COLOR, and the county click-panel itemizes\nexactly what fed it. Alongside the HTML, build_map writes\nlive_markers.json; the open page re-fetches it (same-origin, no keys)\nevery 5 minutes so markers and colors track the newest pipeline run\nwithout a manual reload.\n\n- County polygons (choropleth) shaded by risk — geometry is geographic, so\n  it stays county-sized at every zoom level. Fallback when the GeoJSON\n  can\'t be fetched: L.circle with a radius in *meters* (also zoom-correct).\n- Hover tooltip explains WHY a county is hot: EMS opportunity rank and\n  injured patients/yr, weather conditions in the horizon and the peak-risk\n  window, active incidents, and the county\'s top inbound commuter origins.\n- Click a county to draw its commuter inflow lines (Census LODES): where\n  the people traveling through it come from, line weight ~ share.\n- LIVE MODE: while the page is open it re-fetches Open-Meteo every 15\n  minutes for the dynamic counties, recomputes the weather multipliers in\n  the browser, and recolors the map. Incidents refresh on notebook re-run.\n"""\nfrom __future__ import annotations\n\nimport datetime as _dt\nimport json\nimport os\n\nimport config\nfrom ledger import is_truck\n\n\ndef build_map(scores, geo, origins, *, badges=None, path, hours=48, trail=None,\n              live=None, hotspots=None, segments=None, coverage=None,\n              degraded=None):\n    fips_by_norm = geo["name_to_fips"] if geo else {}\n    import re\n    norm = lambda s: re.sub(r"[^a-z]", "", str(s).lower())  # noqa: E731\n\n    counties_js = {}\n    for r in scores.itertuples():\n        fips = fips_by_norm.get(norm(r.county))\n        cen = (geo["centroids"].get(fips) if geo and fips\n               else config.COUNTY_CENTROIDS.get(r.county))\n        counties_js[r.county] = {\n            "fips": fips, "risk": float(r.risk_score),\n            "rank": int(r.rank), "injured": float(r.injured_patients),\n            "serious": float(r.serious_cases),\n            "opportunity": float(r.opportunity_score),\n            "metro": r.metro, "dynamic": bool(r.dynamic),\n            "events": float(r.active_events),\n            "incBoost": float(r.incident_boost),\n            "lift": float(r.weather_lift),\n            "wx": r.wx_conditions, "peak": r.wx_peak,\n            "trailing": float(r.trailing_weight),\n            "learned": float(getattr(r, "learned_adj", 1.0)),\n            "cov": (coverage or {}).get(r.county),\n            "truckBadge": (badges or {}).get("truck", {}).get(r.county),\n            "lat": cen[0] if cen else None,\n            "lon": cen[1] if cen else None,\n            "flows": (origins.get(fips, {}) if fips else {}),\n        }\n\n    features = geo["features"] if geo else []\n    generated = config.local_now().isoformat(timespec="seconds")\n    payload = {\n        "counties": counties_js,\n        "generated": generated,\n        "minMarkerW": config.MAP_MIN_MARKER_WEIGHT,\n        "trail": [\n            {"lat": e["lat"], "lon": e["lon"], "type": e["type"],\n             "desc": e.get("desc", ""), "county": e["county"],\n             "road": e.get("road", ""),\n             "truck": is_truck(f"{e.get(\'type\', \'\')} {e.get(\'desc\', \'\')}"),\n             "first": str(e.get("first_seen", ""))[:16],\n             "last": str(e.get("last_seen", ""))[:16],\n             "mag": e["magnitude"], "imp": e["importance"],\n             "decay": e["decay"], "age_h": e["age_h"]}\n            for e in (trail or []) if e.get("lat") is not None],\n        "live": [\n            {"lat": e["lat"], "lon": e["lon"],\n             "type": str(e.get("type", "event"))[:80],\n             "desc": str(e.get("desc", ""))[:160],\n             "road": e.get("road", ""),\n             "first": str(e.get("first_seen", ""))[:16],\n             "truck": is_truck(f"{e.get(\'type\', \'\')} {e.get(\'desc\', \'\')}"),\n             "cat": e.get("category", "other"),\n             "w": e.get("weight", 0.3),\n             "staleH": e.get("stale_h"),\n             "county": e.get("county", "")}\n            for e in (live or []) if e.get("lat") is not None],\n        "hotspots": hotspots or [],\n        "segments": segments or [],\n        "hotspotMin": config.HOTSPOT_MIN_N,\n        "hotspotWindowD": config.HOTSPOT_WINDOW_D,\n        "degraded": degraded,\n        # TomTom key for the client-side live-traffic tile overlay. Embedded\n        # in the public HTML on purpose (raster map-tile keys are meant to be\n        # client-side; restrict the key to the Pages domain in the TomTom\n        # dashboard). Empty string when the env var is absent -> the page\n        # simply never creates the layer, everything else unchanged.\n        "tt": os.environ.get("TOMTOM_API_KEY", "").strip(),\n        "features": features,\n        "hours": hours,\n        "exposure": _exposure_vec(),\n        "dynamicCentroids": {\n            c: {"lat": counties_js[c]["lat"], "lon": counties_js[c]["lon"]}\n            for c, v in counties_js.items()\n            if v["dynamic"] and v["lat"] is not None},\n    }\n\n    html = _TEMPLATE.replace("__PAYLOAD__", json.dumps(payload))\n    with open(path, "w") as f:\n        f.write(html)\n    # Sidecar consumed by the open page\'s 5-minute incident auto-refresh\n    # (same-origin fetch; must be published next to the HTML).\n    refresh = {\n        "generated": generated,\n        "live": payload["live"],\n        "trail": payload["trail"],\n        "counties": {n: {"events": c["events"], "incBoost": c["incBoost"],\n                         "trailing": c["trailing"]}\n                     for n, c in counties_js.items()},\n    }\n    side = os.path.join(os.path.dirname(path) or ".", "live_markers.json")\n    with open(side, "w") as f:\n        json.dump(refresh, f)\n\n\ndef _exposure_vec():\n    vec = []\n    for wd in range(7):\n        prof = config.WEEKDAY_HOURLY if wd < 5 else config.WEEKEND_HOURLY\n        vec.extend(prof)\n    mean = sum(vec) / len(vec)\n    return [round(v / mean, 4) for v in vec]\n\n\n_TEMPLATE = r"""<!DOCTYPE html><html><head><meta charset="utf-8">\n<meta name="viewport" content="width=device-width, initial-scale=1">\n<title>Indiana Accident Risk — Live</title>\n<link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/leaflet.min.css"/>\n<script src="https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/leaflet.min.js"></script>\n<style>\nhtml,body{height:100%;margin:0;font-family:system-ui,sans-serif}\n#map{height:100%;transition:margin-right .25s}\nbody.panel-open #map{margin-right:360px}\n.panel-box{background:#fff;padding:8px 12px;border-radius:6px;font-size:13px;\nbox-shadow:0 1px 4px rgba(0,0,0,.3)}\n.leaflet-tooltip.hint{font-size:12px;font-weight:600;padding:3px 8px}\n.leaflet-interactive{cursor:pointer}\n#side{position:fixed;top:0;right:-380px;width:360px;height:100%;background:#fff;\nbox-shadow:-2px 0 10px rgba(0,0,0,.25);transition:right .25s;z-index:1200;\noverflow-y:auto;box-sizing:border-box;padding:16px 18px}\nbody.panel-open #side{right:0}\n#side h2{margin:0 44px 4px 0;font-size:18px}\n#side .badge{display:inline-block;padding:1px 9px;border-radius:10px;color:#fff;font-weight:700}\n#side .sec{margin:14px 0 0}\n#side .sec h3{margin:0 0 4px;font-size:12px;text-transform:uppercase;letter-spacing:.05em;color:#777}\n#side .sec div{font-size:13.5px;line-height:1.5}\n#closebtn{position:absolute;top:10px;right:12px;border:none;background:#eee;\nborder-radius:50%;width:28px;height:28px;font-size:15px;cursor:pointer}\n.origin-row{display:flex;justify-content:space-between;border-bottom:1px solid #f0f0f0;padding:2px 0}\n.bar{height:6px;background:#08519c;border-radius:3px;margin-top:2px}\n.inc{display:flex;align-items:center;justify-content:center;border-radius:50%;\nbackground:#fff;font-weight:700;box-shadow:0 1px 6px rgba(0,0,0,.6);\nline-height:1}\n.inc.live{border:3px solid #c62828;color:#c62828}\n.inc.past{border:3px solid #5e35b1;color:#5e35b1}\n.inc.hot{border:3.5px solid #e65100;color:#e65100;border-radius:9px;background:#fff8f0}\n@media (max-width:700px){#side{width:85%}body.panel-open #map{margin-right:0}}\n#topnav{position:fixed;top:0;left:0;right:0;z-index:1100;\nbackground:#fff;border-bottom:1px solid #D9DFD8;\nbox-shadow:0 4px 18px -14px rgba(18,23,28,.6);\ndisplay:flex;justify-content:center;gap:2px;padding:0 12px;\noverflow-x:auto;scrollbar-width:none}\n#topnav::-webkit-scrollbar{display:none}\n#topnav a{font-family:\'Oswald\',\'Archivo Narrow\',\'Roboto Condensed\',\n\'Franklin Gothic Medium\',\'Arial Narrow\',system-ui,sans-serif;\nfont-size:13px;font-weight:600;letter-spacing:.09em;text-transform:uppercase;\ntext-decoration:none;color:#6E7880;padding:13px 14px 10px;\nborder-bottom:3px solid transparent;white-space:nowrap;\ndisplay:flex;align-items:center;gap:8px}\n#topnav a:hover{color:#12171C;background:#EEF1EC}\n#topnav a .dot{width:7px;height:7px;border-radius:50%;background:currentColor;\nopacity:.55}\n#topnav a.cur{color:#14603C;border-bottom-color:#14603C;cursor:default}\n#topnav a.cur .dot{opacity:1}\n#topnav a:focus-visible{outline:3px solid #14603C;outline-offset:-3px}\n@media (max-width:700px){#topnav a{font-size:11.5px;padding:11px 10px 8px}}\n/* the tab bar is a full-width overlay now, so nudge Leaflet\'s own\n   top-anchored controls and any top-anchored panes clear of it */\n.leaflet-top{margin-top:48px}\n#legend{max-width:270px}\n#legend .lg-h{display:flex;justify-content:space-between;align-items:center;\ngap:10px;cursor:pointer;font-weight:700;user-select:none}\n#legend .lg-h .car{color:#888;font-size:11px;transition:transform .2s}\n#legend.folded .lg-h .car{transform:rotate(-90deg)}\n#legend.folded #lg-body{display:none}\n#legend.folded{padding:5px 11px}\n#legend.folded .lg-sub{display:none}\n#legend .lg-row{display:flex;align-items:flex-start;gap:7px;margin:4px 0;\nfont-size:12.5px;line-height:1.35}\n#legend .lg-sym{flex:0 0 22px;text-align:center;font-weight:700}\n#legend .lg-status{border-top:1px solid #e5e5e5;margin-top:7px;padding-top:5px;\ncolor:#666;font-size:11.5px;line-height:1.5}\n</style></head><body><div id="map"></div>\n<div id="topnav"><a href="index.html" class="cur"><span class="dot"></span>Live Risk Map</a><a href="safety_watch.html"><span class="dot"></span>Road Safety Watch</a><a href="action_brief.html"><span class="dot"></span>Hotspot Action Brief</a><a href="ad_ops.html"><span class="dot"></span>Ad Ops Sheet</a></div>\n<script>(function(){var t=document.querySelector("#topnav a.cur");if(t&&t.scrollIntoView)t.scrollIntoView({block:"nearest",inline:"center"});})();</script>\n<div id="side"><button id="closebtn" onclick="closePanel()">×</button><div id="sidecontent"></div></div>\n<script>\nconst D = __PAYLOAD__;\nconst map = L.map(\'map\').setView([39.9,-86.3],7);\nL.tileLayer(\'https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png\',\n {attribution:\'&copy; OpenStreetMap · risk: EMS opportunity × weather × exposure · flows: Census LODES\'}).addTo(map);\n\n// ---------- live traffic overlay (TomTom raster flow tiles) ----------\n// Style "relative-delay" paints ONLY segments moving slower than free\n// flow, so the risk choropleth underneath stays legible statewide.\n// Tiles live in a custom pane above the county fills (overlayPane=400)\n// but below markers/tooltips (600+); pointer events pass through so\n// county hover/click still work. Layer is skipped when no key was\n// present at build time. redraw() every 5 min pulls fresh tiles\n// (TomTom re-renders them every minute).\nlet trafficLayer=null;\nif(D.tt){\n  map.createPane(\'traffic\');\n  map.getPane(\'traffic\').style.zIndex=450;\n  map.getPane(\'traffic\').style.pointerEvents=\'none\';\n  trafficLayer=L.tileLayer(\n    \'https://api.tomtom.com/traffic/map/4/tile/flow/relative-delay/{z}/{x}/{y}.png?key=\'+D.tt+\'&thickness=10\',\n    {pane:\'traffic\',opacity:0.9,maxZoom:22,attribution:\'live traffic &copy; TomTom\'}).addTo(map);\n  setInterval(()=>{ if(map.hasLayer(trafficLayer)) trafficLayer.redraw(); },300000);\n}\n\nconst byFips = {};\nObject.entries(D.counties).forEach(([name,c])=>{ c.name=name; if(c.fips) byFips[c.fips]=c; });\n\n// Continuous, power-scaled ramp: opportunity is very top-heavy, so a\n// linear scale flattens most counties into one shade. t = (r/100)^0.35\n// spreads the low end — risk 1, 3, and 8 get visibly different fills.\nconst RAMP=[[0,[255,243,238]],[0.25,[252,187,161]],[0.5,[251,106,74]],[0.75,[203,24,29]],[1,[103,0,13]]];\nfunction color(r){\n  const t=Math.pow(Math.min(Math.max(r,0),100)/100,0.35);\n  for(let i=1;i<RAMP.length;i++){\n    if(t<=RAMP[i][0]){\n      const [t0,c0]=RAMP[i-1],[t1,c1]=RAMP[i],f=(t-t0)/(t1-t0);\n      return \'rgb(\'+c0.map((v,k)=>Math.round(v+(c1[k]-v)*f)).join(\',\')+\')\';\n    }\n  }\n  return \'rgb(103,0,13)\';\n}\n// Incident heat flush: blend the fill toward hot red in proportion to the\n// county\'s incident boost. One live crash (boost x1.10) is a clearly\n// visible warm shift even on a pale county; it fades back over ~2 days\n// exactly as the trailing weight decays the boost toward x1.00.\nfunction fillFor(c){\n  const k=Math.min(1,Math.max(0,(c.incBoost-1)/0.3));\n  if(k<=0.01) return color(c.risk);\n  const m=color(c.risk).match(/\\d+/g).map(Number);\n  const hot=[225,25,0];\n  const f=0.5*k;\n  return \'rgb(\'+m.map((v,i)=>Math.round(v+(hot[i]-v)*f)).join(\',\')+\')\';\n}\n\n// ---------- side panel ----------\nfunction sec(title, body){ return `<div class="sec"><h3>${title}</h3><div>${body}</div></div>`; }\nfunction panelHTML(c,name){\n  let h = `<h2>${name} County <span class="badge" style="background:${color(c.risk)}">risk ${c.risk.toFixed(1)}</span></h2>`;\n  h += `<div style="color:#777;font-size:12.5px">${c.metro===\'other_in\'?\'outside core metros\':c.metro+\' market\'} · next ${D.hours}h</div>`;\n  h += sec(\'Why this county scores here\',\n    `#${c.rank} statewide in EMS-measured crash injuries — ${Math.round(c.injured).toLocaleString()} injured patients/yr, ${Math.round(c.serious)} serious cases.`);\n  if(c.dynamic){\n    h += sec(\'Weather (next \'+D.hours+\'h)\',\n      `${c.wx}. Overall risk lift <b>×${c.lift.toFixed(2)}</b>${c.peak?`; peak-risk window <b>${c.peak}</b>`:\'\'}.`);\n  } else {\n    h += sec(\'Weather\', \'<i>Weather feed did not reach this county this run — using neutral baseline.</i>\');\n  }\n  let inc=\'\';\n  const f=countyFactors(name), crashes=f[\'crash\']||0;\n  if(crashes) inc += `<b>⚠ ${crashes} active crash${crashes>1?\'es\':\'\'}</b> — marked on the map.<br>`;\n  const parts=Object.entries(f).filter(([k])=>k!==\'crash\')\n    .map(([k,v])=>`${v} ${FACTOR_LABEL[k]||k}`);\n  if(parts.length) inc += `<b>Traffic factors</b> shading this county (no markers): ${parts.join(\', \')}.<br>`;\n  if(c.trailing>0.05) inc += `<b>Recent-incident echo</b>: weight <b>${c.trailing.toFixed(1)}</b> from significant events in the last ~2 days, fading as they age.<br>`;\n  if(inc) inc += `Together these boost this county\'s color ×${c.incBoost.toFixed(2)} on top of its injury baseline and weather.`;\n  h += sec(\'Live & recent traffic (feeds the color)\', inc ||\n    \'Nothing live or recent — color here is injury baseline × weather only.\');\n  if(c.truckBadge){\n    h += sec(\'Vehicle profile\', `🚛 <b>Trucking-crash-prone</b> — ${c.truckBadge}.`);\n  }\n  if(c.learned && Math.abs(c.learned-1)>=0.005)\n    h += sec(\'Learned county adjustment\', `Official ARIES crash records (all roads, all severities) blended with every crash our own feeds record shift this county ×<b>${c.learned.toFixed(2)}</b> against its EMS-injury baseline (coverage-corrected and recentred so shifts are relative between counties; capped and shrunk toward 1.0 — the EMS baseline stays the anchor).`);\n  if(c.cov){\n    const g=c.cov.grade;\n    let txt;\n    if(g===\'learning\') txt=\'Not graded yet — the statewide crash archive is still in its learning phase.\';\n    else if(g===\'small sample\') txt=`Too few expected crashes here to grade reliably yet (${c.cov.obs} archived so far).`;\n    else txt=`Grade <b>${g}</b> — our feeds captured ${c.cov.obs} of ~${c.cov.exp} crashes expected here, judged against similar-sized counties (peer capture ×${c.cov.peer||1})`+((g===\'D\'||g===\'F\')?\'. <b>Quiet feeds here mean low observation, not low risk</b> — the color leans on the EMS/ARIES baseline instead.\':\'.\');\n    if(c.cov.trend) txt+=` <b>Trend: capture ${c.cov.trend}</b> vs this county\'s own history${c.cov.trend===\'falling\'?\' — check for a feed change before reading it as a safety change\':\'\'}.`;\n    h += sec(\'Feed coverage (are we seeing this county?)\', txt);\n  }\n  if(c.flows && c.flows.origins && c.flows.origins.length){\n    let rows = `<div class="origin-row"><span>local (lives in-county)</span><b>${((c.flows.internal_share||0)*100).toFixed(0)}%</b></div>`;\n    const mx = Math.max(...c.flows.origins.map(o=>o.share));\n    c.flows.origins.forEach(o=>{\n      rows += `<div class="origin-row"><span>${o.label}</span><b>${(o.share*100).toFixed(1)}%</b></div>`+\n              `<div class="bar" style="width:${(o.share/mx*100).toFixed(0)}%"></div>`;\n    });\n    rows += `<div style="color:#777;font-size:12px;margin-top:6px">Census commuter data — blue lines on the map show these inflows. Counties above are candidates to include in this hotspot\'s ad geography.</div>`;\n    h += sec(\'Who travels through (origins)\', rows);\n  }\n  return h;\n}\nfunction incidentPanelHTML(t){\n  const age = t.age_h<48 ? `${Math.round(t.age_h)}h ago` : `${(t.age_h/24).toFixed(1)} days ago`;\n  let h = `<h2>${t.truck?\'🚛\':\'💥\'} Recent ${t.truck?\'truck-involved \':\'\'}crash <span class="badge" style="background:#5e35b1">fading</span></h2>`;\n  h += sec(\'What\', `${t.type}${t.desc?`<br><span style="color:#555">${t.desc}</span>`:\'\'}`);\n  h += sec(\'Where / when\', `${t.county} County${t.road?` · <b>${t.road}</b>`:\'\'}${t.first?`<br>first on feed (Indiana time) ${t.first.replace(\'T\',\' \')}${t.last&&t.last!==t.first?` · last ${t.last.replace(\'T\',\' \')}`:\'\'}`:\'\'} · ${age}.`+\n    (t.lat!=null?`<br><span style="color:#777">${t.lat.toFixed(4)}, ${t.lon.toFixed(4)}</span>`:\'\'));\n  h += sec(\'Current weight\', `Magnitude ${t.mag}/5, decayed to <b>${t.imp.toFixed(2)}</b> (${(t.decay*100).toFixed(0)}% remaining; 48h half-life). It shrinks and fades as it ages, and leaves the map after ~4 days.`);\n  return h;\n}\nconst FACTOR_LABEL={\'closure/hazard\':\'closures/hazards\',\'stalled/disabled\':\'stalled vehicles\',\n \'congestion\':\'congestion reports\',\'roadwork\':\'roadwork zones\',\'other\':\'other events\'};\nfunction countyFactors(name){\n  const f={};(D.live||[]).forEach(t=>{if(t.county===name)f[t.cat]=(f[t.cat]||0)+1;});\n  return f;\n}\nfunction openPanel(html){ document.getElementById(\'sidecontent\').innerHTML=html; document.body.classList.add(\'panel-open\'); setTimeout(()=>map.invalidateSize(),260); }\nfunction closePanel(){ document.body.classList.remove(\'panel-open\'); flowLayer.clearLayers(); setTimeout(()=>map.invalidateSize(),260); }\n\n// ---------- flows ----------\nlet flowLayer = L.layerGroup().addTo(map);\nfunction drawFlows(c){\n  flowLayer.clearLayers();\n  if(!(c.flows&&c.flows.origins&&c.lat)) return;\n  c.flows.origins.forEach(o=>{\n    if(o.lat==null) return;\n    L.polyline([[o.lat,o.lon],[c.lat,c.lon]],{color:\'#08519c\',weight:1+o.share*30,opacity:.65}).addTo(flowLayer);\n    L.circleMarker([o.lat,o.lon],{radius:4,color:\'#08519c\',fillOpacity:.9}).addTo(flowLayer);\n  });\n}\n\n// ---------- county layer ----------\nlet geoLayer=null, fallbackLayer=null;\nlet shadeOn=true;  // \'County risk shading\' toggle (borders stay for clicks)\nfunction styleFor(c){return {color:\'#555\',weight:c.events>0?2.5:1,\n  dashArray:c.events>0?\'4\':null,fillColor:fillFor(c),\n  fillOpacity:shadeOn?.62:0};}\nconst hoverStyle={weight:3,color:\'#111\',fillOpacity:.8};\n\nfunction wireCounty(layer,c,name){\n  layer.bindTooltip(`${name} County — click for details`,{sticky:true,className:\'hint\',direction:\'top\'});\n  layer.on(\'mouseover\',()=>layer.setStyle({...hoverStyle,fillOpacity:shadeOn?.8:0}));\n  layer.on(\'mouseout\',()=>layer.setStyle(styleFor(c)));\n  layer.on(\'click\',()=>{openPanel(panelHTML(c,name)); drawFlows(c);});\n}\nfunction render(){\n  if(D.features && D.features.length){\n    if(geoLayer) map.removeLayer(geoLayer);\n    geoLayer = L.geoJSON({type:\'FeatureCollection\',features:D.features},{\n      style: f=>{const c=byFips[f.id]; return c?styleFor(c):{fillColor:\'#eee\',color:\'#999\',weight:.5,fillOpacity:.3};},\n      onEachFeature:(f,layer)=>{ const c=byFips[f.id]; if(c) wireCounty(layer,c,c.name); }}).addTo(map);\n  } else {\n    if(fallbackLayer) map.removeLayer(fallbackLayer);\n    fallbackLayer=L.layerGroup().addTo(map);\n    Object.entries(D.counties).forEach(([name,c])=>{\n      if(c.lat==null) return;\n      const layer=L.circle([c.lat,c.lon],{radius:13000,...styleFor(c)}).addTo(fallbackLayer);\n      wireCounty(layer,c,name);\n    });\n  }\n}\nrender();\n\n// ---------- incident markers (live + fading past) ----------\nfunction incIcon(cls, sym, size, alpha){\n  return L.divIcon({className:\'\', iconSize:[size,size], iconAnchor:[size/2,size/2],\n    html:`<div class="inc ${cls}" style="width:${size}px;height:${size}px;opacity:${alpha};font-size:${Math.round(size*0.62)}px">${sym}</div>`});\n}\nfunction agoTxt(h){ return h<48 ? Math.round(h)+\'h ago\' : (h/24).toFixed(1)+\'d ago\'; }\nfunction livePanelHTML(t){\n  let h = `<h2>${t.truck?\'🚛\':\'⚠\'} Live ${t.truck?\'truck-involved \':\'\'}incident <span class="badge" style="background:#c62828">active now</span></h2>`;\n  h += sec(\'What\', `${t.type}${t.desc?`<br><span style="color:#555">${t.desc}</span>`:\'\'}`);\n  h += sec(\'Where\', `${t.county} County${t.road?` · <b>${t.road}</b>`:\'\'}${t.staleH?` — still listed on the live feeds <b>${(t.staleH/24).toFixed(1)} days</b> after first report (stale listing; real crashes clear within hours).`:` — currently on the live incident feeds.`}${t.first?` First reported <b>${t.first.replace(\'T\',\' \')}</b> (Indiana time).`:\'\'}`+\n    (t.lat!=null?`<br><span style="color:#777">${t.lat.toFixed(4)}, ${t.lon.toFixed(4)}</span>`:\'\'));\n  h += sec(\'Risk contribution\', `Classified as <b>${t.cat}</b>${t.truck?\' (truck-involved — counts toward this county\\\'s 🚛 profile)\':\'\'} — weight ${t.w.toFixed(2)} toward this county\'s color.${t.staleH?\' <i>(reduced: stale listing)</i>\':\'\'}`);\n  return h;\n}\nconst liveLayer = L.layerGroup().addTo(map);\nfunction drawLive(){\n  liveLayer.clearLayers();\n  (D.live||[]).forEach(t=>{\n    if(t.w < D.minMarkerW) return; // factors shade the county, no marker\n    const m=L.marker([t.lat,t.lon],{icon:incIcon(\'live\',t.truck?\'🚛\':\'⚠\',24,1),zIndexOffset:1000+Math.round(t.w*100)}).addTo(liveLayer);\n    m.bindTooltip(`LIVE ${t.truck?\'TRUCK \':\'\'}${t.cat}: ${t.type}${t.road?` · ${t.road}`:\'\'}${t.first?` · reported ${t.first.slice(11,16)}`:\'\'}`,{sticky:true,className:\'hint\',direction:\'top\'});\n    m.on(\'click\',()=>openPanel(livePanelHTML(t)));\n  });\n}\ndrawLive();\nconst trailLayer = L.layerGroup().addTo(map);\nfunction drawTrail(){\n  trailLayer.clearLayers();\n  (D.trail||[]).forEach(t=>{\n    const size=Math.round(13+(4+t.mag*2.5)*t.decay), alpha=0.35+0.55*t.decay;\n    const m=L.marker([t.lat,t.lon],{icon:incIcon(\'past\',t.truck?\'🚛\':\'💥\',size,alpha),zIndexOffset:500}).addTo(trailLayer);\n    m.bindTooltip(`Recent ${t.truck?\'truck \':\'\'}crash: ${t.type}${t.road?` · ${t.road}`:\'\'} — ${agoTxt(t.age_h)}`,{sticky:true,className:\'hint\',direction:\'top\'});\n    m.on(\'click\',()=>openPanel(incidentPanelHTML(t)));\n  });\n}\ndrawTrail();\n// ---------- vehicle-profile county badges ----------\nconst badgeLayer = L.layerGroup().addTo(map);\nObject.entries(D.counties).forEach(([name,c])=>{\n  if(c.lat==null) return;\n  const put=(sym,txt,dx)=>{\n    const m=L.marker([c.lat,c.lon+dx],{icon:L.divIcon({className:\'\',iconSize:[30,30],iconAnchor:[15,15],\n      html:`<div style="width:30px;height:30px;border-radius:7px;background:#fff;border:2px solid #b45309;box-shadow:0 1px 5px rgba(0,0,0,.45);display:flex;align-items:center;justify-content:center;font-size:19px">${sym}</div>`}),\n      zIndexOffset:650}).addTo(badgeLayer);\n    m.bindTooltip(`${name} County — ${txt}`,{sticky:true,className:\'hint\',direction:\'top\'});\n    m.on(\'click\',()=>openPanel(panelHTML(c,name)));\n  };\n  if(c.truckBadge) put(\'🚛\', \'trucking-crash-prone: \'+c.truckBadge, -0.055);\n});\n\n// ---------- crash hotspot segments (archived repeat-crash spots) ----------\nfunction hotspotPanelHTML(s){\n  let h=`<h2>📍 Crash hotspot <span class="badge" style="background:#e65100">${s.n} archived crashes</span></h2>`;\n  h+=sec(\'Where\',`${s.county||\'?\'} County${s.road?` · <b>${s.road}</b>`:\'\'}<br><span style="color:#777">${s.lat.toFixed(4)}, ${s.lon.toFixed(4)}</span>`);\n  h+=sec(\'History\',`Our feeds have archived <b>${s.n}</b> crashes within ~400 m of this spot${s.first?` (${s.first} → ${s.last})`:\'\'}${s.truck?`, <b>${s.truck} truck-involved</b>`:\'\'}. A segment earns a pin at ${D.hotspotMin}+ archived crashes within the last ${D.hotspotWindowD} days — pins age out when a spot goes quiet.`);\n  if(s.rel) h+=sec(\'How unusual\',`<b>${s.rel}×</b> the median repeat-crash ${s.cls} location statewide in the same window (relative to our own archive; not a traffic-volume-adjusted rate).`);\n  h+=(``);\n  return h;\n}\nconst hotLayer = L.layerGroup().addTo(map);\n(D.hotspots||[]).forEach(s=>{\n  const m=L.marker([s.lat,s.lon],{icon:incIcon(\'hot\',\'📍\',36,1),zIndexOffset:900}).addTo(hotLayer);\n  m.bindTooltip(`Hotspot: ${s.n} crashes${s.rel?` · ${s.rel}× class typical`:\'\'}${s.road?` · ${s.road}`:\'\'}`,{sticky:true,className:\'hint\',direction:\'top\'});\n  m.on(\'click\',()=>openPanel(hotspotPanelHTML(s)));\n});\n\n// ---------- risky corridor segments (multi-km, same window) ----------\nfunction segmentPanelHTML(s){\n  let h=`<h2>〰 Risky corridor <span class="badge" style="background:#0e7490">${s.n} crashes / ${s.km} km</span></h2>`;\n  h+=sec(\'Where\',`<b>${s.road}</b> (${s.cls}) · ${s.county} County${s.county.includes(\'/\')?\' area\':\'\'}`);\n  h+=sec(\'Pattern\',`<b>${s.n}</b> archived crashes on <b>${s.days}</b> distinct days along a <b>${s.km} km</b> stretch in the last ${D.hotspotWindowD} days — ${s.per_km}/km${s.truck?`, <b>${s.truck} truck-involved</b>`:\'\'} (${s.first} → ${s.last}). Corridors complement 📍 hotspots: a stretch can be contentious without any single 400 m cell crossing the hotspot bar.`);\n  h+=sec(\'Reading the line\',`The line connects this corridor\'s actual crash locations (the pipeline has no road-geometry data), so it approximates the roadway.`);\n  return h;\n}\n// Own pane at z=460: above county fills (overlayPane 400) and the\n// TomTom traffic tiles (450), below markers (600). Without this the\n// county layer — re-inserted into the shared SVG on every recolor —\n// paints over the lines and buries them.\nmap.createPane(\'segments\');\nmap.getPane(\'segments\').style.zIndex=460;\nconst segLayer = L.layerGroup().addTo(map);\n(D.segments||[]).forEach(s=>{\n  if(!s.path || s.path.length<2) return;\n  // white casing under a teal dash: cool hue reads against the red\n  // choropleth and red traffic lines; the halo reads on any background\n  L.polyline(s.path,{pane:\'segments\',color:\'#fff\',weight:12,opacity:.95}).addTo(segLayer);\n  const pl=L.polyline(s.path,{pane:\'segments\',color:\'#0e7490\',weight:6.5,opacity:1,dashArray:\'10 6\'}).addTo(segLayer);\n  pl.bindTooltip(`Risky corridor: ${s.road} — ${s.n} crashes / ${s.km} km`,{sticky:true,className:\'hint\'});\n  pl.on(\'click\',()=>openPanel(segmentPanelHTML(s)));\n});\n\n// ---------- layer toggles ----------\n// Shading is a polygon STYLE, not a layer, so a placeholder overlay\n// drives a flag: removing it from the control clears county fills\n// (borders/click/hover stay so the map remains navigable).\nconst shadePlaceholder=L.layerGroup().addTo(map);\nmap.on(\'overlayadd\',e=>{ if(e.layer===shadePlaceholder){shadeOn=true; render();} });\nmap.on(\'overlayremove\',e=>{ if(e.layer===shadePlaceholder){shadeOn=false; render();} });\nconst overlays={\n  \'County risk shading\':shadePlaceholder,\n  \'Live incidents ⚠\':liveLayer,\n  \'Recent crashes 💥 (fading)\':trailLayer,\n  \'Hotspots 📍\':hotLayer,\n  \'Risky corridors 〰\':segLayer,\n  \'Truck-prone counties 🚛\':badgeLayer};\nif(trafficLayer) overlays[\'Live traffic (slowdowns)\']=trafficLayer;\nL.control.layers(null,overlays,{position:\'topleft\',collapsed:true}).addTo(map);\n\n// ---------- legend + live status ----------\nconst legend=L.control({position:\'bottomright\'});\nfunction lgRow(sym,txt){return \'<div class="lg-row"><span class="lg-sym">\'+sym+\'</span><span>\'+txt+\'</span></div>\';}\nlegend.onAdd=()=>{const d=L.DomUtil.create(\'div\',\'panel-box\');\n d.id=\'legend\';\n L.DomEvent.disableClickPropagation(d); L.DomEvent.disableScrollPropagation(d);\n let rows =\n  lgRow(\'<span style="background:linear-gradient(90deg,rgb(255,243,238),rgb(252,187,161),rgb(251,106,74),rgb(203,24,29),rgb(103,0,13));display:inline-block;width:20px;height:10px;border:1px solid #999;border-radius:2px"></span>\',\n        \'county risk, low → high (injuries baseline × weather × traffic); a red flush = live/recent incidents, fading as they decay\')+\n  lgRow(\'<span style="color:#c62828">⚠</span>\',\'live crash (🚛 if truck-involved)\')+\n  lgRow(\'<span style="color:#5e35b1">💥</span>\',\'recent crash — shrinks/fades with age, gone after ~4 days\')+\n  lgRow(\'<span style="color:#e65100">📍</span>\',\'hotspot: \'+D.hotspotMin+\'+ crashes within ~400 m in \'+D.hotspotWindowD+\' days\')+\n  ((D.segments&&D.segments.length)?lgRow(\'<span style="color:#0e7490;background:#fff;border-radius:2px;padding:0 2px">〰</span>\',\'risky corridor: repeat crashes chained along one road for 2+ km (\'+D.segments.length+\' this window)\'):\'\')+\n  (D.tt?lgRow(\'<span style="color:#d32f2f">▬</span>\',\'live traffic slowdowns (TomTom; toggle top-left)\'):\'\')+\n  lgRow(\'🚛\',\'trucking-crash-prone county (vs statewide truck share)\')+\n  lgRow(\'👆\',\'click any county, marker, or line for details\')+\n  (D.degraded?lgRow(\'<span style="color:#c62828">⚠</span>\',\'<span style="color:#c62828;font-weight:700">live feeds degraded since \'+D.degraded+\' — colors lean on baseline</span>\'):\'\');\n d.innerHTML =\n  \'<div class="lg-h" onclick="document.getElementById(\\\'legend\\\').classList.toggle(\\\'folded\\\')">\'+\n  \'<span>Legend<span class="lg-sub"> — next \'+D.hours+\'h</span></span><span class="car">▼</span></div>\'+\n  \'<div id="lg-body">\'+rows+\n  \'<div class="lg-status">\'+\n  \'<span id="livestatus">live weather: starting…</span><br>\'+\n  \'last build: \'+String(D.generated).replace(\'T\',\' \').slice(0,16)+\' (Indiana time)<br>\'+\n  \'<span id="incstatus">incidents: from this build</span></div></div>\';\n if(window.matchMedia && window.matchMedia(\'(max-width:700px)\').matches) d.classList.add(\'folded\');\n return d;};\nlegend.addTo(map);\n\n// ---------- LIVE MODE: refresh weather every 15 min ----------\nconst MULT={rl:1.25,rm:1.5,rh:1.8,sl:1.5,sm:1.8,sh:2.2,fz:2.5,fog:1.4,dark:1.25,wind:1.15};\nfunction wmult(p,s,t,vis,g,day,code){\n  let m=1;\n  if([56,57,66,67].includes(code)||(p>0.1&&t<=0)) m*=MULT.fz;\n  else if(s>2.5)m*=MULT.sh; else if(s>1)m*=MULT.sm; else if(s>0.1)m*=MULT.sl;\n  else if(p>7.6)m*=MULT.rh; else if(p>2.5)m*=MULT.rm; else if(p>0.1)m*=MULT.rl;\n  if(vis<1000)m*=MULT.fog; if(!day)m*=MULT.dark; if(g>40)m*=MULT.wind;\n  return Math.min(m,3.5);\n}\nasync function refreshWeather(){\n  const names=Object.keys(D.dynamicCentroids);\n  if(!names.length) return;\n  const lats=names.map(n=>D.dynamicCentroids[n].lat).join(\',\');\n  const lons=names.map(n=>D.dynamicCentroids[n].lon).join(\',\');\n  const url=`https://api.open-meteo.com/v1/forecast?latitude=${lats}&longitude=${lons}`+\n   `&hourly=precipitation,snowfall,temperature_2m,visibility,wind_gusts_10m,is_day,weather_code`+\n   `&forecast_days=${Math.min(7,Math.ceil(D.hours/24))}&timezone=America%2FIndiana%2FIndianapolis`;\n  try{\n    let payload=await (await fetch(url)).json();\n    if(!Array.isArray(payload)) payload=[payload];\n    names.forEach((name,i)=>{\n      const h=payload[i].hourly; let total=0;\n      for(let k=0;k<Math.min(D.hours,h.time.length);k++){\n        const ts=new Date(h.time[k]);\n        const ex=D.exposure[((ts.getDay()+6)%7)*24+ts.getHours()];\n        total+=wmult(h.precipitation[k],h.snowfall[k],h.temperature_2m[k],\n                     h.visibility[k],h.wind_gusts_10m[k],h.is_day[k],h.weather_code[k])*ex;\n      }\n      const c=D.counties[name];\n      c.lift=total/D.hours;\n    });\n    recolor();\n    document.getElementById(\'livestatus\').textContent=\'live weather: updated \'+new Date().toLocaleTimeString();\n  }catch(e){\n    document.getElementById(\'livestatus\').textContent=\'live weather: refresh failed (showing last data)\';\n  }\n}\nfunction recolor(){\n  Object.values(D.counties).forEach(c=>{ c._live=c.opportunity*(c.lift||1)*D.hours*c.incBoost; });\n  const mx=Math.max(...Object.values(D.counties).map(c=>c._live));\n  Object.entries(D.counties).forEach(([n,c])=>{c.risk=100*c._live/mx; if(c.fips&&byFips[c.fips])byFips[c.fips].risk=c.risk;});\n  render();\n}\nrefreshWeather();\nsetInterval(refreshWeather, 15*60*1000);\n\n// ---------- LIVE MODE: re-pull incidents from the newest pipeline build ----\n// Same-origin fetch of live_markers.json (republished by every Actions run;\n// no API keys in the page). Freshness is bounded by the pipeline cadence.\nasync function refreshIncidents(){\n  try{\n    const r=await fetch(\'live_markers.json?ts=\'+Date.now(),{cache:\'no-store\'});\n    if(!r.ok) return;\n    const j=await r.json();\n    if(!j || j.generated===D.generated) return; // same build, nothing new\n    D.live=j.live||D.live;\n    D.trail=j.trail||D.trail;\n    Object.entries(j.counties||{}).forEach(([n,u])=>{\n      const c=D.counties[n];\n      if(c){c.events=u.events;c.incBoost=u.incBoost;c.trailing=u.trailing;}\n    });\n    D.generated=j.generated;\n    drawLive(); drawTrail(); recolor();\n    document.getElementById(\'incstatus\').textContent=\n      \'incidents: pipeline run of \'+String(j.generated).replace(\'T\',\' \').slice(0,16);\n  }catch(e){/* offline / local file view — keep build-time data */}\n}\nsetInterval(refreshIncidents, 5*60*1000);\n</script></body></html>\n"""\n'
_FILES['deploy.py'] = '"""\nTranslate county risk into an ad plan (v2).\n\nOutputs:\n  budget_shares : metro-level blend of static Phase 2 shares and live\n                  county risk (counties roll up via COUNTY_TO_METRO;\n                  unmapped counties form the \'other_in\' bucket, reported\n                  but excluded from the Phase 2 blend).\n  county_targets: ranked county list for Google Ads county location\n                  targeting, with suggested within-budget weight.\n  cluster_mix   : per-metro keyword-cluster mix from Phase 2 efficiency.\n  dayparting    : high-risk hours per metro with suggested bid adjustments.\n"""\nfrom __future__ import annotations\n\nimport datetime as _dt\nimport html as _html\n\nimport pandas as pd\n\nimport config\nimport ui\n\n\ndef load_phase2():\n    prio = pd.read_csv(config.PHASE2_PRIORITY_CSV)\n    eff = pd.read_csv(config.PHASE2_EFFICIENCY_CSV)\n    return prio, eff\n\n\ndef budget_shares(county_scores: pd.DataFrame) -> pd.DataFrame:\n    live = county_scores.groupby("metro")["risk_score"].sum()\n    live_metros = live.drop(index="other_in", errors="ignore")\n    live_metros = live_metros / live_metros.sum()\n    w = config.DYNAMIC_WEIGHT\n    rows = []\n    for metro, static in config.STATIC_SHARES.items():\n        dyn = float(live_metros.get(metro, 0))\n        rows.append({"metro": metro, "static_share": static,\n                     "live_risk_share": round(dyn, 3),\n                     "blended_share": (1 - w) * static + w * dyn})\n    df = pd.DataFrame(rows)\n    df["blended_share"] = (df["blended_share"]\n                           / df["blended_share"].sum()).round(3)\n    df["shift_vs_static"] = (df["blended_share"]\n                             - df["static_share"]).round(3)\n    return df.sort_values("blended_share", ascending=False)\n\n\ndef county_targets(county_scores: pd.DataFrame, top_n: int = 30\n                   ) -> pd.DataFrame:\n    t = county_scores.head(top_n).copy()\n    t["within_plan_weight"] = (t["risk_score"]\n                               / t["risk_score"].sum()).round(3)\n    t["ads_location"] = t["county"] + " County, Indiana"\n    return t[["county", "metro", "risk_score", "weather_lift",\n              "active_events", "trailing_weight", "within_plan_weight",\n              "ads_location"]]\n\n\ndef cluster_mix(eff: pd.DataFrame) -> pd.DataFrame:\n    e = eff.copy()\n    e["mix"] = e.groupby("metro")["searches_per_1000usd"].transform(\n        lambda s: s / s.sum())\n    return e.sort_values(["metro", "mix"], ascending=[True, False])[\n        ["metro", "cluster", "monthly_searches", "est_cpc", "mix"]]\n\n\ndef daypart(county_hourly: pd.DataFrame,\n            county_scores: pd.DataFrame) -> pd.DataFrame:\n    """Opportunity-weighted metro hourly risk -> hours above the 75th\n    percentile with a +10%..+60% bid adjustment."""\n    h = county_hourly.merge(\n        county_scores[["county", "metro", "opportunity_score"]],\n        on="county", how="left")\n    h["w_risk"] = h["hour_risk"] * h["opportunity_score"]\n    mh = (h.groupby(["metro", "time"])["w_risk"].sum()\n          .rename("hour_risk").reset_index())\n    out = []\n    for metro, grp in mh.groupby("metro"):\n        q75 = grp["hour_risk"].quantile(0.75)\n        med = max(grp["hour_risk"].median(), 1e-9)\n        hot = grp[grp["hour_risk"] >= q75].copy()\n        hot["bid_adj_pct"] = ((hot["hour_risk"] / med - 1) * 100\n                              ).clip(10, 60).round(0)\n        out.append(hot)\n    return pd.concat(out).sort_values(["metro", "time"])\n\n\n# ---------------------------------------------------------------------------\n# Weekly ad ops sheet — plain-English one-pager for whoever runs Google Ads\n# ---------------------------------------------------------------------------\nADOPS_SNAPSHOT_DAYS = 7          # movers are measured against a snapshot\nADOPS_MIN_MOVE_PP = 0.10         # this old; refreshed once it exceeds the\n                                 # window. Movers under 0.10 pp are noise.\n\nMETRO_LABELS = {\n    "indianapolis": "Indianapolis", "indy": "Indianapolis",\n    "fortwayne": "Fort Wayne",\n    "nwindiana": "NW Indiana", "southbend": "South Bend",\n    "lafayette": "Lafayette", "evansville": "Evansville",\n    "other_in": "Rest of state",\n}\n\n\ndef _esc(x) -> str:\n    return _html.escape(str(x))\n\n\ndef _metro_label(m: str) -> str:\n    return METRO_LABELS.get(str(m), str(m))\n\n\ndef _daypart_ranges(parts: pd.DataFrame, metro: str,\n                    max_ranges: int = 4) -> list[str]:\n    """Collapse a metro\'s hot hours into ranges like\n    \'Tue 06:00-09:00 (bid +35%)\', strongest first."""\n    g = parts[parts["metro"] == metro].sort_values("time")\n    if g.empty:\n        return []\n    ranges, cur = [], None\n    for _, r in g.iterrows():\n        t = pd.Timestamp(r["time"])\n        if (cur is not None and t.date() == cur["date"]\n                and t.hour == cur["end"]):\n            cur["end"] = t.hour + 1\n            cur["adj"] = max(cur["adj"], float(r["bid_adj_pct"]))\n        else:\n            if cur is not None:\n                ranges.append(cur)\n            cur = {"date": t.date(), "day": t.strftime("%a"),\n                   "start": t.hour, "end": t.hour + 1,\n                   "adj": float(r["bid_adj_pct"])}\n    if cur is not None:\n        ranges.append(cur)\n    ranges.sort(key=lambda x: -x["adj"])\n    return ["%s %02d:00-%02d:00 (bid +%.0f%%)"\n            % (x["day"], x["start"], x["end"], x["adj"])\n            for x in ranges[:max_ranges]]\n\n\ndef _metro_why(scores: pd.DataFrame, metro: str) -> str:\n    """One line on what is driving a metro: its two riskiest counties."""\n    g = scores[scores["metro"] == metro].head(2)\n    bits = []\n    for _, r in g.iterrows():\n        d = []\n        if float(r.get("active_events", 0)) > 0:\n            d.append("%.1f live event wt" % float(r["active_events"]))\n        if float(r.get("trailing_weight", 0)) > 0:\n            d.append("%.1f recent-crash wt" % float(r["trailing_weight"]))\n        wl = float(r.get("weather_lift", 1.0))\n        if abs(wl - 1.0) >= 0.05:\n            d.append("weather x%.2f" % wl)\n        la = float(r.get("learned_adj", 1.0))\n        if abs(la - 1.0) >= 0.05:\n            d.append("learned adj x%.2f" % la)\n        bits.append("%s (risk %.0f%s)" % (\n            r["county"], float(r["risk_score"]),\n            "; " + ", ".join(d) if d else ""))\n    return " · ".join(bits) if bits else "quiet"\n\n\n# ---------------------------------------------------------------------------\n# Feed-coverage explanations (section 7)\n# ---------------------------------------------------------------------------\n# A grade on its own tells an ad buyer nothing actionable, so every grade\n# carries: what it means about our visibility, and what it licenses us to\n# do with spend. The policy is the same one the map and the public reports\n# use — A/B automated, C human review, D/F monitor only — stated here in\n# the words of the person who has to act on it.\n_GRADE_INFO = {\n    "A": ("Full visibility",\n          "Our feeds record about as many collisions here as we would "\n          "expect for a county this size — nothing obvious is missing.",\n          "Automated spend changes OK", "good"),\n    "B": ("Good visibility",\n          "We see most of what we would expect for a county this size. "\n          "Small gaps, no systematic blind spot.",\n          "Automated spend changes OK", "good"),\n    "C": ("Partial visibility",\n          "We record noticeably fewer collisions than a comparable county "\n          "produces. Live signals here are directionally useful but "\n          "incomplete.",\n          "Human review before moving spend", "warn"),\n    "D": ("Thin visibility",\n          "Most collisions in this county never reach our feeds. Risk "\n          "shown for it is driven by the EMS and ARIES baseline, not by "\n          "anything we observed.",\n          "Monitor only — do not move spend on live signal", "bad"),\n    "F": ("Effectively invisible",\n          "Our feeds capture almost nothing here. Treat any live signal "\n          "as noise; the county is also excluded from the public safety "\n          "reports for this reason.",\n          "Monitor only — do not move spend on live signal", "bad"),\n    "small sample": ("Too small to grade",\n                     "This county produces too few expected collisions "\n                     "for a capture rate to mean anything. Absence of "\n                     "signal here is not evidence of anything.",\n                     "Baseline targeting only", ""),\n    "learning": ("Not graded yet",\n                 "The statewide archive is still below the grading "\n                 "threshold, so no county has a capture grade yet.",\n                 "Baseline targeting only", ""),\n}\n\n_TREND_NOTE = {\n    "rising": "Capture is rising against this county\'s own history — the "\n              "feeds started seeing more here recently.",\n    "falling": "Capture is falling against this county\'s own history. "\n               "That usually means a feed change, not a safer county.",\n}\n\n\ndef _county_line(county: str, d: dict) -> str:\n    """County-SPECIFIC note only. What the grade means in general is\n    stated once at the head of each band; repeating it on all 92 rows\n    was the same paragraph 92 times and buried the actual numbers."""\n    grade = str(d.get("grade", "learning"))\n    obs, exp, rel = d.get("obs"), d.get("exp"), d.get("rel")\n    bits = []\n    if grade == "small sample":\n        bits.append("Only ~%.0f collisions expected here across the whole "\n                    "archive — too few for a capture rate to mean "\n                    "anything." % float(exp or 0))\n    elif grade == "learning":\n        bits.append("No grade until the statewide archive passes %d "\n                    "collisions." % config.LEDGER_MIN_TOTAL)\n    elif obs is not None and exp:\n        gap = float(exp) - float(obs)\n        bits.append("Recorded %d of roughly %.0f expected."\n                    % (int(obs), float(exp)))\n        if rel:\n            bits.append("That is %.2f× the capture rate of similarly "\n                        "sized counties." % float(rel))\n        if gap >= 3:\n            bits.append("Roughly %.0f collisions here are likely invisible "\n                        "to us." % gap)\n    if d.get("trend") in _TREND_NOTE:\n        bits.append(_TREND_NOTE[d["trend"]])\n    return " ".join(bits) if bits else "—"\n\n\n_GRADE_ORDER = ["A", "B", "C", "D", "F", "small sample", "learning"]\n_GRADE_COLOR = {"A": "#14603C", "B": "#4F8A5F", "C": "#B9861B",\n                "D": "#B4632A", "F": "#9E2B2B",\n                "small sample": "#8A9490", "learning": "#B7BFB6"}\n\n\ndef _coverage_section(coverage: dict, scores, degraded) -> str:\n    """Every county, grouped by grade, each group expandable, each county\n    carrying its numbers and a sentence explaining them.\n\n    This used to show the top ten counties by risk and nothing else,\n    which meant the counties most likely to be mis-targeted — the ones\n    we can barely see — were the ones least likely to appear.\n    """\n    if not coverage:\n        return ""\n    risk = {}\n    try:\n        for _i, r in scores.iterrows():\n            risk[str(r["county"])] = float(r["risk_score"])\n    except Exception:  # noqa: BLE001\n        pass\n\n    groups = {}\n    for c, d in coverage.items():\n        groups.setdefault(str(d.get("grade", "learning")), []).append((c, d))\n\n    H = [ui.h2("7", "Feed coverage — every county")]\n    H.append("<p class=\'lede\'>How much of what actually happens in each "\n             "county our live feeds actually see. This is the confidence "\n             "layer underneath every number on this page: a county we "\n             "cannot see cannot generate a trustworthy live signal, no "\n             "matter how its risk score looks.</p>")\n\n    counted = [(g, len(v)) for g, v in groups.items()]\n    counted.sort(key=lambda kv: _GRADE_ORDER.index(kv[0])\n                 if kv[0] in _GRADE_ORDER else 99)\n    H.append(ui.prop_bar([(g, n, _GRADE_COLOR.get(g, "#8A9490"))\n                          for g, n in counted]))\n    H.append("<p class=\'hint\'>Grades compare each county\'s capture rate "\n             "against the median of similarly sized counties, so a small "\n             "rural county is judged against other small rural counties "\n             "rather than against Marion. Expand any band to see its "\n             "counties.</p>")\n\n    if degraded:\n        H.append("<div class=\'note hold\'><b>Feed outage in progress.</b> "\n                 "These grades describe normal operation. While 511 is "\n                 "silent, treat every county as monitor-only regardless "\n                 "of grade.</div>")\n\n    for grade in _GRADE_ORDER:\n        rows = groups.get(grade)\n        if not rows:\n            continue\n        info = _GRADE_INFO.get(grade, _GRADE_INFO["learning"])\n        rows.sort(key=lambda cd: -risk.get(cd[0], 0.0))\n        body = ["<p class=\'small\'>%s <b>%s.</b></p>" % (_esc(info[1]),\n                                                        _esc(info[2])),\n                "<div class=\'tbl-scroll\'><table><tr><th>County</th>"\n                "<th class=\'num\'>Risk</th><th class=\'num\'>Recorded</th>"\n                "<th class=\'num\'>Expected</th><th class=\'num\'>vs peers</th>"\n                "<th>Trend</th><th>What this means here</th></tr>"]\n        for c, d in rows:\n            body.append(\n                "<tr><td><b>%s</b></td><td class=\'num\'>%s</td>"\n                "<td class=\'num\'>%s</td><td class=\'num\'>%s</td>"\n                "<td class=\'num\'>%s</td><td>%s</td>"\n                "<td><span class=\'small\'>%s</span></td></tr>"\n                % (_esc(c),\n                   ("%.0f" % risk[c]) if c in risk else "—",\n                   d.get("obs", "—"),\n                   ("%.0f" % d["exp"]) if d.get("exp") else "—",\n                   ("%.2f×" % d["rel"]) if d.get("rel") else "—",\n                   _esc(str(d.get("trend") or "stable")),\n                   _esc(_county_line(c, d))))\n        body.append("</table></div>")\n        summ = ("<b>Grade %s — %s</b>" % (_esc(grade), _esc(info[0]))\n                if grade in ("A", "B", "C", "D", "F")\n                else "<b>%s</b>" % _esc(info[0]))\n        right = ("<span class=\'chip %s\'>%d %s</span>"\n                 % (info[3], len(rows),\n                    "county" if len(rows) == 1 else "counties"))\n        H.append(ui.detail(summ, "".join(body), right,\n                           open_=grade in ("D", "F")))\n\n    weak = sum(len(groups.get(g, [])) for g in ("D", "F"))\n    if weak:\n        H.append("<p class=\'hint\'><b>%d counties are graded D or F.</b> "\n                 "Their risk scores come from the EMS and ARIES baseline "\n                 "rather than from anything we observed, so a quiet feed "\n                 "there means low observation, not low risk. The D and F "\n                 "bands are expanded above by default for that "\n                 "reason.</p>" % weak)\n    return "".join(H)\n\n\n# ---------------------------------------------------------------------------\n# The sheet\n# ---------------------------------------------------------------------------\n\ndef ad_ops_html(scores: pd.DataFrame, shares: pd.DataFrame,\n                mix: pd.DataFrame, parts: pd.DataFrame,\n                badges: dict, hours: int, prev: dict,\n                coverage: dict | None = None,\n                hotspots: list | None = None,\n                segments: list | None = None,\n                spillover: bool = False,\n                degraded: str | None = None,\n                insights: dict | None = None,\n                profile: dict | None = None\n                ) -> tuple:\n    """Build output/ad_ops.html. Returns (html, new_snapshot_or_None).\n\n    prev is the last stored snapshot ({\'date\': iso, \'shares\': {county:\n    share}}); a new snapshot is returned only when prev is absent or\n    older than ADOPS_SNAPSHOT_DAYS (rolling weekly comparison)."""\n    now = config.local_now()\n    tot = float(scores["risk_score"].sum()) or 1.0\n    cur_shares = {str(r["county"]): float(r["risk_score"]) / tot\n                  for _, r in scores.iterrows()}\n\n    # Watch list vs last snapshot\n    prev_shares = (prev or {}).get("shares") or {}\n    prev_date = str((prev or {}).get("date") or "")[:10]\n    movers_up, movers_dn = [], []\n    if prev_shares:\n        deltas = [(c, (cur_shares.get(c, 0.0) - float(p)) * 100)\n                  for c, p in prev_shares.items()]\n        deltas += [(c, cur_shares[c] * 100) for c in cur_shares\n                   if c not in prev_shares]\n        deltas = [d for d in deltas if abs(d[1]) >= ADOPS_MIN_MOVE_PP]\n        deltas.sort(key=lambda x: -x[1])\n        movers_up = deltas[:4]\n        movers_dn = sorted([d for d in deltas if d[1] < 0],\n                           key=lambda x: x[1])[:4]\n\n    snap = None\n    age_ok = False\n    if prev and prev.get("date"):\n        try:\n            age_ok = (now - _dt.datetime.fromisoformat(\n                prev["date"])).days < ADOPS_SNAPSHOT_DAYS\n        except Exception:  # noqa: BLE001\n            age_ok = False\n    if not age_ok:\n        snap = {"date": now.isoformat(timespec="seconds"),\n                "shares": {c: round(s, 5) for c, s in cur_shares.items()}}\n\n    H = [ui.head("Ad Ops Sheet", "ops"),\n         ui.tabs("ad_ops.html"),\n         ui.open_wrap(),\n         ui.masthead(\n             "Internal · Ad Operations",\n             "Where the budget should sit this week",\n             "County risk translated into spend, bids, and keyword lean — "\n             "with the confidence attached to each, so nobody moves money "\n             "on a signal we cannot actually see.",\n             "Generated " + now.strftime("%a %b %d, %Y %H:%M")\n             + " Indiana time  ·  %d-hour risk horizon" % hours)]\n\n    if degraded:\n        H.append("<div class=\'note hold\'><b>Degraded mode.</b> The 511 "\n                 "live feed has been silent since %s. Live-incident "\n                 "signals are unreliable right now — freeze automated "\n                 "spend changes and run on the baseline until feeds "\n                 "recover.</div>"\n                 % _esc(str(degraded)[:16].replace("T", " ")))\n\n    top = scores.head(1)\n    H.append(ui.figs([\n        ("%d" % len(scores), "Counties scored",\n         "statewide, every build"),\n        (_metro_label(shares.iloc[0]["metro"]) if len(shares) else "—",\n         "Largest share",\n         "%.0f%% of budget" % (float(shares.iloc[0]["blended_share"]) * 100)\n         if len(shares) else ""),\n        (str(top.iloc[0]["county"]) if len(top) else "—",\n         "Top county by risk",\n         "risk %.0f" % float(top.iloc[0]["risk_score"]) if len(top) else ""),\n        ("%d" % len(hotspots or []), "Street-level hotspots",\n         "%d corridors" % len(segments or [])),\n    ]))\n\n    # 1. Budget split\n    H.append(ui.h2("1", "Metro budget split this week"))\n    H.append("<div class=\'tbl-scroll\'><table><tr><th>Metro</th>"\n             "<th class=\'num\'>Spend share</th><th>vs static plan</th>"\n             "<th>What\'s driving it (top counties)</th></tr>")\n    for _, r in shares.iterrows():\n        shift = float(r["shift_vs_static"])\n        arrow = ("<span class=\'chip bad\'>&#9650; +%.1f pp</span>"\n                 % (shift * 100) if shift > 0.0005 else\n                 "<span class=\'chip on\'>&#9660; %.1f pp</span>"\n                 % (shift * 100) if shift < -0.0005 else\n                 "<span class=\'chip\'>flat</span>")\n        H.append("<tr><td><b>%s</b></td><td class=\'num\'>%.0f%%</td>"\n                 "<td>%s</td><td><span class=\'small\'>%s</span></td></tr>"\n                 % (_esc(_metro_label(r["metro"])),\n                    float(r["blended_share"]) * 100, arrow,\n                    _esc(_metro_why(scores, r["metro"]))))\n    H.append("</table></div>")\n    H.append("<p class=\'hint\'>Shares blend the static Phase 2 plan with "\n             "live county risk (at most %.0f%% dynamic shift).%s</p>"\n             % (config.DYNAMIC_WEIGHT * 100,\n                (" County risk credits %.0f%% of each collision\'s weight "\n                 "to commuters\' home counties (Census LODES), so "\n                 "pass-through counties share the exposure."\n                 % (config.SPILLOVER_FRAC * 100)) if spillover else ""))\n\n    # 2. When to bid up\n    H.append(ui.h2("2", "When to bid up (next %dh)" % hours))\n    H.append("<div class=\'tbl-scroll\'><table><tr><th>Metro</th>"\n             "<th>Raise bids during</th></tr>")\n    for m in shares["metro"]:\n        rng = _daypart_ranges(parts, m)\n        if rng:\n            H.append("<tr><td><b>%s</b></td><td><span class=\'small\'>%s"\n                     "</span></td></tr>"\n                     % (_esc(_metro_label(m)), _esc(" · ".join(rng))))\n    H.append("</table></div><p class=\'hint\'>Hours above the metro\'s "\n             "75th-percentile risk; suggested bid adjustment in "\n             "parentheses.</p>")\n\n    # 3. Keyword lean\n    H.append(ui.h2("3", "Keyword cluster lean"))\n    H.append("<div class=\'tbl-scroll\'><table><tr><th>Metro</th>"\n             "<th>Lead clusters (share of mix · est. CPC)</th></tr>")\n    for m, g in mix.groupby("metro", sort=False):\n        cells = " · ".join("%s (%.0f%% · $%.2f)" % (\n            row["cluster"], float(row["mix"]) * 100, float(row["est_cpc"]))\n            for _, row in g.head(3).iterrows())\n        H.append("<tr><td><b>%s</b></td><td><span class=\'small\'>%s</span>"\n                 "</td></tr>" % (_esc(_metro_label(m)), _esc(cells)))\n    H.append("</table></div>")\n\n    # 4. Vehicle-type counties\n    truck = (badges or {}).get("truck") or {}\n    if truck:\n        H.append(ui.h2("4", "Truck-tilted counties"))\n        H.append("<div class=\'card\'><ul>")\n        for c in sorted(truck):\n            H.append("<li>&#128667; <b>%s</b> — %s. Lean on "\n                     "truck-collision keywords here.</li>"\n                     % (_esc(c), _esc(truck[c])))\n        H.append("</ul></div>")\n\n    # 5. Watch list\n    H.append(ui.h2("5", "Watch list — biggest movers"))\n    if prev_shares:\n        H.append("<p class=\'small\'>Change in share of statewide risk "\n                 "against the snapshot of %s, in percentage points.</p>"\n                 % _esc(prev_date))\n        rows = [(c, d) for c, d in movers_up if d > 0] + list(movers_dn)\n        if rows:\n            H.append("<div class=\'card\'>" + ui.stripe_rows(\n                [("%s %+.2f pp" % (c, d), "", abs(d) * 10) for c, d in rows],\n                maxw=200) + "</div>")\n        else:\n            H.append("<div class=\'card\'><p>No county moved more than "\n                     "%.2f pp — steady week.</p></div>" % ADOPS_MIN_MOVE_PP)\n    else:\n        H.append("<p class=\'small\'>First snapshot recorded — movers "\n                 "appear here from next week.</p>")\n\n    # 6. Hot segments\n    if hotspots:\n        H.append(ui.h2("6", "Hot spots (street level)"))\n        H.append("<div class=\'tbl-scroll\'><table><tr><th>Where</th>"\n                 "<th>County</th><th class=\'num\'>Collisions</th>"\n                 "<th class=\'num\'>vs class typical</th>"\n                 "<th class=\'num\'>Truck</th><th>Span</th></tr>")\n        for s in hotspots[:8]:\n            H.append("<tr><td>%s <span class=\'small\'>(%.4f, %.4f)</span>"\n                     "</td><td>%s</td><td class=\'num\'><b>%d</b></td>"\n                     "<td class=\'num\'>%s</td><td class=\'num\'>%s</td>"\n                     "<td><span class=\'small\'>%s → %s</span></td></tr>"\n                     % (_esc(s.get("road") or "unnamed segment"),\n                        s["lat"], s["lon"], _esc(s.get("county", "?")),\n                        s["n"],\n                        ("%.1f× (%s)" % (s["rel"], _esc(s.get("cls", "")))\n                         if s.get("rel") else "—"),\n                        s.get("truck") or "—",\n                        _esc(s.get("first", "?")), _esc(s.get("last", "?"))))\n        H.append("</table></div><p class=\'hint\'>Cells with %d+ archived "\n                 "collisions within ~400 m. Use for geography-level "\n                 "insight such as corridor keywords — never for "\n                 "incident-specific creative.</p>" % config.HOTSPOT_MIN_N)\n\n    if segments:\n        H.append(ui.h2("6b", "Risky corridors (multi-km)"))\n        H.append("<div class=\'tbl-scroll\'><table><tr><th>Road</th>"\n                 "<th>Counties</th><th class=\'num\'>Collisions</th>"\n                 "<th class=\'num\'>Days</th><th class=\'num\'>Length</th>"\n                 "<th class=\'num\'>Density</th><th class=\'num\'>Truck</th>"\n                 "<th>Span</th></tr>")\n        for s in segments[:8]:\n            H.append("<tr><td><b>%s</b> <span class=\'small\'>(%s)</span>"\n                     "</td><td>%s</td><td class=\'num\'><b>%d</b></td>"\n                     "<td class=\'num\'>%d</td><td class=\'num\'>%.1f km</td>"\n                     "<td class=\'num\'>%.2f/km</td><td class=\'num\'>%s</td>"\n                     "<td><span class=\'small\'>%s → %s</span></td></tr>"\n                     % (_esc(s["road"]), _esc(s.get("cls", "")),\n                        _esc(s.get("county", "?")), s["n"], s["days"],\n                        s["km"], s["per_km"], s.get("truck") or "—",\n                        _esc(s["first"]), _esc(s["last"])))\n        H.append("</table></div><p class=\'hint\'>Stretches where collisions "\n                 "chain along one road, each within %.0f km of the next, "\n                 "over %.0f km or more — contentious corridors that no "\n                 "single 400 m cell captures. Drawn as dashed lines on the "\n                 "live map, and the main source of candidates for the "\n                 "public reports.</p>"\n                 % (config.SEGMENT_LINK_KM, config.SEGMENT_MIN_KM))\n\n    # 7. Coverage — all counties, expandable\n    H.append(_coverage_section(coverage or {}, scores, degraded))\n\n    # 8. Archive insights\n    if insights:\n        H.append(ui.h2("8", "Archive insights"))\n        H.append("<p class=\'lede\'>What our own accumulated collision "\n                 "record shows — independent of the risk model, and the "\n                 "only part of this sheet built purely from things we "\n                 "observed rather than predicted.</p>")\n        H.append(ui.figs([\n            ("%d" % insights["total"], "Collisions archived",\n             "since %s" % insights["since"]),\n            ("%.0f%%" % (insights["truck_share"] * 100), "Truck-involved",\n             "statewide official average is ~7%"),\n            ("%s" % (insights["top_day"][0][:3] if insights["top_day"]\n                     else "—"), "Heaviest day",\n             "%d of %d located" % (insights["top_day"][1], insights["n"])\n             if insights["top_day"] else ""),\n            ("%02d:00" % insights["top_hours"][0][0]\n             if insights["top_hours"] else "—", "Busiest hour",\n             "%d collisions" % insights["top_hours"][0][1]\n             if insights["top_hours"] else ""),\n        ]))\n        if profile and profile.get("hours"):\n            H.append("<figure>" + ui.hour_chart(profile["hours"])\n                     + "<figcaption><b>Collisions by hour of day</b>, "\n                       "Indiana local time, across the whole windowed "\n                       "archive. Shaded bands are the commute peaks. Read "\n                       "this against section 2 — where the two disagree, "\n                       "the model is leaning on weather or live events "\n                       "rather than on observed history."\n                       "</figcaption></figure>")\n        if profile and profile.get("days"):\n            H.append("<div class=\'card\'><h3>By day of week</h3>"\n                     + ui.day_chart(profile["days"])\n                     + "<p class=\'hint\'>One dash per recorded collision."\n                       "</p></div>")\n        if profile and profile.get("classes"):\n            pal = {"interstate": "#1B3A6B", "US highway": "#14603C",\n                   "state road": "#8C3A12", "local road": "#6E7880",\n                   "unclassified": "#B7BFB6"}\n            H.append("<div class=\'card\'><h3>By class of road</h3>"\n                     + ui.prop_bar([(k, v, pal.get(k, "#6E7880"))\n                                    for k, v in sorted(\n                                        profile["classes"].items(),\n                                        key=lambda kv: -kv[1])])\n                     + "<p class=\'hint\'>Feed coverage is highway-tilted, "\n                       "so the local-road share is an undercount. Keyword "\n                       "lean should not be derived from this split "\n                       "alone.</p></div>")\n        if insights.get("repeat_roads"):\n            H.append("<div class=\'card\'><h3>Roads appearing "\n                     "repeatedly</h3>"\n                     + ui.stripe_rows([(r, "", c) for r, c\n                                       in insights["repeat_roads"]])\n                     + "<p class=\'hint\'>Includes roads below the hotspot "\n                       "bar. Useful for corridor keyword themes.</p></div>")\n        if insights["total"] < config.LEDGER_MIN_TOTAL:\n            H.append("<div class=\'note\'><b>Small sample.</b> The archive "\n                     "is below the %d-collision threshold at which county "\n                     "baselines start adjusting. Read this section as "\n                     "early signal, not conclusion.</div>"\n                     % config.LEDGER_MIN_TOTAL)\n        H.append("<p class=\'hint\'>Hour and day patterns use the time each "\n                 "collision first reached our feeds, in Indiana local "\n                 "time — slightly later than the collision itself, and "\n                 "later still on roads with sparse detection.</p>")\n\n    H.append(ui.foot(\n        "<b>Compliance (Ind. Prof. Cond. R. 7.1&#8211;7.3).</b> All "\n        "targeting stays at the geography and road-condition level — "\n        "county budgets, dayparts, and keyword themes only. No "\n        "incident-specific ad creative, no retargeting tied to a "\n        "collision, no victim identification."))\n    H.append(ui.close())\n    return "\\n".join(H), snap\n'
_FILES['ledger.py'] = '"""\nLong-term crash ledger (learned county baseline adjustment).\n\nEvery crash our feeds record — from any full build or 5-minute poll — is\ntallied by county and month under the reserved "_ledger" key inside\nincident_history.json (the file the workflow already commits, so nothing\nnew to configure and the tally never fades, unlike trailing memory).\n\nOnce the statewide sample passes LEDGER_MIN_TOTAL, each county\'s observed\ncrash share is compared with its EMS-baseline share and turned into a\ngentle empirical-Bayes multiplier:\n\n    expected_c = total_observed * baseline_share_c\n    factor_c   = clip((observed_c + K) / (expected_c + K), CAP_LO, CAP_HI)\n\nK (LEDGER_PRIOR_K) shrinks small samples toward 1.0 so a rural county\nwith 3 observed crashes isn\'t judged on noise. The caps are deliberately\ntight: the feeds over-represent INDOT highways and metro roads (511\ncovers only state-managed routes; TomTom probe density is urban-tilted),\nso the EMS baseline stays the anchor and this only nudges it.\n"""\nfrom __future__ import annotations\n\nimport datetime as dt\n\nimport config\n\n\ndef _ledger(hist: dict) -> dict:\n    led = hist.get("_ledger")\n    if not isinstance(led, dict) or "months" not in led:\n        led = {"since": config.local_now().isoformat(timespec="seconds"),\n               "months": {}}\n        hist["_ledger"] = led\n    return led\n\n\ndef is_truck(text: str) -> bool:\n    t = f" {str(text).lower()} "\n    return any(k in t for k in config.TRUCK_KEYWORDS)\n\n\ndef _cell(bucket: dict, county: str) -> dict:\n    """County cell within a month bucket; migrates the original plain-int\n    format ({county: 3}) to {county: {"n": 3, "truck": 0}} on touch."""\n    cur = bucket.get(county)\n    if isinstance(cur, dict):\n        return cur\n    cell = {"n": int(cur or 0), "truck": 0}\n    bucket[county] = cell\n    return cell\n\n\ndef record(hist: dict, new_crash_entries: list[dict],\n           now: dt.datetime | None = None) -> None:\n    """Tally newly-first-seen crashes into hist["_ledger"] (in place),\n    tracking truck involvement from the event text."""\n    led = _ledger(hist)\n    if not new_crash_entries:\n        _reconcile_truck(hist, led)\n        return\n    month = (now or config.local_now()).strftime("%Y-%m")\n    bucket = led["months"].setdefault(month, {})\n    for e in new_crash_entries:\n        c = e.get("county")\n        if not c:\n            continue\n        cell = _cell(bucket, c)\n        cell["n"] += 1\n        tk = is_truck(f\'{e.get("type", "")} {e.get("desc", "")}\')\n        if tk:\n            cell["truck"] += 1\n        # Archive the exact location too (street-level hotspot analysis):\n        # [lat, lon, first_seen, truck 0/1, road, county], capped FIFO.\n        if e.get("lat") is not None and e.get("lon") is not None:\n            pts = led.setdefault("points", [])\n            pts.append([round(float(e["lat"]), 4), round(float(e["lon"]), 4),\n                        str(e.get("first_seen", ""))[:16], 1 if tk else 0,\n                        str(e.get("road") or "")[:48], c])\n            if len(pts) > config.LEDGER_POINTS_MAX:\n                del pts[: len(pts) - config.LEDGER_POINTS_MAX]\n    _reconcile_truck(hist, led)\n\n\ndef _reconcile_truck(hist: dict, led: dict) -> None:\n    """Retro-upgrade archived points using the (refreshed) event text in\n    trailing memory. A crash archived from a bare first report can turn\n    out to be truck-involved once the feed adds detail; match points back\n    to their memory entry by (lat, lon, first_seen) and upgrade the truck\n    flag (0 -> 1 only, so the county tally is bumped exactly once) and any\n    late-arriving road name. Events already pruned from memory are simply\n    left as archived — the window for enrichment is the ~2-day trail."""\n    pts = led.get("points") or []\n    if not pts:\n        return\n    idx = {}\n    for k, e in hist.items():\n        if k.startswith("_") or not isinstance(e, dict):\n            continue\n        if e.get("lat") is None or e.get("lon") is None:\n            continue\n        idx[(round(float(e["lat"]), 4), round(float(e["lon"]), 4),\n             str(e.get("first_seen", ""))[:16])] = e\n    for p in pts:\n        e = idx.get((p[0], p[1], p[2]))\n        if not e:\n            continue\n        if not p[3] and is_truck(f\'{e.get("type", "")} {e.get("desc", "")}\'):\n            p[3] = 1\n            cell = _cell(led["months"].setdefault(p[2][:7], {}), p[5])\n            cell["truck"] += 1\n        if (not p[4] or p[4] == "None") and e.get("road"):\n            p[4] = str(e["road"])[:48]\n\n\ndef totals(hist: dict) -> tuple[dict, int, str]:\n    led = _ledger(hist)\n    obs: dict[str, float] = {}\n    for bucket in led["months"].values():\n        for c, n in bucket.items():\n            obs[c] = obs.get(c, 0) + (n["n"] if isinstance(n, dict) else n)\n    return obs, int(sum(obs.values())), led["since"]\n\n\ndef truck_stats(hist: dict) -> dict[str, tuple[int, int]]:\n    """{county: (truck_involved, total)} across the whole archive."""\n    led = _ledger(hist)\n    out: dict[str, list[int]] = {}\n    for bucket in led["months"].values():\n        for c, n in bucket.items():\n            t = n["truck"] if isinstance(n, dict) else 0\n            tot = n["n"] if isinstance(n, dict) else n\n            cur = out.setdefault(c, [0, 0])\n            cur[0] += t\n            cur[1] += tot\n    return {c: (v[0], v[1]) for c, v in out.items()}\n\n\ndef load_baseline() -> dict[str, tuple[int, int]]:\n    """{county: (truck, total)} from the official background table\n    (config.BASELINE_CRASH_CSV, from the ICJI/IU-PPI ARIES county\n    profiles). Missing file or zero-total rows are skipped."""\n    import csv\n    import os\n    out = {}\n    if not os.path.exists(config.BASELINE_CRASH_CSV):\n        return out\n    try:\n        with open(config.BASELINE_CRASH_CSV) as f:\n            for row in csv.DictReader(f):\n                try:\n                    n = int(float(row.get("total_crashes") or 0))\n                    raw_t = (row.get("truck_crashes") or "").strip()\n                    t = int(float(raw_t)) if raw_t else None  # blank=unknown\n                except ValueError:\n                    continue\n                if n > 0 and row.get("county"):\n                    out[row["county"].strip()] = (t, n)\n    except Exception as e:  # noqa: BLE001\n        print(f"[warn] baseline crash table unreadable: {e}")\n    return out\n\n\ndef truck_badges(hist: dict,\n                 baseline: dict[str, tuple[int, int]] | None = None\n                 ) -> dict[str, str]:\n    """{county: reason} for counties notably truck-crash-prone, judged on\n    official background data (when the baseline table is present) blended\n    with everything the live feeds have archived."""\n    baseline = baseline or {}\n    feed = truck_stats(hist)\n    # First pass: blended per-county counts + the statewide truck share\n    # from the SAME data, so every county is judged against one yardstick\n    # (relative comparison; a fixed threshold flickered day to day).\n    blended = {}\n    sw_t = sw_n = 0\n    for c in set(feed) | set(baseline):\n        ft, fn = feed.get(c, (0, 0))\n        bt, bn = baseline.get(c, (None, 0))\n        if bt is None:  # totals known but truck split unknown: badge on\n            bt = bn = 0  # feed evidence alone, don\'t dilute the share\n        t, n = ft + bt, fn + bn\n        blended[c] = (t, n, bn, fn)\n        sw_t += t\n        sw_n += n\n    statewide = (sw_t / sw_n) if sw_n else 0.0\n    thr = max(config.TRUCK_BADGE_REL * statewide, config.TRUCK_BADGE_FLOOR)\n    out = {}\n    for c, (t, n, bn, fn) in blended.items():\n        if n >= config.TRUCK_BADGE_MIN_N and n and t / n >= thr:\n            src = ("official baseline + our archive" if bn and fn\n                   else "official baseline" if bn else "our archive")\n            out[c] = (f"{t} of {n} crashes truck-involved — "\n                      f"{t / n:.0%} vs {statewide:.0%} statewide ({src})")\n    return out\n\n\ndef official_factors(baseline: dict[str, tuple[int | None, int]],\n                     ems_shares: dict[str, float]) -> dict[str, float]:\n    """Background-baseline county adjustment from official ARIES totals:\n    each county\'s share of officially reported crashes vs its EMS-injury\n    share, square-rooted (official totals include property-damage-only\n    crashes, so they get half weight against the injury-anchored EMS\n    baseline) and capped. Applied only when the table covers nearly the\n    whole state, so partial tables can\'t skew relative shares."""\n    if len(baseline) < 80:\n        return {}\n    total = sum(n for _t, n in baseline.values())\n    if total <= 0:\n        return {}\n    lo, hi = config.LEDGER_CAP\n    out = {}\n    for c, share in ems_shares.items():\n        if c not in baseline or share <= 0:\n            continue\n        ratio = (baseline[c][1] / total) / share\n        out[c] = round(min(max(ratio ** 0.5, lo), hi), 3)\n    return out\n\n\ndef factors(hist: dict, baseline_shares: dict[str, float],\n            spill: dict | None = None,\n            coverage: dict | None = None) -> tuple[dict[str, float], dict]:\n    """({county: multiplier}, meta). Factors stay empty (no adjustment)\n    while the statewide sample is below LEDGER_MIN_TOTAL. When a commuter\n    spill matrix is given, observed crash credit is partially spread to\n    home counties before the empirical-Bayes ratio.\n\n    Two fairness corrections (v9.7):\n    - COVERAGE: a county our feeds over-observe (capture ratio above its\n      size-tier\'s median; the same \'rel\' the coverage grades use) has its\n      observed count deflated by that ratio, and vice versa — so factors\n      measure crash propensity, not feed instrumentation density.\n    - RECENTRING: factors are divided by their share-weighted mean before\n      capping, so the field is strictly RELATIVE between counties\n      (mean 1.0). Archive growth can shift counties against each other\n      but can never push the whole state redder."""\n    obs, total, since = totals(hist)\n    if spill:\n        obs = apply_spill(obs, spill)\n    meta = {"total": total, "since": since}\n    if total < config.LEDGER_MIN_TOTAL:\n        return {}, meta\n    if coverage:\n        adj = {}\n        for county, o in obs.items():\n            rel = (coverage.get(county) or {}).get("rel")\n            if rel:  # graded county: undo its capture advantage/deficit\n                adj[county] = o / min(max(float(rel), 0.25), 4.0)\n            else:    # learning / small sample: leave as observed\n                adj[county] = o\n        obs = adj\n        meta["coverage_adjusted"] = True\n    k = config.LEDGER_PRIOR_K\n    lo, hi = config.LEDGER_CAP\n    raw = {}\n    for county, share in baseline_shares.items():\n        expected = total * share\n        raw[county] = (obs.get(county, 0) + k) / (expected + k)\n    wmean = sum(raw[c] * baseline_shares[c] for c in raw)\n    wtot = sum(baseline_shares[c] for c in raw)\n    wmean = (wmean / wtot) if wtot else 1.0\n    out = {c: round(min(max(f / (wmean or 1.0), lo), hi), 3)\n           for c, f in raw.items()}\n    return out, meta\n\n\ndef road_class(road) -> str:\n    """Coarse facility class from the road name — the archive\'s own\n    exposure proxy until real AADT data is integrated (ARIES era)."""\n    r = str(road or "").strip().upper()\n    if r.startswith(("I-", "I ")):\n        return "interstate"\n    if r.startswith(("US-", "US ")):\n        return "US highway"\n    if r.startswith(("SR-", "SR ", "IN-", "STATE ROAD")):\n        return "state road"\n    return "local road" if r else "unclassified"\n\n\ndef class_relative(cells: list[dict]) -> None:\n    """Annotate each cell dict (needs \'n\' and \'road\') in place with:\n    cls  — its road class,\n    rel  — n as a multiple of the MEDIAN repeat-crash (n>=2) cell of the\n           same class in this batch (falls back to the all-class median),\n    None when fewer than 3 comparison cells exist (too little context to\n    make a multiple honest). Comparing within class keeps the busiest-\n    interchange objection at bay: interstates are judged against\n    interstates, county roads against county roads."""\n    for c in cells:\n        c["cls"] = road_class(c.get("road"))\n    med = {}\n    all_rep = sorted(c["n"] for c in cells if c["n"] >= 2)\n    for cls in {c["cls"] for c in cells}:\n        rep_cells = sorted(c["n"] for c in cells\n                           if c["cls"] == cls and c["n"] >= 2)\n        base = rep_cells if len(rep_cells) >= 3 else all_rep\n        med[cls] = base[len(base) // 2] if len(base) >= 3 else None\n    for c in cells:\n        m = med.get(c["cls"])\n        c["rel"] = round(c["n"] / m, 1) if m else None\n\n\ndef _km(a, b) -> float:\n    """Equirectangular distance in km — fine at Indiana scale."""\n    import math\n    x = math.radians(b[1] - a[1]) * math.cos(math.radians((a[0] + b[0]) / 2))\n    y = math.radians(b[0] - a[0])\n    return 6371.0 * (x * x + y * y) ** 0.5\n\n\ndef segments(hist: dict) -> list[dict]:\n    """Corridor-level risk: windowed crash points grouped by primary road\n    name, single-linkage chained (gap <= SEGMENT_LINK_KM), kept when the\n    chain has >= SEGMENT_MIN_N crashes over >= SEGMENT_MIN_KM. Returns\n    dicts with an ordered \'path\' of [lat, lon] through the actual crash\n    coordinates (no road geometry data exists in the pipeline — the\n    polyline approximates the corridor by connecting its crashes)."""\n    pts = _ledger(hist).get("points") or []\n    cutoff = (config.local_now()\n              - dt.timedelta(days=config.HOTSPOT_WINDOW_D)\n              ).isoformat(timespec="minutes")\n    by_road: dict[str, list] = {}\n    for p in pts:\n        if len(p) < 6 or str(p[2] or "") < cutoff:\n            continue\n        road = str(p[4] or "").split(" / ")[0].strip()\n        if not road or road.lower() == "none":\n            continue\n        try:\n            by_road.setdefault(road, []).append(\n                (float(p[0]), float(p[1]), str(p[2]), int(p[3] or 0),\n                 str(p[5] or "")))\n        except (TypeError, ValueError):\n            continue\n    out = []\n    for road, rp in by_road.items():\n        if len(rp) < config.SEGMENT_MIN_N:\n            continue\n        # single-linkage clustering (n is small; O(n^2) is fine)\n        parent = list(range(len(rp)))\n\n        def find(i):\n            while parent[i] != i:\n                parent[i] = parent[parent[i]]\n                i = parent[i]\n            return i\n\n        for i in range(len(rp)):\n            for j in range(i + 1, len(rp)):\n                if _km(rp[i][:2], rp[j][:2]) <= config.SEGMENT_LINK_KM:\n                    parent[find(i)] = find(j)\n        groups: dict[int, list] = {}\n        for i in range(len(rp)):\n            groups.setdefault(find(i), []).append(rp[i])\n        for g in groups.values():\n            if len(g) < config.SEGMENT_MIN_N:\n                continue\n            # corridor endpoints = the most distant pair; span = that gap\n            best, ends = 0.0, (g[0], g[0])\n            for i in range(len(g)):\n                for j in range(i + 1, len(g)):\n                    d = _km(g[i][:2], g[j][:2])\n                    if d > best:\n                        best, ends = d, (g[i], g[j])\n            if best < config.SEGMENT_MIN_KM:\n                continue  # dense but short: hotspot territory\n            a = ends[0]\n            axis = (ends[1][0] - a[0], ends[1][1] - a[1])\n            g.sort(key=lambda p: (p[0] - a[0]) * axis[0]\n                   + (p[1] - a[1]) * axis[1])\n            days = {p[2][:10] for p in g}\n            counties = {}\n            for p in g:\n                if p[4]:\n                    counties[p[4]] = counties.get(p[4], 0) + 1\n            out.append({\n                "road": road, "cls": road_class(road),\n                "n": len(g), "days": len(days),\n                "truck": sum(p[3] for p in g),\n                "km": round(best, 1),\n                "per_km": round(len(g) / best, 2),\n                "county": " / ".join(sorted(counties, key=counties.get,\n                                            reverse=True)[:2]),\n                "first": min(p[2] for p in g)[:10],\n                "last": max(p[2] for p in g)[:10],\n                "path": [[round(p[0], 4), round(p[1], 4)] for p in g],\n            })\n    out.sort(key=lambda s: (-s["per_km"], -s["n"]))\n    return out[:config.SEGMENT_MAX]\n\n\ndef hotspots(hist: dict) -> list[dict]:\n    """Cluster archived crash locations on a ~400 m grid; cells with\n    >= HOTSPOT_MIN_N crashes WITHIN THE LAST HOTSPOT_WINDOW_D DAYS become\n    hotspot pins (see config: lifetime counts would saturate)."""\n    pts = _ledger(hist).get("points") or []\n    cutoff = (config.local_now()\n              - dt.timedelta(days=config.HOTSPOT_WINDOW_D)\n              ).isoformat(timespec="minutes")\n    pts = [p for p in pts\n           if len(p) > 2 and str(p[2] or "") >= cutoff]\n    cell = config.HOTSPOT_CELL_DEG\n    grid: dict[tuple, dict] = {}\n    for p in pts:\n        try:\n            lat, lon, ts, tk, road, cty = (list(p) + ["", 0, "", ""])[:6]\n            lat, lon = float(lat), float(lon)\n        except (TypeError, ValueError):\n            continue\n        key = (round(lat / cell), round(lon / cell))\n        g = grid.setdefault(key, {"n": 0, "truck": 0, "lat": 0.0, "lon": 0.0,\n                                  "roads": {}, "first": "", "last": "",\n                                  "county": ""})\n        g["n"] += 1\n        g["truck"] += int(tk or 0)\n        g["lat"] += lat\n        g["lon"] += lon\n        if road:\n            g["roads"][road] = g["roads"].get(road, 0) + 1\n        if ts:\n            g["first"] = min(g["first"] or ts, ts)\n            g["last"] = max(g["last"], ts)\n        if cty:\n            g["county"] = cty\n    # class-relative context is computed over ALL windowed cells (even\n    # sub-threshold ones) so the medians describe the real landscape,\n    # then only threshold cells become pins.\n    all_cells = []\n    for g in grid.values():\n        road = " / ".join(sorted(g["roads"], key=g["roads"].get,\n                                 reverse=True)[:2])\n        all_cells.append({"lat": round(g["lat"] / g["n"], 4),\n                          "lon": round(g["lon"] / g["n"], 4),\n                          "n": g["n"], "truck": g["truck"], "road": road,\n                          "county": g["county"], "first": g["first"][:10],\n                          "last": g["last"][:10]})\n    class_relative(all_cells)\n    out = [c for c in all_cells if c["n"] >= config.HOTSPOT_MIN_N]\n    # rank by relative excess first (how abnormal for its road class),\n    # then raw count; cells without enough context rank by count alone\n    return sorted(out, key=lambda x: (-(x.get("rel") or 1.0), -x["n"]))\n\n\ndef insights(hist: dict) -> dict | None:\n    """Plain-language patterns from the crash archive for the ad ops\n    sheet: busiest hours (local time), heaviest weekday, truck share,\n    and roads that keep reappearing (even below the hotspot bar).\n    Returns None while the archive is nearly empty."""\n    pts = _ledger(hist).get("points") or []\n    if len(pts) < 5:\n        return None\n    hours: dict[int, int] = {}\n    days: dict[str, int] = {}\n    roads: dict[str, int] = {}\n    truck = 0\n    for p in pts:\n        try:\n            _lat, _lon, ts, tk, road, _cty = (list(p) + ["", 0, "", ""])[:6]\n        except (TypeError, ValueError):\n            continue\n        truck += int(tk or 0)\n        try:\n            t = dt.datetime.fromisoformat(str(ts))\n            hours[t.hour] = hours.get(t.hour, 0) + 1\n            days[t.strftime("%A")] = days.get(t.strftime("%A"), 0) + 1\n        except (TypeError, ValueError):\n            pass\n        if road:\n            roads[str(road)] = roads.get(str(road), 0) + 1\n    _obs, total, since = totals(hist)\n    rep = [(r, c) for r, c in sorted(roads.items(), key=lambda x: -x[1])\n           if c >= 2][:5]\n    return {"n": len(pts), "total": total, "since": str(since)[:10],\n            "truck_share": truck / max(len(pts), 1),\n            "top_hours": sorted(hours.items(), key=lambda x: -x[1])[:3],\n            "top_day": (max(days.items(), key=lambda x: x[1])\n                        if days else None),\n            "repeat_roads": rep}\n\n\ndef apply_spill(values: dict, matrix: dict) -> dict:\n    """Redistribute a fraction of each county\'s evidence to commuter home\n    counties. matrix = {work county: [(home county, fraction)]}; the\n    fractions already include SPILLOVER_FRAC, so totals are conserved."""\n    out = {c: 0.0 for c in values}\n    for c, v in values.items():\n        v = float(v)\n        kept = v\n        for home, frac in (matrix.get(c) or []):\n            amt = v * float(frac)\n            out[home] = out.get(home, 0.0) + amt\n            kept -= amt\n        out[c] = out.get(c, 0.0) + kept\n    return {c: round(v, 4) for c, v in out.items()}\n\n\ndef capture_trend(hist: dict, expected_shares: dict[str, float]\n                  ) -> dict[str, str]:\n    """Self-baseline drift: counties whose recent capture rate (last two\n    COMPLETE months) halved (\'falling\') or doubled (\'rising\') vs their own\n    earlier months. Catches feed changes without punishing counties for\n    being small — a county is only compared against itself here."""\n    months = _ledger(hist).get("months") or {}\n    cur = config.local_now().strftime("%Y-%m")\n    keys = sorted(k for k in months if k != cur)\n    if len(keys) < 3:\n        return {}\n\n    def agg(ks):\n        per, tot = {}, 0\n        for k in ks:\n            for c, n in months[k].items():\n                v = n["n"] if isinstance(n, dict) else int(n)\n                per[c] = per.get(c, 0) + v\n                tot += v\n        return per, tot\n\n    r_per, r_tot = agg(keys[-2:])\n    p_per, p_tot = agg(keys[:-2])\n    out = {}\n    for c, s in expected_shares.items():\n        er, ep = r_tot * float(s), p_tot * float(s)\n        if er < config.TREND_MIN_N or ep < config.TREND_MIN_N:\n            continue\n        rr = (r_per.get(c, 0) + 1) / (er + 1)\n        rp = (p_per.get(c, 0) + 1) / (ep + 1)\n        ratio = rr / max(rp, 1e-9)\n        if ratio <= 0.5 and p_per.get(c, 0) >= config.TREND_MIN_N:\n            out[c] = "falling"\n        elif ratio >= 2.0 and r_per.get(c, 0) >= config.TREND_MIN_N:\n            out[c] = "rising"\n    return out\n\n\ndef coverage(hist: dict, expected_shares: dict[str, float]\n             ) -> dict[str, dict]:\n    """Per-county feed-coverage grade, judged FAIRLY:\n    - counties are split into COVERAGE_TIERS size tiers by expected crash\n      volume, and each county\'s capture ratio (observed / expected) is\n      graded against the MEDIAN capture ratio of its own tier — small\n      rural counties are compared with other small counties (similar road\n      mix and probe density), not with Marion;\n    - counties whose expected crashes are below COVERAGE_MIN_EXPECTED get\n      \'small sample\' instead of a fake grade;\n    - a \'trend\' field (from capture_trend) flags drift against the\n      county\'s OWN history.\n    Grades: rel>=0.85 A, >=0.6 B, >=0.35 C, >=0.15 D, else F;\n    \'learning\' before LEDGER_MIN_TOTAL."""\n    obs, total, _since = totals(hist)\n    trends = capture_trend(hist, expected_shares)\n    out = {}\n    if total < config.LEDGER_MIN_TOTAL:\n        for c, s in expected_shares.items():\n            out[c] = {"grade": "learning", "rel": None,\n                      "obs": int(obs.get(c, 0)),\n                      "exp": round(total * float(s), 1),\n                      "trend": trends.get(c)}\n        return out\n    ranked = sorted(expected_shares.items(), key=lambda kv: -kv[1])\n    ntier = max(1, config.COVERAGE_TIERS)\n    size = max(1, (len(ranked) + ntier - 1) // ntier)\n    tiers, tier_of = [], {}\n    for i in range(0, len(ranked), size):\n        grp = [c for c, _ in ranked[i:i + size]]\n        tiers.append(grp)\n        for c in grp:\n            tier_of[c] = len(tiers) - 1\n    ratio = {c: (obs.get(c, 0) / (total * float(s))\n                 if total * float(s) > 0 else None)\n             for c, s in expected_shares.items()}\n    med = {}\n    for ti, grp in enumerate(tiers):\n        vals = sorted(ratio[c] for c in grp if ratio[c] is not None\n                      and total * float(expected_shares[c])\n                      >= config.COVERAGE_MIN_EXPECTED)\n        med[ti] = vals[len(vals) // 2] if vals else None\n    for c, s in expected_shares.items():\n        exp = total * float(s)\n        o = int(obs.get(c, 0))\n        tr = trends.get(c)\n        if exp < config.COVERAGE_MIN_EXPECTED:\n            out[c] = {"grade": "small sample", "rel": None, "obs": o,\n                      "exp": round(exp, 1), "trend": tr}\n            continue\n        base = med.get(tier_of.get(c))\n        base = base if base and base > 0 else 1.0\n        rel = (o / exp) / base\n        g = ("A" if rel >= 0.85 else "B" if rel >= 0.6 else\n             "C" if rel >= 0.35 else "D" if rel >= 0.15 else "F")\n        out[c] = {"grade": g, "rel": round(rel, 2), "obs": o,\n                  "exp": round(exp, 1), "peer": round(base, 2),\n                  "trend": tr}\n    return out\n'
_FILES['pubsafe.py'] = '"""\nPublic road-safety spinoff (v10): Road Safety Watch + Policymaker Hotspot\nAction Brief, generated as DRAFT HTML pages from the same crash archive\nthat feeds the internal map.\n\nWHAT CHANGED IN v10 — WHY THE PAGES USED TO READ AS "NOT ENOUGH DATA"\n---------------------------------------------------------------------\nv9 recognised exactly one shape of evidence: a ~400 m grid cell holding\n>= PUB_MIN_N crashes on >= PUB_MIN_DAYS distinct days. That is a very\nsmall target. Measured against a 550-crash archive, the points spread\nacross ~520 distinct cells and only FOUR cleared n>=3 — so the reports\nsat on the empty-state note while the archive was in fact substantial.\nThe archive was never the problem; the question being asked of it was.\n\nv10 asks for recurrence at the scale roads actually have it, in three\ntiers, all of which still require repetition across distinct days:\n\n  SPOT      ~400 m cell, >= PUB_MIN_N crashes on >= PUB_MIN_DAYS days.\n            The original gate, unchanged. Strongest evidence: an\n            intersection or interchange the crashes keep landing on.\n  CORRIDOR  a chain of crashes along ONE named road (ledger.segments),\n            >= PUB_CORRIDOR_MIN_N crashes over >= SEGMENT_MIN_KM on\n            >= PUB_CORRIDOR_MIN_DAYS days. Catches the several-km\n            stretch that is plainly contentious without any single cell\n            crossing the spot bar. This tier is what makes the reports\n            report at realistic sample sizes.\n  ROAD      a named road within one county carrying >= PUB_ROAD_MIN_N\n            crashes on >= PUB_ROAD_MIN_DAYS days, where the crashes are\n            too scattered to chain into a corridor. Weakest tier,\n            labelled as such, and never presented as a single location.\n\nA record\'s tier is stated on its face in both reports, so a reader can\nsee what kind of claim is being made. The tiers are mutually exclusive:\ncrashes already represented by a spot are not re-reported as a corridor\ncontaining that spot, and roads are only reported when neither stronger\ntier claimed them.\n\nEverything else about the protocol is unchanged:\n- ALL prose is deterministic template text (calm, caution-oriented; no\n  predictions, no cause claims, no victim detail, no legal call to\n  action), so the prohibited-language check is satisfied by\n  construction. Template VARIANTS are selected by a stable hash of the\n  location name, so the pages read less mechanically while remaining\n  byte-identical between runs on identical data.\n- Both pages are written as *_draft.html every full build. Publication\n  is a separate manual workflow step.\n- The public page shows road + county + aggregate pattern only. The\n  policymaker brief adds coordinates rounded to 3 decimals (~100 m) and\n  the evidence tables. Neither ever includes event-level descriptions.\n"""\nfrom __future__ import annotations\n\nimport datetime as _dt\nimport zlib as _zlib\n\nimport config\nimport ui\n\n_esc = ui.esc\n\n\ndef _pick(options: list, key: str):\n    """Deterministic variant choice — stable across runs for the same\n    location, so drafts don\'t churn, but varied across locations so the\n    report doesn\'t read like a mail merge."""\n    if not options:\n        return ""\n    h = _zlib.crc32(key.encode("utf-8", "replace"))\n    return options[h % len(options)]\n\n\ndef _cut() -> str:\n    return (config.local_now()\n            - _dt.timedelta(days=config.HOTSPOT_WINDOW_D)\n            ).isoformat(timespec="minutes")\n\n\ndef _points(hist) -> list:\n    """Windowed, well-formed crash points: [lat, lon, ts, truck, road, cty]."""\n    raw = (hist.get("_ledger") or {}).get("points") or []\n    cut = _cut()\n    out = []\n    for p in raw:\n        if not p or len(p) < 3 or str(p[2] or "") < cut:\n            continue\n        try:\n            lat, lon, ts, tk, road, cty = (list(p) + ["", 0, "", ""])[:6]\n            out.append([float(lat), float(lon), str(ts or ""),\n                        int(tk or 0), str(road or ""), str(cty or "")])\n        except (TypeError, ValueError):\n            continue\n    return out\n\n\ndef _clusters(hist) -> list[dict]:\n    """Cluster archived crash points on the same ~400 m grid as\n    ledger.hotspots, keeping distinct days and hour detail for the\n    protocol gates."""\n    cell = config.HOTSPOT_CELL_DEG\n    grid: dict[tuple, dict] = {}\n    for lat, lon, ts, tk, road, cty in _points(hist):\n        key = (round(lat / cell), round(lon / cell))\n        g = grid.setdefault(key, {"n": 0, "truck": 0, "lat": 0.0, "lon": 0.0,\n                                  "roads": {}, "days": set(), "hours": [],\n                                  "dates": [], "first": "", "last": "",\n                                  "county": "", "key": key})\n        g["n"] += 1\n        g["truck"] += tk\n        g["lat"] += lat\n        g["lon"] += lon\n        if road:\n            g["roads"][road] = g["roads"].get(road, 0) + 1\n        if len(ts) >= 10:\n            g["days"].add(ts[:10])\n            g["dates"].append(ts[:10])\n        if len(ts) >= 13:\n            try:\n                g["hours"].append(int(ts[11:13]))\n            except ValueError:\n                pass\n        if ts:\n            g["first"] = min(g["first"] or ts, ts)\n            g["last"] = max(g["last"], ts)\n        if cty:\n            g["county"] = cty\n    return list(grid.values())\n\n\n_WINDOWS = [\n    ("the morning commute (roughly 6-9 AM)", range(6, 10), "morning"),\n    ("midday hours (roughly 10 AM-2 PM)", range(10, 15), "midday"),\n    ("the afternoon and evening commute (roughly 3-7 PM)",\n     range(15, 19), "evening"),\n    ("evening and overnight hours",\n     list(range(19, 24)) + list(range(0, 6)), "night"),\n]\n\n\ndef _window(hours: list) -> tuple:\n    """(public label, key) for the dominant time-of-day window, or a\n    \'varied\' label when no window holds a majority of the crashes."""\n    if not hours:\n        return ("varied times of day", "varied")\n    best_lab, best_key, best_n = "varied times of day", "varied", 0\n    for lab, rng, key in _WINDOWS:\n        n = sum(1 for h in hours if h in rng)\n        if n > best_n:\n            best_lab, best_key, best_n = lab, key, n\n    if best_n / max(len(hours), 1) < 0.5:\n        return ("varied times of day", "varied")\n    return (best_lab, best_key)\n\n\n_ACTIONS = {\n    "morning": "Leave additional following distance and anticipate "\n               "slowing or stopped traffic ahead",\n    "evening": "Leave additional following distance and anticipate "\n               "slowing or stopped traffic ahead",\n    "midday": "Slow down and allow extra following distance through "\n              "this area",\n    "night": "Reduce speed and stay especially alert in low-light "\n             "conditions through this area",\n    "varied": "Slow down and allow extra following distance through "\n              "this area",\n}\n\n_TRUCK_ACTION = ("Allow commercial trucks extra room and avoid lingering "\n                 "alongside them through this stretch")\n\n_QUESTIONS = {\n    "morning": ["Do signal timing, queue formation, or sight distance "\n                "contribute to the recurring peak-period pattern?",\n                "Are advance warning of slowdowns and speed management "\n                "adequate for commute-period volumes?"],\n    "evening": ["Do signal timing, queue formation, or sight distance "\n                "contribute to the recurring peak-period pattern?",\n                "Are advance warning of slowdowns and speed management "\n                "adequate for commute-period volumes?"],\n    "night": ["Are lighting, delineation, and retroreflectivity adequate "\n              "for nighttime conditions at this location?",\n              "Does nighttime sight distance or roadside visibility "\n              "contribute to the recurring pattern?"],\n    "midday": ["Are lane markings, signs, access points, and sight "\n               "distance adequate at this location?"],\n    "varied": ["Are lane markings, signs, lighting, drainage, and "\n               "pavement condition adequate at this location?",\n               "Does the location warrant a formal road-safety audit or "\n               "speed study?"],\n}\n\n_TRUCK_QUESTION = ("Are merge transitions, lane continuity, signing, and "\n                   "speed differentials appropriate for the commercial "\n                   "traffic using this location?")\n\n_CORRIDOR_QUESTION = ("Does the pattern along this stretch suggest a "\n                      "corridor-wide treatment (access management, speed "\n                      "management, consistent delineation) rather than a "\n                      "single-point fix?")\n\n_ROAD_QUESTION = ("Is the recurrence along this route better explained by "\n                  "a consistent design characteristic than by any one "\n                  "location on it?")\n\n# Plain-English "why locations do this" phrases for the PUBLIC page.\n# Accountability framing: a recurring pattern at one spot points to\n# something about the road (fixable), not the drivers passing through.\n_CAUSES = {\n    "morning": "sight lines, signal timing, or the way traffic backs "\n               "up during the commute",\n    "evening": "sight lines, signal timing, or the way traffic backs "\n               "up during the commute",\n    "midday": "lane markings, signs, access points, or sight distance",\n    "night": "lighting, pavement markings, or nighttime visibility",\n    "varied": "road geometry, drainage, signs, or pavement condition",\n}\n_TRUCK_CAUSE = ("merge transitions and speed differences between "\n                "cars and commercial trucks")\n_CORRIDOR_CAUSE = ("the design of the stretch as a whole - how entrances "\n                   "and exits are spaced, where speeds change, or how "\n                   "consistent the road feels from one mile to the next")\n\n# Opening clauses for the public location cards. Selected deterministically\n# per location so the page reads like prose rather than a filled-in form.\n_OPENERS = {\n    "spot": [\n        "Collisions here keep landing in the same short stretch of road.",\n        "This is a single spot our monitoring keeps returning to.",\n        "The collisions we recorded here cluster tightly around one point.",\n    ],\n    "corridor": [\n        "The pattern here runs along the road rather than sitting at one "\n        "intersection.",\n        "Collisions are spread down this stretch rather than piling up at "\n        "a single point.",\n        "This one shows up as a length of road, not a pinpoint.",\n    ],\n    "road": [\n        "Collisions keep appearing on this road across the county, without "\n        "settling on one stretch.",\n        "This route comes up repeatedly in our monitoring, in more than "\n        "one place.",\n        "The recurrence here is at route level: several separate places, "\n        "same road.",\n    ],\n}\n\n_TIER_LABEL = {"spot": "Single location",\n               "corridor": "Corridor",\n               "road": "Route-wide"}\n\n\ndef _tier_note(tier: str) -> str:\n    if tier == "spot":\n        return "collisions concentrated within about 400 metres"\n    if tier == "corridor":\n        return ("collisions chained along one road, each within %.0f km "\n                "of the next" % config.SEGMENT_LINK_KM)\n    return ("collisions on the same named road within one county, too "\n            "scattered to form a single corridor")\n\n\ndef _when(r: dict) -> str:\n    """Sentence-fragment for when a pattern concentrates. \'Varied\' is not\n    a time of day, so it gets its own phrasing rather than being dropped\n    into a slot that expects one."""\n    if r["window_key"] == "varied":\n        return "spread across the day with no single peak period"\n    return "concentrated during " + r["window"]\n\n\ndef _when_drive(r: dict) -> str:\n    """Trailing clause for driver advice. Says nothing rather than\n    \'especially during varied times of day\'."""\n    if r["window_key"] == "varied":\n        return ""\n    return ", especially during " + r["window"]\n\n\ndef _confidence(n: int, days: int) -> str:\n    if n >= 10 and days >= 7:\n        return "high"\n    if n >= 5 and days >= 4:\n        return "moderate"\n    return "low"\n\n\n_COVERAGE_BAND = {"A": "high", "B": "high", "C": "moderate", "D": "low"}\n\n\ndef _recency(dates: list, ref=None) -> float:\n    """Share of a location\'s collisions falling in the most recent 30\n    days - is this pattern current, or the tail of something already\n    dealt with?"""\n    if not dates:\n        return 0.0\n    ref = ref or config.local_now()\n    cut = (ref - _dt.timedelta(days=30)).isoformat()[:10]\n    return sum(1 for d in dates if d >= cut) / len(dates)\n\n\ndef _priority(r: dict, mx_n: int) -> dict:\n    """Review-priority score, 0-100, built from four named 0-25\n    components so the Action Brief can SHOW its reasoning instead of\n    asserting a rank. Deliberately simple and monotonic: nothing here is\n    a model, it is an ordering rule stated in public.\n\n    `mx_n` is the largest count WITHIN THE SAME TIER, not overall. A\n    corridor spanning 7 km will always out-count a 400 m spot, so\n    scoring them on the same raw scale would rank every corridor above\n    every spot regardless of merit — and spots are the more actionable\n    finding. Volume therefore answers \'how strong is this for its kind\'.\n    """\n    vol = 25.0 * min(r["n"] / max(mx_n, 1), 1.0)\n    rec = 25.0 * min(r["days"] / 10.0, 1.0)\n    con = 25.0 * min((r.get("rel") or _corridor_rel(r)) / 3.0, 1.0)\n    cur = 25.0 * min(r.get("recency", 0.0) / 0.5, 1.0)\n    return {"volume": round(vol, 1), "recurrence": round(rec, 1),\n            "concentration": round(con, 1), "currency": round(cur, 1),\n            "total": round(vol + rec + con + cur, 1)}\n\n\ndef _corridor_rel(r: dict) -> float:\n    """Concentration proxy for tiers without a class-relative multiple:\n    collisions per km for corridors (1.0/km treated as par), a flat\n    modest value for route-wide records."""\n    if r.get("per_km"):\n        return min(float(r["per_km"]), 6.0)\n    return 1.0\n\n\ndef _dress(rec: dict, coverage: dict):\n    """Shared enrichment: time window, action, cause, questions,\n    confidence, coverage band. Returns None if the coverage gate fails."""\n    grade = (coverage.get(rec["county"].split(" / ")[0]) or {}).get("grade")\n    if grade == "F":\n        return None\n    win_label, win_key = _window(rec.get("hours") or [])\n    truck_heavy = rec["n"] >= 3 and rec["truck"] / rec["n"] >= 0.4\n    questions = list(_QUESTIONS[win_key])\n    if truck_heavy:\n        questions.insert(0, _TRUCK_QUESTION)\n    if rec["tier"] == "corridor":\n        questions.append(_CORRIDOR_QUESTION)\n    if rec["tier"] == "road":\n        questions.append(_ROAD_QUESTION)\n    cause = (_TRUCK_CAUSE if truck_heavy\n             else _CORRIDOR_CAUSE if rec["tier"] in ("corridor", "road")\n             else _CAUSES[win_key])\n    rec.update({\n        "window": win_label, "window_key": win_key,\n        "truck_heavy": truck_heavy,\n        "action": _TRUCK_ACTION if truck_heavy else _ACTIONS[win_key],\n        "cause": cause,\n        "questions": questions,\n        "confidence": _confidence(rec["n"], rec["days"]),\n        "coverage_band": _COVERAGE_BAND.get(grade, "still building"),\n        "coverage_grade": grade,\n        "opener": _pick(_OPENERS[rec["tier"]], rec["road"] + rec["county"]),\n        "tier_label": _TIER_LABEL[rec["tier"]],\n        "tier_note": _tier_note(rec["tier"]),\n    })\n    return rec\n\n\ndef qualified(hist, coverage=None) -> list:\n    """Ranked public-safe location records across all three evidence\n    tiers. Everything downstream renders only these records."""\n    import ledger as _ledger_mod\n    coverage = coverage or {}\n    out = []\n    claimed_roads = set()   # (road, county) claimed by a stronger tier\n\n    # --- tier 1: spots -------------------------------------------------\n    clusters = _clusters(hist)\n    cells = [{"n": g["n"],\n              "road": " / ".join(sorted(g["roads"], key=g["roads"].get,\n                                        reverse=True)[:2])}\n             for g in clusters]\n    _ledger_mod.class_relative(cells)\n    for g, cc in zip(clusters, cells):\n        g["cls"], g["rel"] = cc["cls"], cc["rel"]\n    for g in clusters:\n        if g["n"] < max(config.PUB_MIN_N, config.HOTSPOT_MIN_N):\n            continue\n        if len(g["days"]) < config.PUB_MIN_DAYS:\n            continue\n        road = " / ".join(sorted(g["roads"], key=g["roads"].get,\n                                 reverse=True)[:2])\n        if not road:\n            continue\n        rec = _dress({\n            "tier": "spot", "road": road, "county": g["county"] or "",\n            "lat": round(g["lat"] / g["n"], 3),\n            "lon": round(g["lon"] / g["n"], 3),\n            "n": g["n"], "days": len(g["days"]), "truck": g["truck"],\n            "hours": g["hours"], "dates": g["dates"],\n            "first": g["first"][:10], "last": g["last"][:10],\n            "cls": g.get("cls"), "rel": g.get("rel"),\n            "recency": _recency(g["dates"]),\n            "km": None, "per_km": None, "path": None,\n        }, coverage)\n        if rec:\n            out.append(rec)\n            claimed_roads.add((road.split(" / ")[0], rec["county"]))\n\n    # --- tier 2: corridors ---------------------------------------------\n    # ledger.segments already does the chaining; here we add the\n    # recurrence gate and drop corridors on a road a spot already claimed,\n    # so the same collisions are never counted twice.\n    pts = _points(hist)\n    for s in _ledger_mod.segments(hist):\n        if s["n"] < config.PUB_CORRIDOR_MIN_N:\n            continue\n        if s["days"] < config.PUB_CORRIDOR_MIN_DAYS:\n            continue\n        base = s["road"].split(" / ")[0]\n        cty0 = (s.get("county") or "").split(" / ")[0]\n        if (base, cty0) in claimed_roads:\n            continue\n        inside = {(round(p[0], 4), round(p[1], 4)) for p in s["path"]}\n        hours, dates = [], []\n        for lat, lon, ts, tk, road, cty in pts:\n            if (round(lat, 4), round(lon, 4)) not in inside:\n                continue\n            if len(ts) >= 10:\n                dates.append(ts[:10])\n            if len(ts) >= 13:\n                try:\n                    hours.append(int(ts[11:13]))\n                except ValueError:\n                    pass\n        rec = _dress({\n            "tier": "corridor", "road": s["road"],\n            "county": s.get("county") or "",\n            "lat": round(sum(p[0] for p in s["path"]) / len(s["path"]), 3),\n            "lon": round(sum(p[1] for p in s["path"]) / len(s["path"]), 3),\n            "n": s["n"], "days": s["days"], "truck": s["truck"],\n            "hours": hours, "dates": dates,\n            "first": s["first"], "last": s["last"],\n            "cls": s.get("cls"), "rel": None,\n            "recency": _recency(dates),\n            "km": s["km"], "per_km": s["per_km"], "path": s["path"],\n        }, coverage)\n        if rec:\n            out.append(rec)\n            claimed_roads.add((base, cty0))\n\n    # --- tier 3: route-wide --------------------------------------------\n    by_road = {}\n    for lat, lon, ts, tk, road, cty in pts:\n        base = road.split(" / ")[0].strip()\n        if not base or base.lower() == "none" or not cty:\n            continue\n        if (base, cty) in claimed_roads:\n            continue\n        g = by_road.setdefault((base, cty), {\n            "n": 0, "truck": 0, "lat": 0.0, "lon": 0.0, "days": set(),\n            "hours": [], "dates": [], "first": "", "last": ""})\n        g["n"] += 1\n        g["truck"] += tk\n        g["lat"] += lat\n        g["lon"] += lon\n        if len(ts) >= 10:\n            g["days"].add(ts[:10])\n            g["dates"].append(ts[:10])\n        if len(ts) >= 13:\n            try:\n                g["hours"].append(int(ts[11:13]))\n            except ValueError:\n                pass\n        g["first"] = min(g["first"] or ts, ts)\n        g["last"] = max(g["last"], ts)\n    for (base, cty), g in by_road.items():\n        if g["n"] < config.PUB_ROAD_MIN_N:\n            continue\n        if len(g["days"]) < config.PUB_ROAD_MIN_DAYS:\n            continue\n        rec = _dress({\n            "tier": "road", "road": base, "county": cty,\n            "lat": round(g["lat"] / g["n"], 3),\n            "lon": round(g["lon"] / g["n"], 3),\n            "n": g["n"], "days": len(g["days"]), "truck": g["truck"],\n            "hours": g["hours"], "dates": g["dates"],\n            "first": g["first"][:10], "last": g["last"][:10],\n            "cls": _ledger_mod.road_class(base), "rel": None,\n            "recency": _recency(g["dates"]),\n            "km": None, "per_km": None, "path": None,\n        }, coverage)\n        if rec:\n            out.append(rec)\n\n    mx_by_tier = {}\n    for r in out:\n        mx_by_tier[r["tier"]] = max(mx_by_tier.get(r["tier"], 1), r["n"])\n    for r in out:\n        r["score"] = _priority(r, mx_by_tier.get(r["tier"], 1))\n    tier_rank = {"spot": 0, "corridor": 1, "road": 2}\n    out.sort(key=lambda r: (-r["score"]["total"], tier_rank[r["tier"]],\n                            -r["n"]))\n    # Slot reservation. A pinpointed spot is the most actionable thing we\n    # can hand an engineer, and there are always fewer of them than\n    # corridors, so reserve part of the report for them rather than\n    # letting a good corridor run push every spot off the page.\n    cap = config.PUB_MAX_LOCATIONS\n    spots = [r for r in out if r["tier"] == "spot"]\n    if spots and len(out) > cap:\n        keep = spots[:config.PUB_RESERVE_SPOTS]\n        rest = [r for r in out if r not in keep]\n        out = keep + rest[:max(cap - len(keep), 0)]\n        out.sort(key=lambda r: (-r["score"]["total"], tier_rank[r["tier"]],\n                                -r["n"]))\n    return out[:cap]\n\n\n# --- archive-wide statistics for the teaching sections -------------------\n\ndef profile(hist) -> dict:\n    """Statewide shape of the windowed archive: hour, weekday, month,\n    road class, truck share, counties touched."""\n    import ledger as _l\n    pts = _points(hist)\n    hours, days, months, classes, counties = {}, {}, {}, {}, {}\n    truck = 0\n    for _lat, _lon, ts, tk, road, cty in pts:\n        truck += tk\n        if cty:\n            counties[cty] = counties.get(cty, 0) + 1\n        cls = _l.road_class(road)\n        classes[cls] = classes.get(cls, 0) + 1\n        if len(ts) >= 16:\n            try:\n                t = _dt.datetime.fromisoformat(ts)\n            except ValueError:\n                continue\n            hours[t.hour] = hours.get(t.hour, 0) + 1\n            days[t.strftime("%A")] = days.get(t.strftime("%A"), 0) + 1\n            key = t.strftime("%Y-%m")\n            months[key] = months.get(key, 0) + 1\n    return {"n": len(pts), "hours": hours, "days": days,\n            "months": sorted(months.items()), "classes": classes,\n            "counties": counties, "truck": truck,\n            "truck_share": truck / max(len(pts), 1)}\n\n\ndef readiness(hist, records: list) -> dict:\n    """Why the report says what it says. Reports the archive size and how\n    many locations survive each gate, so an empty report can distinguish\n    \'we do not have enough data yet\' from \'we have plenty of data and\n    nothing is recurring\' - those mean opposite things, and v9 printed\n    the same sentence for both."""\n    total = 0\n    for bucket in ((hist.get("_ledger") or {}).get("months") or {}).values():\n        for _c, v in bucket.items():\n            total += v["n"] if isinstance(v, dict) else int(v or 0)\n    pts = _points(hist)\n    clusters = _clusters(hist)\n    spots_n = [g for g in clusters\n               if g["n"] >= max(config.PUB_MIN_N, config.HOTSPOT_MIN_N)]\n    spots_d = [g for g in spots_n if len(g["days"]) >= config.PUB_MIN_DAYS]\n    spots_r = [g for g in spots_d if g["roads"]]\n    verdict = ("publishing" if records\n               else "thin" if total < config.PUB_MIN_ARCHIVE\n               else "no_pattern")\n    return {\n        "archive_total": total,\n        "windowed": len(pts),\n        "cells": len(clusters),\n        "spots_volume": len(spots_n),\n        "spots_recurring": len(spots_d),\n        "spots_named": len(spots_r),\n        "records": len(records),\n        "by_tier": {t: sum(1 for r in records if r["tier"] == t)\n                    for t in ("spot", "corridor", "road")},\n        "verdict": verdict,\n        "needed": max(config.PUB_MIN_ARCHIVE - total, 0),\n    }\n\n\n_DISCLAIMER = ("This report summarizes broad, aggregated roadway patterns "\n               "and conditions. It does not predict individual collisions, "\n               "identify people involved in collisions, determine the "\n               "engineering cause of any incident, or replace official "\n               "traffic, weather, emergency, or transportation guidance.")\n\n\ndef _period(records: list, hist) -> str:\n    firsts = [r["first"] for r in records if r.get("first")]\n    lasts = [r["last"] for r in records if r.get("last")]\n    if firsts and lasts:\n        return "%s to %s" % (min(firsts), max(lasts))\n    since = str((hist.get("_ledger") or {}).get("since") or "")[:10]\n    return ("monitoring since " + since) if since else "current archive"\n\n\ndef _stamp() -> str:\n    now = config.local_now()\n    return ("Generated " + now.strftime("%A, %B %d, %Y at %I:%M %p")\n            .replace(" 0", " ")\n            + " Indiana time  ·  %d-day analysis window"\n            % config.HOTSPOT_WINDOW_D)\n\n\ndef _banners(degraded, published: bool) -> str:\n    out = []\n    if not published:\n        out.append("<div class=\'note draft\'><b>Draft — internal review "\n                   "copy.</b> Not published. To publish after review, "\n                   "re-run the workflow with the publish box ticked; that "\n                   "copies the draft you are reading to the public address "\n                   "before the next build refreshes it.</div>")\n    if degraded:\n        out.append("<div class=\'note hold\'><b>Publication hold "\n                   "recommended.</b> A primary live data source has been "\n                   "unavailable since "\n                   + _esc(str(degraded)[:16].replace("T", " "))\n                   + ". Per protocol, keep the last published report live "\n                   "rather than publishing from degraded data.</div>")\n    return "".join(out)\n\n\ndef _empty_block(rd: dict) -> str:\n    """The honest empty state. Two very different situations get two very\n    different messages, each naming the next thing that has to happen."""\n    if rd["verdict"] == "thin":\n        body = ("<p class=\'lede\'>The archive is still filling. We have "\n                "<b>%d</b> recorded collisions; reporting begins at "\n                "<b>%d</b>, so roughly <b>%d</b> more are needed before "\n                "locations are ranked here.</p>"\n                % (rd["archive_total"], config.PUB_MIN_ARCHIVE,\n                   rd["needed"]))\n    else:\n        body = ("<p class=\'lede\'>The archive is large enough to report "\n                "from — <b>%d</b> collisions recorded, <b>%d</b> of them "\n                "inside the current %d-day window. What it does not "\n                "contain right now is <i>recurrence</i>: no spot, "\n                "corridor, or route has accumulated enough collisions on "\n                "enough separate days to be published as a pattern.</p>"\n                "<p>That is a finding, not a failure. Collisions "\n                "scattered widely with nothing repeating is what a road "\n                "network without a concentrated problem looks like in "\n                "this data.</p>"\n                % (rd["archive_total"], rd["windowed"],\n                   config.HOTSPOT_WINDOW_D))\n    stages = [("Collisions in window", rd["windowed"], ""),\n              ("Distinct locations", rd["cells"], ""),\n              ("%d+ collisions" % config.PUB_MIN_N, rd["spots_volume"], ""),\n              ("On %d+ separate days" % config.PUB_MIN_DAYS,\n               rd["spots_recurring"], ""),\n              ("With a road name", rd["spots_named"], ""),\n              ("Published", rd["records"], "")]\n    return (body + "<figure>" + ui.funnel(stages)\n            + "<figcaption>Every gate a single location has to clear "\n              "before it appears here. The bar that collapses is the one "\n              "holding publication back. Corridor and route-wide "\n              "candidates are screened separately and also came back "\n              "empty.</figcaption></figure>")\n\n\n# =========================================================================\n# ROAD SAFETY WATCH — public page\n# =========================================================================\n\ndef watch_html(records, hist, degraded=None, prof=None, rd=None,\n               published: bool = False) -> str:\n    prof = prof or profile(hist)\n    rd = rd if rd is not None else readiness(hist, records)\n    period = _period(records, hist)\n    brief_link = "action_brief.html" if published \\\n        else "action_brief_draft.html"\n    H = [ui.head("Indiana Road Safety Watch", "safety"),\n         ui.tabs("safety_watch.html", draft=not published),\n         ui.open_wrap(),\n         ui.masthead(\n             "Indiana Road Safety Watch",\n             "Where Indiana roads keep producing collisions",\n             "Different drivers, different days, the same piece of road. "\n             "When that keeps happening, the road is usually part of the "\n             "story — and roads can be changed.",\n             _stamp()),\n         _banners(degraded, published)]\n\n    if records:\n        n_c = len({r["county"].split(" / ")[0] for r in records})\n        H.append(ui.figs([\n            (str(len(records)), "Locations watched",\n             "across %d %s" % (n_c, "county" if n_c == 1 else "counties")),\n            (str(sum(r["n"] for r in records)), "Collisions at them",\n             "inside the analysis window"),\n            ("%d / %d / %d" % (rd["by_tier"]["spot"],\n                               rd["by_tier"]["corridor"],\n                               rd["by_tier"]["road"]),\n             "Spots / corridors / routes", "by kind of pattern"),\n            ("%.0f%%" % (100 * prof["truck_share"]), "Truck-involved",\n             "of everything we recorded"),\n        ]))\n        H.append("<p class=\'lede\'>Our roadway monitoring has identified "\n                 "<b>%d</b> %s across <b>%d</b> Indiana %s where "\n                 "collisions keep happening in the same place (analysis "\n                 "period: %s). Each is listed below in plain language, and "\n                 "each is flagged as a candidate for engineering review in "\n                 "our <a href=\'%s\'>Hotspot Action Brief</a>. None of this "\n                 "is a prediction about any individual driver or any "\n                 "individual trip.</p>"\n                 % (len(records),\n                    "location" if len(records) == 1 else "locations",\n                    n_c, "county" if n_c == 1 else "counties",\n                    _esc(period), brief_link))\n\n        H.append(ui.h2("Watch", "The locations"))\n        H.append("<p class=\'small\'>Ordered by how strongly the pattern "\n                 "shows in our data. The tag on each card says what kind "\n                 "of pattern it is: a single spot, a stretch of road, or a "\n                 "route that keeps coming up in more than one place.</p>")\n        for i, r in enumerate(records, 1):\n            H.append(_watch_card(r, i, brief_link))\n\n        H.append(ui.h2("Rank", "Ranked by recorded collisions"))\n        H.append("<div class=\'card\'>" + ui.stripe_rows(\n            [(r["road"], "%s County · %s" % (r["county"], r["tier_label"]),\n              r["n"]) for r in records]) + "</div>")\n        H.append("<p class=\'hint\'>Each dash is one collision our "\n                 "monitoring recorded inside the analysis window. Counts "\n                 "are not adjusted for how much traffic a road carries, so "\n                 "busy roads naturally appear more often.</p>")\n    else:\n        H.append(ui.h2("Status", "Nothing meets the publication bar yet"))\n        H.append(_empty_block(rd))\n\n    H.append(_teaching(prof))\n\n    H.append(ui.h2("Read", "How to read this page"))\n    H.append(\n        "<div class=\'card\'>"\n        "<p><b>A quiet location is not a safe location.</b> We can only "\n        "see collisions that reach a public traffic feed. Coverage is "\n        "strongest on interstates and state-managed roads and thinnest on "\n        "local streets, so a road\'s absence from this page says as much "\n        "about our visibility as about the road.</p>"\n        "<p><b>These are patterns, not causes.</b> We can show that "\n        "collisions repeat at a place. Determining <i>why</i> takes a site "\n        "visit, traffic counts, and engineering judgement — which is "\n        "exactly what the companion brief asks public agencies to do.</p>"\n        "<p><b>Nothing here describes an individual collision.</b> No "\n        "people, vehicles, injuries, or fault. Counts, dates, and places "\n        "only.</p></div>")\n\n    H.append(ui.foot("<b>About this report.</b> " + _DISCLAIMER))\n    H.append(ui.close())\n    return "\\n".join(H)\n\n\ndef _watch_card(r: dict, rank: int, brief_link: str) -> str:\n    truck_clause = (" A noticeable share of them involved commercial "\n                    "trucks." if r["truck_heavy"] else "")\n    if r.get("rel") and r["rel"] >= 1.2:\n        rel_clause = (" That is roughly <b>%.1f×</b> the collision count "\n                      "of a typical repeat-collision %s location in our "\n                      "current window." % (r["rel"], _esc(r["cls"])))\n    elif r.get("per_km"):\n        rel_clause = (" Along <b>%.1f km</b> of road, that works out to "\n                      "about <b>%.1f</b> collisions per kilometre."\n                      % (r["km"], r["per_km"]))\n    else:\n        rel_clause = ""\n\n    chips = ["<span class=\'chip on\'>%s</span>" % _esc(r["tier_label"]),\n             "<span class=\'chip\'>%s confidence</span>"\n             % _esc(r["confidence"])]\n    if r["truck_heavy"]:\n        chips.append("<span class=\'chip warn\'>Truck-involved</span>")\n    if r.get("recency", 0) >= 0.4:\n        chips.append("<span class=\'chip warn\'>Active recently</span>")\n\n    hours = {}\n    for h in (r.get("hours") or []):\n        hours[h] = hours.get(h, 0) + 1\n    chart = ""\n    if len(hours) >= 3:\n        chart = ("<figure>" + ui.hour_chart(hours, height=62)\n                 + "<figcaption>When these collisions were first reported, "\n                   "by hour of day. Shaded bands are the morning and "\n                   "afternoon commutes.</figcaption></figure>")\n\n    return (\n        "<div class=\'card rank\'>"\n        "<div class=\'card-h\'><div class=\'where\'>%s<span class=\'cty\'>%s "\n        "County</span></div><div class=\'kicker\'>#%d</div></div>"\n        "<div class=\'chips\'>%s</div>"\n        "<p>%s We recorded <b>%d collisions</b> here on <b>%d separate "\n        "days</b> between %s and %s, %s.%s%s</p>"\n        "<p>A pattern like that — different drivers, different days, same "\n        "place — usually traces back to the location rather than to the "\n        "people driving through it: things like %s. Those are the kinds of "\n        "things a road agency can survey and change.</p>"\n        "<p><b>What happens next:</b> this location is flagged as a "\n        "candidate for engineering or policy review in the "\n        "<a href=\'%s\'>Hotspot Action Brief</a>, which sets out the "\n        "specific questions a reviewing engineer would work through.</p>"\n        "<p><b>If you drive it:</b> %s%s.</p>"\n        "%s"\n        "<p class=\'small\' style=\'margin-top:12px;padding-top:10px;"\n        "border-top:1px solid var(--line2)\'>Evidence: %d collisions on %d "\n        "separate days · %s · observation coverage in this county is %s. "\n        "Counts are not adjusted for traffic volume.</p></div>"\n        % (_esc(r["road"]), _esc(r["county"]), rank, "".join(chips),\n           _esc(r["opener"]), r["n"], r["days"], _esc(r["first"]),\n           _esc(r["last"]), _esc(_when(r)), truck_clause, rel_clause,\n           _esc(r["cause"]), _esc(brief_link), _esc(r["action"]),\n           _esc(_when_drive(r)), chart, r["n"], r["days"],\n           _esc(r["tier_note"]), _esc(r["coverage_band"])))\n\n\n# =========================================================================\n# TEACHING SECTION — shared by both reports\n# =========================================================================\n\ndef _teaching(prof: dict) -> str:\n    if not prof["n"]:\n        return ""\n    H = [ui.h2("Pattern", "What the whole archive shows")]\n    H.append("<p class=\'lede\'>Beyond individual locations, the collisions "\n             "we recorded have a shape: they cluster in particular hours, "\n             "on particular days, and on particular classes of road. What "\n             "follows is all <b>%d</b> collisions inside the current "\n             "%d-day window.</p>" % (prof["n"], config.HOTSPOT_WINDOW_D))\n\n    H.append("<figure>" + ui.hour_chart(prof["hours"])\n             + "<figcaption><b>By hour of day.</b> Each bar is the number "\n               "of collisions first reported in that hour, Indiana local "\n               "time. The shaded bands are the morning (6–10 AM) and "\n               "afternoon (3–7 PM) commutes — the two periods when most "\n               "of Indiana is on the road at once.</figcaption></figure>")\n\n    if prof["days"]:\n        H.append("<div class=\'card\'><h3>By day of week</h3>"\n                 + ui.day_chart(prof["days"])\n                 + "<p class=\'hint\'>One dash per collision. Weekday and "\n                   "weekend patterns differ because the trips differ — "\n                   "commuting versus errands, daylight versus night "\n                   "driving.</p></div>")\n\n    if prof["classes"]:\n        pal = {"interstate": "#1B3A6B", "US highway": "#14603C",\n               "state road": "#8C3A12", "local road": "#6E7880",\n               "unclassified": "#B7BFB6"}\n        parts = [(k, v, pal.get(k, "#6E7880"))\n                 for k, v in sorted(prof["classes"].items(),\n                                    key=lambda kv: -kv[1])]\n        H.append("<div class=\'card\'><h3>By class of road</h3>"\n                 + ui.prop_bar(parts)\n                 + "<p class=\'hint\'>This split is as much about what we "\n                   "can see as about where collisions happen. Live feeds "\n                   "cover interstates and state-managed routes thoroughly "\n                   "and local streets only patchily, so the local-road "\n                   "share here is an undercount of reality rather than a "\n                   "measurement of it.</p></div>")\n\n    if len(prof["months"]) >= 2:\n        labs = []\n        for m, v in prof["months"]:\n            try:\n                labs.append((_dt.datetime.strptime(m, "%Y-%m")\n                             .strftime("%b"), v))\n            except ValueError:\n                labs.append((m, v))\n        H.append("<figure>" + ui.month_chart(labs)\n                 + "<figcaption><b>By month.</b> Recorded collisions per "\n                   "calendar month. The current month is partial, and the "\n                   "earliest may be too if monitoring began mid-month — "\n                   "read the trend, not the end columns."\n                   "</figcaption></figure>")\n\n    if prof["counties"]:\n        top = sorted(prof["counties"].items(), key=lambda kv: -kv[1])[:10]\n        H.append("<div class=\'card\'><h3>Where they were recorded</h3>"\n                 + ui.stripe_rows([(c, "", n) for c, n in top])\n                 + "<p class=\'hint\'>Top ten counties by recorded "\n                   "collisions. This tracks population and highway mileage "\n                   "closely, and it also tracks how well our feeds see "\n                   "each county — it is not a ranking of which counties "\n                   "are most dangerous.</p></div>")\n    return "".join(H)\n\n\n# =========================================================================\n# HOTSPOT ACTION BRIEF — policymaker page\n# =========================================================================\n\ndef brief_html(records, hist, degraded=None, prof=None, rd=None,\n               coverage=None, published: bool = False) -> str:\n    prof = prof or profile(hist)\n    rd = rd if rd is not None else readiness(hist, records)\n    coverage = coverage or {}\n    period = _period(records, hist)\n    watch_link = "safety_watch.html" if published \\\n        else "safety_watch_draft.html"\n    H = [ui.head("Hotspot Action Brief", "brief"),\n         ui.tabs("action_brief.html", draft=not published),\n         ui.open_wrap(),\n         ui.masthead(\n             "Hotspot Action Brief",\n             "Candidates for engineering or policy review",\n             "A screening signal for public officials and traffic "\n             "professionals: where recorded collisions concentrate, how "\n             "strong each signal is, and the questions a site review "\n             "would need to answer.",\n             _stamp()),\n         _banners(degraded, published)]\n\n    if records:\n        H.append(ui.figs([\n            (str(len(records)), "Review candidates", "ranked below"),\n            (str(sum(r["n"] for r in records)), "Collisions represented",\n             "inside the analysis window"),\n            (str(sum(1 for r in records if r["confidence"] != "low")),\n             "Moderate or better", "by evidence confidence"),\n            (str(sum(r["truck"] for r in records)), "Truck-involved",\n             "across all candidates"),\n        ]))\n        H.append("<p class=\'lede\'>The locations below show recurring "\n                 "collision concentration in our monitoring (analysis "\n                 "period: %s). Each is presented as a <b>candidate for "\n                 "engineering or policy review</b> — a place worth looking "\n                 "at, not a place we have concluded anything about. This "\n                 "brief is a screening signal, not a determination of "\n                 "cause, and it does not conclude that any location is "\n                 "defective or negligently designed. A public companion "\n                 "page, <a href=\'%s\'>Road Safety Watch</a>, presents the "\n                 "same locations in plain language for drivers.</p>"\n                 % (_esc(period), watch_link))\n        H.append(_method_block())\n        H.append(_evidence_table(records))\n        H.append(ui.h2("Candidates", "Review candidates in priority order"))\n        for i, r in enumerate(records, 1):\n            H.append(_brief_card(r, i))\n        H.append(_coverage_caveat(records, coverage))\n    else:\n        H.append(ui.h2("Status", "No candidates meet the screening bar"))\n        H.append(_empty_block(rd))\n\n    H.append(_teaching(prof))\n\n    H.append(ui.h2("Limits", "Data limitations"))\n    H.append(\n        "<div class=\'card\'>"\n        "<p><b>Source.</b> Collision observations come from public live "\n        "traffic feeds — INDOT-managed roads via 511, plus probe-data "\n        "incident detection on local roads. These feeds do not capture "\n        "every collision, and what they capture skews toward higher road "\n        "classes.</p>"\n        "<p><b>No exposure adjustment.</b> Counts are not normalised by "\n        "traffic volume. A road carrying 80,000 vehicles a day "\n        "accumulates more recorded collisions than one carrying 8,000 at "\n        "the same rate per vehicle. Rankings here are screening "\n        "priorities within observed data, not exposure-adjusted risk "\n        "rates. Pairing this list with AADT counts is the single "\n        "highest-value next step for anyone acting on it.</p>"\n        "<p><b>Detection timing.</b> Timestamps record when a collision "\n        "first appeared on a feed, not when it occurred. Peak-hour "\n        "figures are therefore slightly lagged, and the lag is longer on "\n        "roads with sparser detection.</p>"\n        "<p><b>Window.</b> Everything here is drawn from the last %d "\n        "days. Locations treated and improved before that window will not "\n        "appear; locations that have only recently begun to deteriorate "\n        "may not yet clear the recurrence bar.</p></div>"\n        % config.HOTSPOT_WINDOW_D)\n\n    H.append(ui.foot("<b>About this brief.</b> " + _DISCLAIMER))\n    H.append(ui.close())\n    return "\\n".join(H)\n\n\ndef _method_block() -> str:\n    return (ui.h2("Method", "How a location earns a place on this list")\n            + ("<div class=\'card\'><p>Three kinds of recurrence qualify. "\n               "All three require collisions on multiple <i>separate "\n               "days</i>, which is what distinguishes a pattern from one "\n               "bad afternoon.</p>"\n               "<div class=\'tbl-scroll\'><table><tr><th>Tier</th>"\n               "<th>What it means</th><th class=\'num\'>Bar</th></tr>"\n               "<tr><td><b>Single location</b></td><td>Collisions inside "\n               "one ~400 m cell — an intersection, interchange, or short "\n               "stretch.</td><td class=\'num\'>%d+ on %d+ days</td></tr>"\n               "<tr><td><b>Corridor</b></td><td>Collisions chained along "\n               "one named road, each within %.0f km of the next, spanning "\n               "at least %.0f km.</td><td class=\'num\'>%d+ on %d+ days"\n               "</td></tr>"\n               "<tr><td><b>Route-wide</b></td><td>Collisions on one named "\n               "road within one county, too scattered to form a single "\n               "corridor. Weakest tier — a prompt to look, not a located "\n               "defect.</td><td class=\'num\'>%d+ on %d+ days</td></tr>"\n               "</table></div>"\n               "<p class=\'hint\'>Tiers are exclusive: collisions counted "\n               "as a single location are not counted again as a corridor "\n               "containing it, and a route only appears at the third tier "\n               "when neither stronger tier claimed it. Counties whose "\n               "feed coverage grades F are excluded entirely — we cannot "\n               "responsibly rank a place we can barely see.</p></div>"\n               % (config.PUB_MIN_N, config.PUB_MIN_DAYS,\n                  config.SEGMENT_LINK_KM, config.SEGMENT_MIN_KM,\n                  config.PUB_CORRIDOR_MIN_N, config.PUB_CORRIDOR_MIN_DAYS,\n                  config.PUB_ROAD_MIN_N, config.PUB_ROAD_MIN_DAYS)))\n\n\ndef _score_bar(s: dict) -> str:\n    """Stacked bar showing the four components of the priority score, so\n    the ranking argues for itself."""\n    parts = [("Volume", s["volume"], "#1B3A6B"),\n             ("Recurrence", s["recurrence"], "#2E6E4E"),\n             ("Concentration", s["concentration"], "#8C3A12"),\n             ("Currency", s["currency"], "#B9861B")]\n    segs = "".join(\n        "<div style=\'width:%.2f%%;background:%s\' title=\'%s: %.1f of 25\'>"\n        "%s</div>" % (v, c, _esc(k), v, (_esc(k) if v >= 17 else ""))\n        for k, v, c in parts if v > 0)\n    rest = 100 - sum(p[1] for p in parts)\n    if rest > 0.5:\n        segs += ("<div style=\'width:%.2f%%;background:var(--sunk)\'></div>"\n                 % rest)\n    keys = " ".join("<span><i style=\'background:%s\'></i>%s <b>%.0f</b>"\n                    "</span>" % (c, _esc(k), v) for k, v, c in parts)\n    return ("<div class=\'prop\' style=\'height:20px\'>" + segs + "</div>"\n            "<div class=\'prop-key\'>" + keys + "</div>")\n\n\ndef _evidence_table(records: list) -> str:\n    rows = []\n    for i, r in enumerate(records, 1):\n        rows.append(\n            "<tr><td class=\'num\'>%d</td><td><b>%s</b><br>"\n            "<span class=\'small\'>%.3f, %.3f</span></td><td>%s</td>"\n            "<td>%s</td><td class=\'num\'>%d</td><td class=\'num\'>%d</td>"\n            "<td class=\'num\'>%s</td><td>%s</td><td class=\'num\'>%d</td>"\n            "<td>%s</td><td>%s</td><td class=\'num\'>%.0f</td></tr>"\n            % (i, _esc(r["road"]), r["lat"], r["lon"], _esc(r["county"]),\n               _esc(r["tier_label"]), r["n"], r["days"],\n               ("%.1f×" % r["rel"]) if r.get("rel")\n               else ("%.1f/km" % r["per_km"]) if r.get("per_km") else "—",\n               _esc("no single peak" if r["window_key"] == "varied"\n                    else r["window"]), r["truck"], _esc(r["confidence"]),\n               _esc(r["coverage_band"]), r["score"]["total"]))\n    return (ui.h2("Evidence", "Evidence summary")\n            + "<div class=\'tbl-scroll\'><table><tr><th class=\'num\'>#</th>"\n              "<th>Location</th><th>County</th><th>Tier</th>"\n              "<th class=\'num\'>Collisions</th><th class=\'num\'>Days</th>"\n              "<th class=\'num\'>Intensity</th><th>Concentrated during</th>"\n              "<th class=\'num\'>Truck</th><th>Confidence</th>"\n              "<th>Coverage</th><th class=\'num\'>Priority</th></tr>"\n            + "".join(rows) + "</table></div>"\n            + "<p class=\'hint\'><b>Intensity</b> is a multiple of the "\n              "median repeat-collision location of the same road class "\n              "for single locations, and collisions per kilometre for "\n              "corridors — the two are not comparable with each other. "\n              "<b>Priority</b> is the 0–100 screening score broken down "\n              "on each candidate below. <b>Coverage</b> is how well our "\n              "feeds see the county, graded against similarly sized "\n              "counties.</p>")\n\n\ndef _brief_card(r: dict, rank: int) -> str:\n    qs = "".join("<li>%s</li>" % _esc(q) for q in r["questions"])\n    hours = {}\n    for h in (r.get("hours") or []):\n        hours[h] = hours.get(h, 0) + 1\n    chart = ""\n    if len(hours) >= 3:\n        chart = ("<figure>" + ui.hour_chart(hours, height=62)\n                 + "<figcaption>Collisions by hour of first report. "\n                   "Shaded bands mark the commute peaks."\n                   "</figcaption></figure>")\n    geom = ""\n    if r["tier"] == "corridor" and r.get("path"):\n        geom = ("<div style=\'margin-top:10px\'><div class=\'kicker\'>Crash "\n                "positions along the corridor</div>"\n                + ui.sparkpath(r["path"], w=330, h=76)\n                + "<p class=\'small\'>Each dot is one recorded collision, "\n                  "plotted by coordinate. Bunching at one end usually "\n                  "means a corridor with a specific problem point inside "\n                  "it; even spacing suggests a corridor-wide "\n                  "condition.</p></div>")\n    if r.get("per_km"):\n        intensity = ("Along %.1f km, about %.1f collisions per kilometre."\n                     % (r["km"], r["per_km"]))\n    elif r.get("rel"):\n        intensity = ("About %.1f× the median repeat-collision %s location "\n                     "in the same window." % (r["rel"], _esc(r["cls"])))\n    else:\n        intensity = ""\n\n    return (\n        "<div class=\'card rank\'>"\n        "<div class=\'card-h\'><div class=\'where\'>%s<span class=\'cty\'>%s "\n        "County · %s</span></div><div class=\'kicker\'>Priority %.0f / 100"\n        "</div></div>"\n        "<div class=\'chips\'><span class=\'chip on\'>%s</span>"\n        "<span class=\'chip\'>%s confidence</span>"\n        "<span class=\'chip\'>coverage: %s</span>%s</div>"\n        "<p>Our monitoring recorded <b>%d collisions</b> here on <b>%d "\n        "separate days</b> (%s to %s), %s. %s</p>"\n        "<div style=\'margin:14px 0\'><div class=\'kicker\'>Why it ranks "\n        "here</div>%s<p class=\'small\'>Four components, 25 points each: "\n        "<b>volume</b> relative to the busiest candidate, <b>recurrence</b> "\n        "across distinct days, <b>concentration</b> against comparable "\n        "locations, and <b>currency</b> — the share of collisions in the "\n        "last 30 days. A high currency score means the pattern is "\n        "live.</p></div>%s%s"\n        "<div class=\'kicker\' style=\'margin-top:14px\'>A professional review "\n        "should examine</div><ul>%s</ul>"\n        "<p class=\'small\' style=\'padding-top:10px;border-top:1px solid "\n        "var(--line2)\'>Screening signal only — not a determination of "\n        "cause, and not evidence that this location is defective. "\n        "Qualification basis: %s.</p></div>"\n        % (_esc(r["road"]), _esc(r["county"]), _esc(r["tier_label"]),\n           r["score"]["total"], _esc(r["tier_label"]),\n           _esc(r["confidence"]), _esc(r["coverage_band"]),\n           ("<span class=\'chip warn\'>Truck-involved</span>"\n            if r["truck_heavy"] else ""),\n           r["n"], r["days"], _esc(r["first"]), _esc(r["last"]),\n           _esc(_when(r)), _esc(intensity), _score_bar(r["score"]),\n           chart, geom, qs, _esc(r["tier_note"])))\n\n\ndef _coverage_caveat(records, coverage) -> str:\n    rows = []\n    for c in sorted({r["county"].split(" / ")[0] for r in records if\n                     r.get("county")}):\n        d = coverage.get(c) or {}\n        rows.append("<tr><td><b>%s</b></td><td>%s</td><td class=\'num\'>%s"\n                    "</td><td class=\'num\'>%s</td><td>%s</td></tr>"\n                    % (_esc(c), _esc(str(d.get("grade", "—"))),\n                       d.get("obs", "—"),\n                       ("%.0f" % d["exp"]) if d.get("exp") else "—",\n                       _esc(str(d.get("trend") or "stable"))))\n    if not rows:\n        return ""\n    return (ui.h2("Coverage", "How well we see these counties")\n            + "<div class=\'tbl-scroll\'><table><tr><th>County</th>"\n              "<th>Feed coverage grade</th><th class=\'num\'>Collisions "\n              "recorded</th><th class=\'num\'>Expected</th>"\n              "<th>Capture trend</th></tr>" + "".join(rows)\n            + "</table></div><p class=\'hint\'>Grades compare each county\'s "\n              "capture rate against similarly sized counties, so small "\n              "rural counties are not penalised for being small. A weaker "\n              "grade does not weaken the collisions we <i>did</i> record — "\n              "it means there are likely others we did not, so a county\'s "\n              "true concentration may be higher than shown here.</p>")\n\n\ndef write_reports(records, hist, outdir: str, degraded=None,\n                  coverage=None) -> None:\n    prof = profile(hist)\n    rd = readiness(hist, records)\n    with open(outdir + "/safety_watch_draft.html", "w") as f:\n        f.write(watch_html(records, hist, degraded, prof, rd,\n                           published=False))\n    with open(outdir + "/action_brief_draft.html", "w") as f:\n        f.write(brief_html(records, hist, degraded, prof, rd, coverage,\n                           published=False))\n'
for _p, _t in _FILES.items():
    with open(_p, 'w') as _f:
        _f.write(_t)

# Modules are now guaranteed-correct on disk; import and run.
import datetime as _dt
import importlib, sys
for _m in ('config','sources','memory','ledger','model','geo','ui','mapbuild','deploy','pubsafe'):
    if _m in sys.modules:
        importlib.reload(sys.modules[_m])
import config, deploy, geo, ledger, mapbuild, memory, model, pubsafe, sources, ui

def run(hours: int = 48, outdir: str = "output"):
    os.makedirs(outdir, exist_ok=True)
    print("Loading county opportunity table ...")
    counties = sources.load_counties()
    print("Fetching county boundaries ...")
    geodata = geo.fetch_indiana_geojson()
    centroids = sources.county_centroids(geodata, list(counties["county"]))
    print("Fetching weather for %d counties (one batched call) ..."
          % len(centroids))
    weather = sources.fetch_weather(hours, centroids)
    hist = memory.load()
    print("Fetching live incidents ...")
    incidents, live_events = sources.fetch_incidents(
        geodata, list(counties["county"]),
        tomtom_cache=hist.setdefault("_tomtom", {}))
    for _e in live_events:
        if not _e.get("road"):
            _e["road"] = sources.extract_road(
                f"{_e.get('type', '')} {_e.get('desc', '')}")
    degraded = _health_update(hist)
    before_ids = set(hist)
    hist = memory.update(hist, live_events)
    ledger.record(hist, [hist[i] for i in set(hist) - before_ids
                         if hist[i].get("category") == "crash"])
    memory.save(hist)
    live_ids = {memory.event_id(e) for e in live_events}
    import datetime as _dtm
    _stale_n = 0
    _now = config.local_now()
    for _e in live_events:  # show "first reported" on live map markers
        _h = hist.get(memory.event_id(_e))
        if _h:
            _e["first_seen"] = _h.get("first_seen", "")
            # Stale-crash cap (see config.CRASH_LIVE_MAX_H): a "crash"
            # still on the feed this long is a hygiene ghost, not risk.
            if _e.get("category") == "crash" and _e["first_seen"]:
                try:
                    _age_h = (_now - _dtm.datetime.fromisoformat(
                        _e["first_seen"])).total_seconds() / 3600
                except ValueError:
                    _age_h = 0.0
                if _age_h > config.CRASH_LIVE_MAX_H:
                    _old_w = float(_e.get("weight", 1.0))
                    _e["weight"] = _old_w * config.CRASH_STALE_WEIGHT
                    _e["stale_h"] = round(_age_h, 1)
                    _c = _e.get("county")
                    try:  # incidents was summed upstream; take back the diff
                        if _c and _c in incidents:
                            incidents[_c] = max(
                                incidents[_c] - (_old_w - _e["weight"]), 0.0)
                    except TypeError:
                        pass
                    _stale_n += 1
    if _stale_n:
        print(f"[info] {_stale_n} stale crash listing(s) older than "
              f"{config.CRASH_LIVE_MAX_H}h downweighted "
              f"x{config.CRASH_STALE_WEIGHT} (511 feed hygiene)")
    trail = memory.trailing(hist, live_ids)
    trailing_scores = memory.county_trailing_scores(trail)
    if trail:
        print(f"  {len(trail)} trailing incident(s) in memory "
              f"(top: {trail[0]['type']} in {trail[0]['county']}, "
              f"{trail[0]['age_h']:.0f}h ago, importance "
              f"{trail[0]['importance']:.2f})")

    print("Fetching commuter origin-destination data (Census LODES; "
          "~1-2 min first run) ...")
    flows = geo.fetch_flows()
    origins = geo.top_origins(flows, geodata)
    spill = geo.spill_matrix(flows, geodata, list(counties["county"]))
    if spill:
        hist["_flows"] = spill  # cached for runs where LODES is down
        memory.save(hist)
    else:
        spill = hist.get("_flows") or None
    if spill:
        print("[info] commuter spillover active: %d%% of each county's "
              "crash evidence spread to commuter home counties "
              "(%d counties, %d links)"
              % (round(config.SPILLOVER_FRAC * 100), len(spill),
                 sum(len(v) for v in spill.values())))
        incidents = ledger.apply_spill(dict(incidents), spill)
        trailing_scores = ledger.apply_spill(trailing_scores, spill)
    else:
        print("[info] commuter spillover off: no LODES flow matrix this "
              "run and no cached copy yet")
    opp = counties.set_index("county")["opportunity_score"]
    base_shares = (opp / opp.sum()).to_dict()
    baseline_tbl = ledger.load_baseline()
    if baseline_tbl:
        print(f"[info] official baseline crash table loaded: "
              f"{len(baseline_tbl)} counties")
    # coverage is computed BEFORE factors (v9.7) so the ledger factor can
    # correct for feed-instrumentation differences between counties
    if baseline_tbl:
        _btot = float(sum(v[1] for v in baseline_tbl.values())) or 1.0
        _exp_shares = {c: v[1] / _btot for c, v in baseline_tbl.items()}
    else:
        _exp_shares = base_shares
    coverage = ledger.coverage(hist, _exp_shares)
    _weak = sorted(c for c, d in coverage.items()
                   if d.get("grade") in ("D", "F"))
    if _weak:
        print("[info] feed coverage: %d county(ies) graded D/F — feeds "
              "see few of their expected crashes there: %s%s"
              % (len(_weak), ", ".join(_weak[:8]),
                 "…" if len(_weak) > 8 else ""))
    led_factors, led_meta = ledger.factors(hist, base_shares, spill=spill,
                                           coverage=coverage)
    official = ledger.official_factors(baseline_tbl, base_shares)
    if official:
        lo, hi = config.LEDGER_CAP
        led_factors = {c: round(min(max(
            official.get(c, 1.0) * led_factors.get(c, 1.0), lo), hi), 3)
            for c in set(official) | set(led_factors)}
        print(f"[info] official ARIES baseline adjusting "
              f"{len(official)} county baselines (blended with the "
              f"live-feed ledger, cap x{lo}-{hi})")
    if led_factors:
        print(f"[info] crash ledger: {led_meta['total']} crash(es) archived "
              f"since {str(led_meta['since'])[:10]} — county baselines "
              f"adjusted (cap x{config.LEDGER_CAP[0]}-{config.LEDGER_CAP[1]})")
    else:
        print(f"[info] crash ledger: {led_meta['total']} crash(es) archived "
              f"(learning phase; adjustments begin at "
              f"{config.LEDGER_MIN_TOTAL} statewide)")
    hotspots = ledger.hotspots(hist)
    segments = ledger.segments(hist)
    if segments:
        print("[info] %d risky corridor segment(s): %s"
              % (len(segments),
                 "; ".join(f"{s['road']} {s['km']}km n={s['n']}"
                           for s in segments[:4])))
    if hotspots:
        print("[info] %d crash hotspot segment(s) on the map (>= %d "
              "archived crashes within ~400 m)"
              % (len(hotspots), config.HOTSPOT_MIN_N))
    scores, hourly = model.score(counties, weather, incidents, hours,
                                 trailing_scores, led_factors)
    prio, eff = deploy.load_phase2()
    shares = deploy.budget_shares(scores)
    targets = deploy.county_targets(scores)
    mix = deploy.cluster_mix(eff)
    parts = deploy.daypart(hourly, scores)

    scores.to_csv(f"{outdir}/county_risk.csv", index=False)
    targets.to_csv(f"{outdir}/county_targets.csv", index=False)
    shares.to_csv(f"{outdir}/budget_shares.csv", index=False)
    mix.to_csv(f"{outdir}/cluster_mix.csv", index=False)
    parts.to_csv(f"{outdir}/dayparting.csv", index=False)
    # Only crashes get markers: live ones filtered in-page via
    # MAP_MIN_MARKER_WEIGHT, recent ones filtered here from trailing
    # memory. Every event still shades its county and is itemized in
    # its panel.
    truck = dict(ledger.truck_badges(hist, baseline_tbl))
    for c in config.TRUCK_COUNTIES_MANUAL:
        truck.setdefault(c, "designated from firm case history")
    if truck:
        print(f"[info] truck-prone counties: {sorted(truck)}")
    prev = hist.get("_adops") or {}
    archive_profile = pubsafe.profile(hist)
    ops_html, snap = deploy.ad_ops_html(
        scores, shares, mix, parts,
        {"truck": truck}, hours, prev,
        coverage=coverage, hotspots=hotspots, segments=segments,
        spillover=bool(spill),
        degraded=degraded, insights=ledger.insights(hist),
        profile=archive_profile)
    with open(f"{outdir}/ad_ops.html", "w") as f:
        f.write(ops_html)
    if snap is not None:
        hist["_adops"] = snap
        memory.save(hist)
    print("[info] ad ops sheet written: %s/ad_ops.html (movers vs %s)"
          % (outdir, (prev.get("date","")[:10] or "first snapshot")))
    pub = pubsafe.qualified(hist, coverage)
    pubsafe.write_reports(pub, hist, outdir, degraded=degraded,
                          coverage=coverage)
    _rd = pubsafe.readiness(hist, pub)
    print("[info] public safety drafts written: %d qualified location(s) "
          "(%d spot / %d corridor / %d route-wide) -> "
          "%s/safety_watch_draft.html + action_brief_draft.html"
          % (len(pub), _rd["by_tier"]["spot"], _rd["by_tier"]["corridor"],
             _rd["by_tier"]["road"], outdir))
    if not pub:
        print("[info] no qualifying locations: verdict=%s (archive %d, "
              "%d in window). 'no_pattern' means the archive is ample and "
              "nothing is recurring — that is a finding, not a shortage."
              % (_rd["verdict"], _rd["archive_total"], _rd["windowed"]))
    crash_trail = [e for e in trail
                   if e.get("category") == "crash"
                   or (not e.get("category") and sources.classify_event(
                       f"{e.get('type', '')} {e.get('desc', '')}")[1]
                       >= config.MAP_MIN_MARKER_WEIGHT)]
    mapbuild.build_map(scores, geodata, origins,
                       badges={"truck": truck},
                       path=f"{outdir}/risk_map.html", hours=hours,
                       trail=crash_trail, live=live_events,
                       hotspots=hotspots, segments=segments,
                       coverage=coverage,
                       degraded=degraded)

    print("\n=== Blended budget shares (next %d h) ===" % hours)
    print(shares.to_string(index=False))
    print("\n=== Top 10 counties ===")
    print(targets.head(10).to_string(index=False))
    print(f"\nOutputs written to ./{outdir} (open risk_map.html).")
    return scores, shares, targets, mix, parts


def _health_update(hist) -> str | None:
    """Append this run's source status to hist['_health'] (ring buffer)
    and return the timestamp 511 went silent if the last DEGRADED_AFTER
    runs all failed, else None."""
    hl = hist.setdefault("_health", [])
    hl.append({"t": config.local_now().isoformat(timespec="seconds"),
               **dict(sources.LAST_STATUS)})
    del hl[:-config.HEALTH_MAX]
    recent = hl[-config.DEGRADED_AFTER:]
    if (len(recent) >= config.DEGRADED_AFTER
            and all(h.get("g511", -1) == -1 for h in recent)):
        since = recent[0]["t"]
        print(f"[warn] DEGRADED MODE: 511 feed silent for "
              f"{config.DEGRADED_AFTER}+ consecutive runs (since {since}) "
              f"— live layer unreliable; automated spend changes should "
              f"be frozen", file=sys.stderr)
        return since
    return None


def poll_only(loop: bool = False):
    """Lightweight incident-only poll: 511 -> incident_history.json and
    exit. No TomTom (protects its daily request quota), no weather, no
    map. Run every 5 minutes between full builds so short-lived crash
    reports get captured into trailing memory instead of being missed.

    loop=True (--poll-loop): keep sweeping 511 every
    config.POLL_LOOP_INTERVAL seconds until config.POLL_LOOP_SECONDS
    elapse — sub-cron sampling inside one Actions job, sized to hand
    the runner back before the next scheduled job. History is saved
    after every sweep, so a mid-loop crash or runner eviction keeps
    everything captured up to that point (the workflow's commit step
    picks up whatever the last save wrote)."""
    import time as _time
    counties = sources.load_counties()
    geodata = geo.fetch_indiana_geojson()
    hist = memory.load()
    _health_update(hist)
    deadline = _time.monotonic() + config.POLL_LOOP_SECONDS
    sweep = 0
    while True:
        sweep += 1
        _, live_events = sources.fetch_incidents(
            geodata, list(counties["county"]), include_tomtom=False)
        for _e in live_events:
            if not _e.get("road"):
                _e["road"] = sources.extract_road(
                    f"{_e.get('type', '')} {_e.get('desc', '')}")
        before_ids = set(hist)
        hist = memory.update(hist, live_events)
        new_crashes = [hist[i] for i in set(hist) - before_ids
                       if hist[i].get("category") == "crash"]
        ledger.record(hist, new_crashes)
        memory.save(hist)
        crashes = sum(1 for e in live_events
                      if e.get("category") == "crash")
        print(f"[info] poll{f'-loop sweep {sweep}' if loop else '-only'}: "
              f"{len(live_events)} live event(s), "
              f"{crashes} crash(es), {len(new_crashes)} new to the ledger; "
              f"history {len(before_ids)} -> {len(hist)} entries")
        if (not loop or _time.monotonic() + config.POLL_LOOP_INTERVAL
                >= deadline):
            break
        _time.sleep(config.POLL_LOOP_INTERVAL)


if __name__ == "__main__":
    ap = argparse.ArgumentParser()
    ap.add_argument("--hours", type=int, default=48)
    ap.add_argument("--poll-only", action="store_true",
                    help="511-only incident poll; update history and exit")
    ap.add_argument("--poll-loop", action="store_true",
                    help="like --poll-only, but sweeps 511 every "
                         "~POLL_LOOP_INTERVAL s for ~POLL_LOOP_SECONDS "
                         "(sub-cron sampling inside one Actions job)")
    args = ap.parse_args()
    if args.poll_only or args.poll_loop:
        poll_only(loop=args.poll_loop)
    else:
        run(args.hours)
